Let $\left(\rho^{(1)},\ldots,\rho^{(d)}\right),\left(\sigma^{(1)},\ldots,\sigma^{(d)}\right)$ be two tuples of states in $S$. If for all divergences $D$, 
    \begin{equation}\label{eq:informaltheoremcompare}
        D\left(\rho^{(1)},\ldots,\rho^{(d)}\right)>D\left(\sigma^{(1)},\ldots,\sigma^{(d)}\right), 
    \end{equation}
    then 
    \begin{enumerate}[(a)]
        \item there exist a channel $\mathcal{C}$ and catalyst states $\left(\tau^{(1)},\ldots,\tau^{(d)}\right)$ such that\\
        for $k=1,\ldots,d$,         
        \begin{equation}
            \mathcal{C}\left(\tau^{(k)}\otimes\rho^{(k)}\right)=\tau^{(k)}\otimes\sigma^{(k)}, 
        \end{equation}
        \item for sufficiently large $n$, there exists a channel $\mathcal{C}_n$ such that for $k=1,\ldots,d$, 
        \begin{equation}
            \mathcal{C}_n\left(\left(\rho^{(k)}\right)^{\otimes n}\right)=\left(\sigma^{(k)}\right)^{\otimes n}. 
        \end{equation}
    \end{enumerate}
    Conversely, if either (a) or (b) holds, then also \eqref{eq:informaltheoremcompare} holds for all divergences $D$ with non-strict inequality $\geq$ instead of $>$.

Let $\mathcal{H}$ be a finite-dimensional linear space and $A,B$ projections in $\mathcal{H}$ (i.e. two operators on $\mathcal{H}$ such that $A^2=A=A^*$, $B^2=B=B^*$). Then $A,B$ can be simultaneously block-diagonalized with blocks of dimension $1$ or $2$. In the case of dimension $2$, the corresponding blocks in $A,B$ have rank $1$. More precisely, there exists a decomposition $\mathcal{H}=\bigoplus_{i=1}^n\mathcal{H}_i$, for some $n\geq1$, where the $\mathcal{H}_i$ are at most $2$ dimensional linear spaces, such that 
    \begin{equation}\label{eq:Jordanform}
        A=\bigoplus_{i=1}^n A_i,\quad B=\bigoplus_{i=1}^n B_i, 
    \end{equation}
    where the $A_i$, $B_i$ are projections of rank at most $1$ in $\mathcal{H}_i$.

\label{thm:Fritz2022}
Let $S$ be a zerosumfree preordered semidomain with a power universal element $u$. Assume that for some $d\in\mathbb{N}$ there is a surjective homomorphism (called the \emph{norm}) $\|\cdot\|:S\to\mathbb{R}_{>0}^d\cup\{(0,\ldots,0)\}$\footnote{Note that $\mathbb{R}_{>0}^d\cup\{(0,\ldots,0)\}$ with component-wise addition and multiplication forms a semiring.} with trivial kernel and such that
\begin{equation}\label{eq:surjectivehomomorphismproperties}
a\succeq b\ \Rightarrow\ \|a\|=\|b\|\quad {\rm and} \quad \|a\|=\|b\|\ \Rightarrow\ a\sim b.
\end{equation}
Denote the component homomorphisms of $\|\cdot\|$ by $\|\cdot\|_{(j)}$, $j=1,\ldots,d$. Let $x,y\in S\setminus\{0\}$ with $\|x\|=\|y\|$. If 
\begin{enumerate}[(i)]
\item for every $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$ and every non-degenerate monotone homomorphism $\Phi : S \to \mathbb{K}$ with trivial kernel, we have $\Phi(x) > \Phi(y)$, and
\item $\Delta(x) > \Delta(y)$ for every monotone $\|\cdot\|_{(j)}$-derivation\footnote{\label{ftn:interchangeability}In fact, this inequality only has to be verified for every derivation up to interchangeability: two derivations of some degenerate monotone homomorphism are called \emph{interchangeable} if their difference takes a (possibly different) constant value on every equivalence class of the relation $\sim$.} $\Delta : S \to \mathbb{R}$ with $\Delta(u) = 1$ for all component indices $j = 1,\ldots,d$,
\end{enumerate}
then
\begin{enumerate}
\item[(a)] there exists a nonzero $a\in S$ such that $ax\succeq ay$, and 
\item[(b)] if additionally $x$ is power universal, then $x^n \succeq y^n$ for all sufficiently large $n\in\mathbb{N}$. 
\end{enumerate}
Conversely, if either of these properties (a) or (b) holds for any $n$ or $a$, then the inequalities (i) and (ii) hold non-strictly.

\label{prop:optimalconversionrate}
    Consider a preordered semiring $S$ as in Theorem \ref{thm:Fritz2022}, with associated divergences $\mathcal{D}(S)$. Let $x,y\in S$, where $x$ is power universal, satisfy $x,y\succeq1$ and $D(x)>0$ for all $D\in\mathcal{D}(S)$. The optimal rate of conversion is given by 
    \begin{equation}\label{eq:optimalrategeneral}
        r(x\to y)=\min_{D\in\mathcal{D}(S)}\frac{D(x)}{D(y)}. 
    \end{equation}

We first show that 
    \begin{equation}\label{eq:upperboundrate}
        r(x\to y)\leq\min_{D\in\mathcal{D}(S)}\frac{D(x)}{D(y)}. 
    \end{equation}
    The proof for this is completely standard and does not use the fact that the divergences in $\mathcal{D}(S)$ characterize large-sample ordering. Let $D\in\mathcal{D}(S)$, and $r$ an achievable rate, i.e. there exists a sequence of natural numbers $(m_n)_{n=1}^\infty$ such that $x^n\succeq y^{m_n}$ for $n$ large enough and $r\leq\liminf_{n\rightarrow\infty}m_n/n$. By monotonicity of $D$, we have $D(x^n)\geq D(y^{m_n})$ for $n$ large enough. Then by additivity this implies that $m_n/n\leq D(x)/D(y)$ for $n$ large enough, where we note that $D(x)/D(y)$ may be infinite. Therefore, 
    \begin{equation}
        r\leq\liminf_{n\rightarrow\infty}\frac{m_n}{n}\leq\frac{D(x)}{D(y)}. 
    \end{equation}
    By taking the supremum over all achievable rates $r$ and then the minimum over all $D\in\mathcal{D}(S)$, we arrive at \eqref{eq:upperboundrate}. 

    Next, using Theorem \ref{thm:Fritz2022}, we prove that any $r<\min_{D\in\mathcal{D}(S)}D(x)/D(y)$ is an achievable rate. Together with \eqref{eq:upperboundrate}, this implies \eqref{eq:optimalrategeneral}. Consider any $r<\min_{D\in\mathcal{D}(S)}D(x)/D(y)$ and let $p,q\in\mathbb{N}$ be such that 
    \begin{equation}
        r\leq\frac{p}{q}<\min_{D\in\mathcal{D}(S)}\frac{D(x)}{D(y)}. 
    \end{equation}
    From this, it follows that $qD(x)>pD(y)$ for any $D\in\mathcal{D}(S)$. Then, by additivity, 
    \begin{equation}
        D(x^q)=qD(x)>pD(y)=D(y^p). 
    \end{equation}
    Note that since $x$ is power universal and $x\succeq1$, $x^q$ is also power universal. It now follows from Theorem \ref{thm:Fritz2022} that $x^{nq}\succeq y^{np}$ for all $n$ larger than or equal to some $n_0\in\mathbb{N}$. Any $k\in\mathbb{N}$ can be written as $k=n_kq+l_k$ with unique $n_k\in\mathbb{N}$ and $l_k\in\{0,\ldots,q-1\}$. This allows us to define $m_k:=n_kp$. Then, using that $x\succeq1$, we have for $k\geq n_0q$, 
    \begin{equation}
        x^k=x^{n_kq+l_k}=x^{n_kq}x^{l_k}\succeq x^{n_kq}\succeq y^{n_kp}=y^{m_k}. 
    \end{equation}
    Also, 
    \begin{equation}
        \liminf_{k\rightarrow\infty}\frac{m_k}{k}=\liminf_{k\rightarrow\infty}\frac{p}{q+l_k/n_k}=\frac{p}{q}\geq r. 
    \end{equation}
    This establishes that $r$ is an achievable rate.

\label{Mlem:1or2}
Let $B\subseteq[d]$, and $\Phi:S^d\to\mathbb{K}$ a monotone homomorphism for some $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$. Then the following holds: 
\begin{enumerate}[(i)]
\item We have 
\begin{equation}
\label{Meq:1or2}
\Phi[B]=\left\{\begin{array}{ll}
1\text{ or }2&\text{if}\quad\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op}\}\\
1&\text{if}\quad\mathbb{K}\in\{\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}
\end{array}\right.. 
\end{equation}
\item Suppose that $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op}\}$ and that $\Phi$ is associated with $\underline{\alpha}=(\alpha_1,\ldots,\alpha_d)\in A_+\cup A_-$. If $\Phi[B]$ equals $2$, then $\alpha_k=0$ for all $k\notin B$. 
\end{enumerate}

To prove (i), notice 
\begin{align}
&\left(\begin{array}{ccc}
1&\cdots&1\\
&B&
\end{array}\right)^{\boxtimes2}\boxplus\left(\begin{array}{ccc}
1&\cdots&1\\
1&\cdots&1
\end{array}\right)&\label{Meq:basicmatrixequation1}\\
&\qquad\qquad=\left(\begin{array}{ccc}
1&\cdots&1\\
&B&
\end{array}\right)\boxplus\left(\begin{array}{ccc}
1&\cdots&1\\
&B&
\end{array}\right)\boxplus\left(\begin{array}{ccc}
1&\cdots&1\\
&B&
\end{array}\right).&\label{Meq:basicmatrixequation2}
\end{align}
Using additivity and multiplicativity of $\Phi$, and the fact that we know that $\Phi$ evaluated on single rows with only positive entries is given by \eqref{Meq:singlerowfunction}, the above equality, for $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op}\}$, yields the equation 
\begin{equation}
\left(\Phi[B]\right)^2+2=3\Phi[B], 
\end{equation}
and for $\mathbb{K}\in\{\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$, yields the equation 
\begin{equation}
\max\left\{\left(\Phi[B]\right)^2,1\right\}=\Phi[B]. 
\end{equation}
The solutions to the first equation are $1$ and $2$, and to the second the unique solution is $1$, proving \eqref{Meq:1or2}. 

To prove (ii), define the numbers $x_k$ coinciding with $2$ when $k\in B$ and otherwise $x_k=1$ and $y_k$ coinciding with $2$ when $k\in B$ and otherwise $y_k=0$. Denoting by $\substack{\succeq\\\preceq}$ majorization in both directions simultaneously, we have
\begin{align}
&\left(\begin{array}{ccc}
1&\cdots&1\\
&B&
\end{array}\right)\boxplus\left(\begin{array}{ccc}
1&\cdots&1\\
&B&
\end{array}\right)\boxplus (x_1\,\cdots\,x_d)&\\
&\qquad\qquad\substack{\succeq\\\preceq}\left(\begin{array}{ccc}
x_1&\cdots&x_d\\
y_1&\cdots&y_d
\end{array}\right)\boxplus\left(\begin{array}{ccc}
1&\cdots&1\\
1&\cdots&1
\end{array}\right),&
\end{align}
where the LHS majorizes the RHS because there is a stochastic matrix that adds the two rows $(\;B\;)$ to obtain the row $(y_1\,\cdots\,y_d)$, and the RHS majorizes the LHS because there is a stochastic matrix that splits the row $(y_1\,\cdots\,y_d)$ into two copies of the row $(\;B\;)$. Next, notice that the RHS is equal to
\begin{equation}
\label{Meq:1or2b}
    (x_1\,\cdots\,x_d)\boxtimes\left(\begin{array}{ccc}
        1&\cdots&1\\
        &B&
    \end{array}\right)\boxplus\left(\begin{array}{ccc}
        1&\cdots&1\\
        1&\cdots&1
    \end{array}\right). 
\end{equation}
This yields the equation 
\begin{equation}
2+2+2^{\sum_{k\in B}\alpha_k}=2^{\sum_{k\in B}\alpha_k}\cdot2+2, 
\end{equation}
where we used the monotonicity, additivity and multiplicativity of $\Phi$, and the single-row function given by \eqref{Meq:singlerowfunction} above. Therefore, $\sum_{k\in B}\alpha_k=1$. This implies $\alpha_k=0$ for all $k\notin B$, where for the case $\mathbb{K}=\mathbb{R}_+$ we use the fact that $\underline{\alpha}\in A_-$ and therefore only one of the coordinates $\alpha_k$ is positive.

\label{Mclm:nontrivialB}
Fix a monotone homomorphism $\Phi:S^d\to\mathbb{K}$ for $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op}\}$. Let $B_1,B_2\subseteq[d]$. The following holds: 
\begin{enumerate}[(i)]
\item If $B_1$ and $B_2$ are $\Phi$-nontrivial, then $B_1\cap B_2$ is also $\Phi$-nontrivial. 
\item If $B_1\subseteq B_2$ and $B_1$ is $\Phi$-nontrivial, then $B_2$ is also $\Phi$-nontrivial. 
\end{enumerate}

For the proof of (i), assume that $B_1$ and $B_2$ are $\Phi$-nontrivial. Notice 
\begin{equation}
\left(\begin{array}{ccc}
1&\cdots&1\\
1&\cdots&1
\end{array}\right)\boxplus\left(\begin{array}{ccc}
1&\cdots&1\\
&B_1&
\end{array}\right)\boxtimes\left(\begin{array}{ccc}
1&\cdots&1\\
&B_2&
\end{array}\right)=\left(\begin{array}{ccc}
1&\cdots&1\\
1&\cdots&1\\
1&\cdots&1\\
&B_1&\\
&B_2&\\
&B_1\cap B_2&
\end{array}\right). 
\end{equation}
This yields 
\begin{equation}
2+\Phi[B_1]\Phi[B_2]=\Phi[B_1]+\Phi[B_2]+\Phi[B_1\cap B_2]. 
\end{equation}
Since $\Phi[B_1]=2=\Phi[B_2]$, we conclude that $\Phi[B_1\cap B_2]=2$, hence $B_1\cap B_2$ is $\Phi$-nontrivial. 

Next, for the proof of (ii), assume that $B_1$ is $\Phi$-nontrivial. Notice 
\begin{equation}
\left(\begin{array}{ccc}
1&\cdots&1\\
1&\cdots&1
\end{array}\right)\boxplus\left(\begin{array}{ccc}
1&\cdots&1\\
&B_1&
\end{array}\right)\boxtimes\left(\begin{array}{ccc}
1&\cdots&1\\
&B_2&
\end{array}\right)=\left(\begin{array}{ccc}
1&\cdots&1\\
1&\cdots&1\\
1&\cdots&1\\
&B_1&\\
&B_2&\\
&B_1&
\end{array}\right). 
\end{equation}
This yields 
\begin{equation}
2+\Phi[B_1]\Phi[B_2]=2\Phi[B_1]+\Phi[B_2]. 
\end{equation}
Since $\Phi[B_1]=2$, we conclude that $\Phi[B_2]=2$, hence $B_2$ is $\Phi$-nontrivial.

Let us first consider the case $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op}\}$ and fix a monotone homomorphism $\Phi:S^d\to\mathbb{K}$. Let $\underline{\alpha}=(\alpha_1,\ldots,\alpha_d)\in A_+\cup A_-$ be the parameter vector which $\Phi$ is associated with and $C\subseteq[d]$ be the character of $\Phi$.                                             



































For any $x\in\mathbb{R}_+^d$, denote by $\tilde{x}\in\mathbb{R}_{>0}^d$ the vector obtained from $x$ by replacing all vanishing entries with $1$. We now extend the domain $\mathbb{R}_{>0}^d\cup\{(0,\ldots,0)\}$ of the map $\varphi$ defined at the beginning of subsection \ref{Msubsec:monotonehomomorphisms} to $\mathbb{R}_+^d$ through
\begin{equation}
\varphi(x):=\Phi\big(\tilde{x}^T\boxplus x^T\big)-\varphi(\tilde{x})
\end{equation}
for all $x\in\mathbb{R}_+^d$. Note that for $x=(x_1,\ldots,x_d)\in\mathbb{R}_+^d$, the vector $\tilde{x}$ has no vanishing entries, and hence 
\begin{equation}
\varphi(\tilde{x})=\prod_{k\in{\rm supp}\,x}x_k^{\alpha_k}. 
\end{equation}
We see that $\varphi$ coincides with its earlier definition on vectors in $\mathbb{R}_{>0}^d\cup\{(0,\ldots,0)\}$. Now we have, for all $x=(x_1,\ldots,x_k)\in\mathbb{R}_+^d$,
\begin{align}
\varphi(x)&=\Phi\big(\tilde{x}^T\boxplus x^T\big)-\varphi(\tilde{x})=\Phi\left(\tilde{x}^T\boxtimes\left(\begin{array}{ccc}
1&\cdots&1\\
&{\rm supp}\,x&
\end{array}\right)\right)-\varphi(\tilde{x})\label{Meq:Phihajotus1}\\
&=\varphi(\tilde{x})\left(\Phi\left(\begin{array}{ccc}
1&\cdots&1\\
&{\rm supp}\,x&
\end{array}\right)-1\right)=\varphi(\tilde{x})\big(\Phi[{\rm supp}\,x]-1\big)\label{Meq:Phihajotus2}\\
&=\left\{\begin{array}{ll}
\varphi(\tilde{x})&C\subseteq {\rm supp}\,x\\
0&{\rm otherwise}
\end{array}\right.,\label{Meq:Phihajotus3}
\end{align}
where the last equality is due to the fact that $\Phi[B]=2$ if and only if $C\subseteq B$ and $\Phi[B]=1$ otherwise.

Let $P=\big(p^{(1)},\ldots,p^{(d)}\big)\in\mathcal{V}^d$, $p^{(k)}=\big(p^{(k)}_1,\ldots,p^{(k)}_n\big)$ for $k=1,\ldots,d$. Define $p_i:=\big(p^{(1)}_i,\ldots,p^{(d)}_i\big)$ for $i=1,\ldots,n$. We may write
\begin{align}
\Phi(P)&=\Phi\left(\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i=1}^n p_i^T\right)=\Phi\left(\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i=1}^n \big(\tilde{p}_i^T\boxplus p_i^T\big)\right)-\sum_{i=1}^n\varphi(\tilde{p}_i)\label{Meq:PhisumsCrowsa}\\
&=\sum_{i=1}^n\left(\Phi\big(\tilde{p}_i^T\boxplus p_i^T\big)-\varphi(\tilde{p}_i)\right)=\sum_{i=1}^n \varphi(p_i)\label{Meq:PhisumsCrowsb}\\
&=\sum_{i:\,C\subseteq{\rm supp}\,p_i}\prod_{k\in{\rm supp}\,p_i}\big(p^{(k)}_i\big)^{\alpha_k}.\label{Meq:PhisumsCrowsc}
\end{align}
It follows from Lemma \ref{Mlem:1or2}(ii) that if $k\notin C$, then $\alpha_k=0$. 

Thus, the form of $\Phi$ is the same as those in $\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}^{\rm op}_+)$ but with $\underline{\alpha}$ not necessarily in $A_+$. We already know that those within $\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$ are monotone in the case $\mathbb{K}=\mathbb{R}_+^{\rm op}$. We know from \cite{farooq2024} that, if $\underline{\alpha}\in A_-\setminus\{e_1,\ldots,e_d\}$, then $\Phi$ is monotone in the case $\mathbb{K}=\mathbb{R}_+$ when restricted on matrices whose columns have common support. Thus, in the case $\mathbb{K}=\mathbb{R}_+^{\rm op}$, the nondegenerate monotone homomorphisms are exactly those in $\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}^{\rm op})$. We next show that there are actually no nondegenerate monotone homomorphisms in the case $\mathbb{K}=\mathbb{R}_+$.


































































































































Assume $\mathbb{K}=\mathbb{R}_+$. It follows from \eqref{Meq:PhisumsCrowsa}, \eqref{Meq:PhisumsCrowsb} and \eqref{Meq:PhisumsCrowsc} that 
\begin{equation}\label{Meq:Phisinglex}
\Phi\left(\begin{array}{ccccccc}
1&\cdots&1&1&1&\cdots&1\\
0&\cdots&0&\smash{\underbrace{x}_{k\text{-th entry}}}&0&\cdots&0
\end{array}\right) 
\vspace{0.5cm}
\end{equation}
equals either $1+x$ or $1$ for all $x\geq0$ depending on whether $C=\{k\}$, respectively $C\neq\{k\}$. Furthermore, in the former case, \eqref{Meq:Phisinglex} equals $1$ for all other $k^\prime\neq k$, and since $k^\prime\notin C$, $\alpha_{k^\prime}=0$ for all $k^\prime\neq k$, and hence $\alpha_k=1$. 





























Let $P=(p^{(1)},\ldots,p^{(d)})\in\mathcal{V}_n^d$. Notice the following inequalities, which follow from monotonicity, and for the second inequality by inserting a row of $1$'s for every non-zero entry in $P$ and putting every entry on its own row: 
\begin{align}
&\Phi(\|p^{(1)}\|_1\;\cdots\;\|p^{(d)}\|_1)\leq\Phi(P)&\label{Meq:Phiis01}\\
&\qquad\qquad\leq\sum_{i=1}^n\sum_{k=1}^d\left(\Phi\left(\begin{array}{ccccccc}
1&\cdots&1&1&1&\cdots&1\\
0&\cdots&0&\smash{\underbrace{p_i^{(k)}}_{k\text{-th entry}}}&0&\cdots&0 
\end{array}\right)-1\right).&\label{Meq:Phiis02}
\end{align}
Assume \eqref{Meq:Phisinglex} equals $1+x$ for some $k$. Then it equals $1$ for all $k^\prime\neq k$, and the RHS equals $\|p^{(k)}\|_1$. Also, since in this case $\alpha_k=1$ and $\alpha_{k^\prime}=0$ for all $k^\prime\neq k$, the LHS is equal to $\|p^{(k)}\|_1$. Hence $\Phi(P)=\|p^{(k)}\|_1$ for all $P$, meaning that $\Phi$ is degenerate. Assume \eqref{Meq:Phisinglex} equals $1$ for all $k$. Then it follows from the second inequality in \eqref{Meq:Phiis01}, \eqref{Meq:Phiis02} that $\Phi(P)=0$ for all $P$, which is not possible. In conclusion, no non-degenerate monotone homomorphism $S^d\to\mathbb{R}_+$ exists. 

Next, we consider the cases $\mathbb{K}$ equal to $\mathbb{T}\mathbb{R}_+$ or $\mathbb{T}\mathbb{R}_+^{\rm op}$. Let $\Phi:S^d\to\mathbb{K}$, where $\mathbb{K}\in\{\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$, be a non-degenerate monotone homomorphism, and $\underline{\beta}=(\beta_1,\ldots,\beta_d)\in B$ the parameter vector which $\Phi$ is associated with. 



















































Let $\ell\in[d]$ and define $B_\ell:=\{\ell\}$ and $x^{(\ell)}:=(0,\ldots,x,\ldots,0)$ for some $x>0$. Then it follows from Lemma \ref{Mlem:1or2}(i) that 
\begin{align}
\Phi\big(\big(\widetilde{x^{(\ell)}}\big)^T\boxplus \big(x^{(\ell)}\big)^T\big)&=\Phi\left(\big(\widetilde{x^{(\ell)}}\big)^T\boxtimes\left(\begin{array}{ccc}
1&\cdots&1\\
&B_\ell&
\end{array}\right)\right)\\
&=\Phi\big((\widetilde{x^{(\ell)}}\big)^T)\Phi[B_\ell]=\Phi\big((\widetilde{x^{(\ell)}}\big)^T). 
\end{align}

Consider now the case $\mathbb{K}=\mathbb{T}\mathbb{R}_+$. Let $P\in\mathcal{V}_n^d$, $P\neq0$. By inserting rows of $1$'s and placing each non-zero entry in $P$ on its own row, we have 
\begin{align}
&P\boxplus\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i,k\,:\,p_i^{(k)}>0}(1\,\cdots\,1\,p_i^{(k)}\,1\,\cdots\,1)&\\
&\qquad\preceq\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i,k\,:\,p_i^{(k)}>0}\left(\begin{array}{ccccccc}
1&\cdots&1&p_i^{(k)}&1&\cdots&1\\[0.1cm]
0&\cdots&0&\smash{\underbrace{p_i^{(k)}}_{k\text{-th entry}}}&0&\cdots&0 
\end{array}\right).&
\vspace{0.5cm}
\end{align}
Assume all $\beta_k=0$.	Then from the majorization above and the fact that we know the value of $\Phi$ on single rows \eqref{Meq:singlerowfunction} it follows that 
\begin{equation}
\Phi(P)\leq\max\{\Phi(P),1\}\leq1. 
\end{equation}
Since also $1=\Phi(\|p^{(1)}\|_1\;\cdots\;\|p^{(d)}\|_1)\leq\Phi(P)$, we find that $\Phi(P)=1$. Hence $\Phi$ is degenerate, which leads to a contradiction. Thus there exists $k$ such that $\beta_k>0$. Note that 
\begin{align}
&\left(\begin{array}{cc}
1&\frac{1}{2}\\[0.1cm]
0&\frac{1}{2}
\end{array}\right)\left(\begin{array}{ccccccc}
\frac{3}{2}&\cdots&\frac{3}{2}&1&\frac{3}{2}&\cdots&\frac{3}{2}\\[0.1cm]
0&\cdots&0&\smash{\underbrace{1}_{k\text{-th entry}}}&0&\cdots&0
\end{array}\right)&\\\nonumber\\
&\qquad\qquad=\left(\begin{array}{ccccccc}
\frac{3}{2}&\cdots&\frac{3}{2}&\frac{3}{2}&\frac{3}{2}&\cdots&\frac{3}{2}\\[0.1cm]
0&\cdots&0&\smash{\underbrace{\textstyle\frac{1}{2}}_{k\text{-th entry}}}&0&\cdots&0
\end{array}\right).&
\end{align}
Using this and the fact that $\sum_{k^\prime\neq k}\beta_{k^\prime}<0$ it follows that
\begin{align}\label{Meq:tropicalhomomorphismcontradiction}
1&>\left(\frac{3}{2}\right)^{\sum_{k^\prime\neq k}\beta_{k^\prime}}\\
&=\Phi\bigg(\left(\frac{3}{2}\;\cdots\;\frac{3}{2}\;\smash{\underbrace{1}_{k\text{-th entry}}}\;\frac{3}{2}\;\cdots\;\frac{3}{2}\right)\\\nonumber\\
&\qquad\qquad\boxtimes\left(\begin{array}{ccccccc}
1&\cdots&1&1&1&\cdots&1\\[0.1cm]
0&\cdots&0&\smash{\underbrace{1}_{k\text{-th entry}}}&0&\cdots&0
\end{array}\right)\bigg)\\\nonumber\\
&=\Phi\left(\begin{array}{ccccccc}
\frac{3}{2}&\cdots&\frac{3}{2}&1&\frac{3}{2}&\cdots&\frac{3}{2}\\[0.1cm]
0&\cdots&0&\smash{\underbrace{1}_{k\text{-th entry}}}&0&\cdots&0
\end{array}\right)\\\nonumber\\
&\geq\Phi\left(\begin{array}{ccccccc}
\frac{3}{2}&\cdots&\frac{3}{2}&\frac{3}{2}&\frac{3}{2}&\cdots&\frac{3}{2}\\[0.1cm]
0&\cdots&0&\smash{\underbrace{\textstyle\frac{1}{2}}_{k\text{-th entry}}}&0&\cdots&0
\end{array}\right)\\\nonumber\\
&=\Phi\left(\left(\frac{3}{2}\;\cdots\;\frac{3}{2}\right)\boxtimes\left(\begin{array}{ccccccc}
1&\cdots&1&1&1&\cdots&1\\[0.1cm]
0&\cdots&0&\smash{\underbrace{\textstyle\frac{1}{3}}_{k\text{-th entry}}}&0&\cdots&0
\end{array}\right)\right)\\\nonumber\\
&\geq\Phi\left(\frac{3}{2}\;\cdots\;\frac{3}{2}\right)\Phi\left(1\;\cdots\;1\;\smash{\underbrace{\textstyle\frac{4}{3}}_{k\text{-th entry}}}\;1\;\cdots\;1\right)=\left(\frac{4}{3}\right)^{\beta_k}>1, \\\nonumber
\end{align}
which leads to a contradiction. We conclude that no non-degenerate monotone homomorphism $S^d\to\mathbb{T}\mathbb{R}_+$ exists. 

Finally, consider the case $\mathbb{K}=\mathbb{T}\mathbb{R}_+^{\rm op}$. Let $P\in\mathcal{V}_n^d$, $P\neq0$. $P$ has at least one row not containing any $0$. Assume WLOG it is the first row. Then 
\begin{equation}
P\preceq\left(\begin{array}{ccc}
p_1^{(1)}/2&\cdots&p_1^{(d)}/2\\
p_1^{(1)}/2&\cdots&p_1^{(d)}/2\\
p_2^{(1)}&\cdots&p_2^{(d)}\\
\vdots&\vdots&\vdots\\
p_n^{(1)}&\cdots&p_n^{(d)}
\end{array}\right), 
\end{equation}
hence
\begin{equation}
\Phi(P)\geq\max\left\{\Phi\left(p_1^{(1)}/2\;\cdots\;p_1^{(d)}/2\right),\Phi\left(\begin{array}{ccc}
p_1^{(1)}/2&\cdots&p_1^{(d)}/2\\
p_2^{(1)}&\cdots&p_2^{(d)}\\
\vdots&\vdots&\vdots\\
p_n^{(1)}&\cdots&p_n^{(d)}
\end{array}\right)\right\}. 
\end{equation}	
Assume all $\beta_k=0$. Then it follows from the above and \eqref{Meq:singlerowfunction} that $\Phi(P)\geq1$. Since also $1=\Phi(\|p^{(1)}\|_1\;\cdots\;\|p^{(d)}\|_1)\geq\Phi(P)$, we find that $\Phi(P)=1$. Hence $\Phi$ is degenerate, which leads to a contradiction. Thus there exists $k$ such that $\beta_k<0$. Then we can perform the same calculations as in \eqref{Meq:tropicalhomomorphismcontradiction} but now with $\beta_k<0$ and all the inequalities reversed. This leads to a contradiction. Hence there exists no non-degenerate monotone homomorphism $S^d\to\mathbb{T}\mathbb{R}_+^{\rm op}$.

\label{Mlem:interchangeability}
Up to interchangeability, we may assume that any monotone derivation $\Delta$ at a degenerate monotone homomorphism satisfies 
\begin{equation}
\Delta(x\,\cdots\,x)=0 
\end{equation}
for any $x\geq0$.

Let $\Delta$ be a monotone derivation at the degenerate monotone homomorphism $\Phi^{(k)}:P\mapsto \|p^{(k)}\|_1$ for some $k\in[d]$. Define the function $\delta:\mathbb{R}_+\to\mathbb{R}$ through $\delta(x)=-\Delta(x\,\cdots\,x)$. Consider $x,y\in\mathbb{R}_+$. Note that
\begin{equation}
\left(\begin{array}{ccc}
x&\cdots&x\\
y&\cdots&y
\end{array}\right)\succeq \big(x+y\,\cdots\,x+y\big)\succeq \left(\begin{array}{ccc}
x&\cdots&x\\
y&\cdots&y
\end{array}\right).
\end{equation}
Thus,
\begin{align}
\delta(x+y)&=-\Delta\left(\begin{array}{ccc}
x&\cdots&x\\
y&\cdots&y
\end{array}
\right)\\
&=-\Delta(x\,\cdots\,x)-\Delta(y\,\cdots\,y)=\delta(x)+\delta(y).
\end{align}
Moreover,
\begin{align}
\delta(xy)&=-\Delta\big((x\,\cdots\,x)\boxtimes(y\,\cdots\,y)\big)=-\Delta(x\,\cdots\,x)y-x\Delta(y\,\cdots\,y)\\
&=\delta(x)y+x\delta(y).
\end{align}

Let us define 
\begin{equation}
\Delta'(P):=\Delta(P)+\delta\big(\|p^{(k)}\|_1\big), 
\end{equation}
for $P\in S^d$. Since $\Delta$ is a monotone derivation at $\Phi^{(k)}$, so is $\Delta'$ because of the above calculations for $\delta$ and since $P\succeq Q$ implies $\|p^{(k)}\|_1=\|q^{(k)}\|_1$ for all $P,Q\in S^d$. Also, $\Delta$ and $\Delta'$ are clearly interchangeable. We now have, for all $x\geq0$,
\begin{equation}
\Delta'(x\,\cdots\,x)=\Delta(x\,\cdots\,x)+\delta(x)=\Delta(x\,\cdots\,x)-\Delta(x\,\cdots\,x)=0.
\end{equation}

According to Lemma \ref{Mlem:interchangeability}, up to interchangeability, any monotone derivation $\Delta:S^d\to\mathbb{R}$ has the vanishing property $\Delta(p,\ldots,p)=0$ for any $p\in\mathbb{R}_+^n$, $n\in\mathbb{N}$. Indeed, denoting $p=(p_1,\ldots,p_n)$, we have
\begin{equation}
\Delta(p,\ldots,p)=\sum_{i=1}^n \Delta(p_i\,\cdots\,p_i)=0.
\end{equation}
This same result also applies to the results of \cite{farooq2024} where the assumption that $\|p\|_1\in\mathbb Q_+$ was made to guarantee this vanishing property.

Recall the equality of matrices given in \eqref{Meq:basicmatrixequation1}, \eqref{Meq:basicmatrixequation2}. Using the Leibniz rule and additivity of $\Delta$, and Lemma \ref{Mlem:interchangeability}, we find 
    \begin{equation}
        2\Phi^{(k)}[B]\Delta[B]=3\Delta[B], 
    \end{equation}
    where $\Phi^{(k)}[B]=2$, respectively $1$, depending on whether $k\in B$, respectively $k\notin B$. In both cases, the only solution is $\Delta[B]=0$.

Fix $k\in[d]$ and assume $\Delta:S^d\to\mathbb{R}$ is a monotone $\Phi^{(k)}$-derivation. For $\ell=1,\ldots,d$ define
\begin{equation}
    C_\ell:=\left(\begin{array}{ccccccc}
        1&\cdots&1&1&1&\cdots&1\\[0.1cm]
        0&\cdots&0&\smash{\underbrace{1}_{\ell\text{-th entry}}}&0&\cdots&0
    \end{array}\right). 
    \vspace{0.5cm}
\end{equation}
According to Lemma \ref{Mlem:derivationszero}, $\Delta(C_\ell)=0$ for $\ell=1,\ldots,d$. Let us consider $P=\big(p^{(1)},\ldots,p^{(d)}\big)\in\mathcal{V}^d$ with $p^{(\ell)}=\big(p^{(\ell)}_1,\ldots,p^{(\ell)}_n\big)$. Define the matrix
\begin{equation}
P':=\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i=1}^n\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{\ell=1}^d \big(p^{(\ell)}_i\,\cdots\,p^{(\ell)}_i\big)\boxtimes C_\ell.
\end{equation}
One easily sees that
\begin{equation}
P'\succeq P'':=P\boxplus \DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i=1}^n\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{\ell=1}^d \big(p^{(\ell)}_i\,\cdots\,p^{(\ell)}_i\big).
\end{equation}
Since $\Delta(x\,\cdots\,x)=0$ for all $x\geq0$, we notice that $\Delta(P'')=\Delta(P)$ and, hence
\begin{align}
\Delta(P)&=\Delta(P'')\leq\Delta(P')=\sum_{i=1}^n\sum_{\ell=1}^d\Delta\left(\big(p^{(\ell)}_i\,\cdots\,p^{(\ell)}_i\big)\boxtimes C_\ell\right)\label{Meq:Deltais0a}\\
&=\sum_{i=1}^n\sum_{\ell=1}^d\Big(\underbrace{\Delta\big(p^{(\ell)}_i\,\cdots\,p^{(\ell)}_i\big)}_{=0}\Phi^{(k)}(C_\ell)+\Phi^{(k)}\big(p^{(\ell)}_i\,\cdots\,p^{(\ell)}_i\big)\underbrace{\Delta(C_\ell)}_{=0}\Big)\label{Meq:Deltais0b}\\
&=0.\label{Meq:Deltais0c}
\end{align}
Thus, $\Delta$ is nonpositive.

We finish the proof by showing that $\Delta$ is also nonnegative. Define $M:=\max_{1\leq\ell\leq d}\|p^{(\ell)}\|_1$, $m_\ell:=M-\|p^{(\ell)}\|_1$ for $\ell=1,\ldots,d$, and $m:=m_1+\cdots+m_d$. Consider
\begin{equation}
\tilde{P}:=P\boxplus\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{\ell=1}^d\big(m_\ell\,\cdots\,m_\ell\big)\boxtimes C_\ell, 
\end{equation}
which has columns that have the same $1$-norm $M+m$ as one easily verifies. By monotonicity, we find 
\begin{align}
0&=\Delta(M+m\,\cdots\,M+m)\leq \Delta(\tilde{P})\\
&=\Delta(P)+\sum_{\ell=1}^d\underbrace{\Delta\Big(\big(m_\ell\,\cdots\,m_\ell\big)\boxtimes C_\ell\Big)}_{=0}=\Delta(P),
\end{align}
where the terms in the sum vanish according to a calculation analogous to \eqref{Meq:Deltais0a}, \eqref{Meq:Deltais0b} and \eqref{Meq:Deltais0c}.

We show the implications (iii) $\Rightarrow$ (ii) $\Rightarrow$ (i) $\Rightarrow$ (iv) $\Rightarrow$ (iii). 

		(iii) $\Rightarrow$ (ii): Let $k\in[d]$. The matrix $U^{\boxtimes(d-1)}$ contains a row which is the element-wise product of the $d-1$ rows $(u^{(1)}_{i_{k^\prime}}\;\cdots\;u^{(d)}_{i_{k^\prime}})$ with $u^{(k)}_{i_{k^\prime}}>0,u^{(k^\prime)}_{i_{k^\prime}}=0$ for $k^\prime\in[d]\setminus\{k\}$, which exist according to (iii). This row in $U^{\boxtimes(d-1)}$ is clearly of the form $(0\,\cdots\,0\underbrace{x_k}_{k\text{-th entry}}0\,\cdots\,0)$ for some $x_k>0$. We conclude that (ii) holds for $m=d-1$. 

		(ii) $\Rightarrow$ (i): Assume $U\in \mathcal{V}_n^d$ satisfies (ii), and let $P,Q\in \mathcal{V}_n^d$, $Q\preceq P$. We may assume WLOG that $P,Q$ have columns of unit $1$-norm. By (ii) there exists $m_0\in\mathbb{N}$ such that $\tilde{U}:=U^{\boxtimes m_0}$ has a row $(0\,\cdots\,0\underbrace{x_k}_{k\text{-th entry}}0\,\cdots\,0)$ with $x_k>0$ for every $k\in[d]$. We then have 
		\begin{align}
			\tilde{U}&=\left(\begin{array}{ccc}
				\tilde{u}^{(1)}_0&\cdots&\tilde{u}^{(d)}_0\\
				1-\|\tilde{u}^{(1)}_0\|_1&\cdots&0\\
				0&\ddots&0\\
				0&\cdots&1-\|\tilde{u}^{(d)}_0\|_1
			\end{array}\right)\\
            &\succeq\left(\begin{array}{ccc}
				\|\tilde{u}^{(1)}_0\|_1&\cdots&\|\tilde{u}^{(d)}_0\|_1\\
				1-\|\tilde{u}^{(1)}_0\|_1&\cdots&0\\
				0&\ddots&0\\
				0&\cdots&1-\|\tilde{u}^{(d)}_0\|_1
			\end{array}\right), 
		\end{align}
		for some vectors $\tilde{u}_0^{(k)}\in\mathbb{R}_+^l$, $k\in[d]$, where $l\in\mathbb{N}$, and such that $1-\|\tilde{u}_0^{(k)}\|_1>0$ for all $k\in[d]$. Then for any $m\geq1$ 
		\begin{align}
			\tilde{U}^{\boxtimes m}&\succeq\left(\begin{array}{ccc}
				\|\tilde{u}^{(1)}_0\|_1&\cdots&\|\tilde{u}^{(d)}_0\|_1\\
				1-\|\tilde{u}^{(1)}_0\|_1&\cdots&0\\
				0&\ddots&0\\
				0&\cdots&1-\|\tilde{u}^{(d)}_0\|_1
			\end{array}\right)^{\boxtimes m}\\
			&\succeq\left(\begin{array}{ccc}
				\|\tilde{u}^{(1)}_0\|_1^m&\cdots&\|\tilde{u}^{(d)}_0\|_1^m\\
				1-\|\tilde{u}^{(1)}_0\|_1^m&\cdots&0\\
				0&\ddots&0\\
				0&\cdots&1-\|\tilde{u}^{(d)}_0\|_1^m
			\end{array}\right)=:\tilde{U}_m. 
		\end{align}
		Denote the stochastic matrix that maps $\tilde{U}^{\boxtimes m}$ to $\tilde{U}_m$ as $T_m$. Write
		\begin{equation}
			P=\left(\begin{array}{ccc}
				p_0^{(1)}&\cdots&p_0^{(d)}\\
				p_1^{(1)}&\cdots&p_1^{(d)}
			\end{array}\right), 
		\end{equation}
		where for $k\in[d]$ the vectors $p_0^{(k)}\in\mathbb{R}_{>0}^{n_0}$ form the part of common support of $P$ and $p_1^{(k)}\in\mathbb{R}_+^{n_1}$, and $n_0+n_1=n$. Also, define $v_0:=(1/n_0,\ldots,1/n_0)\in\mathbb{R}_+^{n_0}$. Next, consider 
		\begin{equation}
			S_m:=\left(\begin{array}{cccc}
				v_0&\frac{p_0^{(1)}}{1-\|\tilde{u}_0^{(1)}\|_1^m}-\frac{\|\tilde{u}_0^{(1)}\|_1^m}{1-\|\tilde{u}_0^{(1)}\|_1^m}v_0&\cdots&\frac{p_0^{(d)}}{1-\|\tilde{u}_0^{(d)}\|_1^m}-\frac{\|\tilde{u}_0^{(d)}\|_1^m}{1-\|\tilde{u}_0^{(d)}\|_1^m}v_0\\
				0&\frac{1-\|p_0^{(1)}\|_1}{1-\|\tilde{u}_0^{(1)}\|_1^m}&\cdots&0\\
				\vdots&0&\ddots&0\\
				0&0&\cdots&\frac{1-\|p_0^{(d)}\|_1}{1-\|\tilde{u}_0^{(d)}\|_1^m}
			\end{array}\right), 
		\end{equation}
		which has columns that sum to $1$ and non-negative entries for sufficiently large $m$ because $\|\tilde{u}_0^{(k)}\|_1<1$ and $p_0^{(k)}$ has positive entries for all $k\in[d]$. Then 
		\begin{align}
			P&\preceq\left(\begin{array}{ccc}
				p_0^{(1)}&\cdots&p_0^{(d)}\\
				1-\|p_0^{(1)}\|_1&\cdots&0\\
				0&\ddots&0\\
				0&\cdots&1-\|p_0^{(d)}\|_1
			\end{array}\right)=S_m\tilde{U}_m=S_mT_m\tilde{U}^{\boxtimes m}\\
			&\preceq \tilde{U}^{\boxtimes m}=(1\,\cdots\,1)\boxtimes U^{\boxtimes(m_0m)}\preceq Q\boxtimes U^{\boxtimes(m_0m)}, 
		\end{align}
		which is what we aimed to prove. 

		(i) $\Rightarrow$ (iv): Let $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$, and $P,Q\in \mathcal{V}^d$ such that $Q\preceq P$. Since $U$ is power universal, there exists $m\in\mathbb{N}$ such that $P\preceq Q\boxtimes U^{\boxtimes m}$. Using monotonicity and multiplicativity: 
		\begin{equation}
			\Phi_{\underline{\alpha},C}(P)\geq \Phi_{\underline{\alpha},C}(Q\boxtimes U^{\boxtimes m})=\Phi_{\underline{\alpha},C}(Q)\Phi_{\underline{\alpha},C}(U)^m\geq \Phi_{\underline{\alpha},C}(P)\Phi_{\underline{\alpha},C}(U)^m. 
		\end{equation}
		If $\Phi_{\underline{\alpha},C}(U)=1$, then $\Phi_{\underline{\alpha},C}(P)=\Phi_{\underline{\alpha},C}(Q)$. This implies that $\Phi_{\underline{\alpha},C}$ is degenerate, leading to a contradiction. Therefore, $\Phi_{\underline{\alpha},C}(U)<1$. 

		(iv) $\Rightarrow$ (iii): Let $k,k^\prime\in[d]$, $k\neq k^\prime$. Since $\Phi_{e_k,\{k,k^\prime\}}(U)<1$ and the columns in $U$ sum to $1$, $I(U,\{k,k^\prime\})$ cannot contain all rows $i$ in $U$ where $u^{(k)}_i>0$. Hence there exists a row $i$ such that $u^{(k)}_i>0$, but $u^{(k^\prime)}_i=0$, proving the claim.

\label{Mthm:majorization}
		Let $P=(p^{(1)},\ldots,p^{(d)})$, $Q=(q^{(1)},\ldots,q^{(d)})$ be tuples of probability vectors such that $\bigcap_{k=1}^d{\rm supp}\,p^{(k)}\neq\emptyset$ and $\bigcap_{k=1}^d{\rm supp}\,q^{(k)}\neq\emptyset$. If the inequalities in \eqref{Meq:majorizationconditions} hold, then we have the following: 
		\begin{enumerate}[(a)]
			\item There exist a stochastic map $T$ and a tuple of probability vectors $(r^{(1)},\ldots,r^{(d)})$, satisfying $\bigcap_{k=1}^d{\rm supp}\,r^{(k)}\neq\emptyset$, such that
			\begin{equation}
				T(r^{(k)}\otimes p^{(k)})=r^{(k)}\otimes q^{(k)}\quad\text{for }k\in[d], 
			\end{equation}
			and we may choose, for $n$ sufficiently large, 
			\begin{equation}
                \label{Meq:rform}
				r^{(k)}=\frac{1}{n+1}\bigoplus_{\ell=0}^n\left(q^{(k)}\right)^{\otimes \ell}\otimes\left(p^{(k)}\right)^{\otimes(n-\ell)}\quad\text{ for }k\in[d]. 
			\end{equation}
			\item For $n$ sufficiently large there exists a stochastic map $T_n$ such that 
			\begin{equation}
				T_n(p^{(k)})^{\otimes n}=(q^{(k)})^{\otimes n}\quad\text{for }k\in[d]. 
			\end{equation}
		\end{enumerate}
		Conversely, if either one of these holds, then the inequalities in \eqref{Meq:majorizationconditions} hold non-strictly.

\label{Mthm:genasymptocatalytic}
		Let $P=(p^{(1)},\ldots,p^{(d)})$, $Q=(q^{(1)},\ldots,q^{(d)})$ be tuples of probability vectors such that $\bigcap_{k=1}^d{\rm supp}\,p^{(k)}\neq\emptyset$ and $\bigcap_{k=1}^d{\rm supp}\,q^{(k)}\neq\emptyset$, and $P$ is power universal. The following are equivalent: 
		\begin{enumerate}[(i)]
			\item For all $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$ that are continuous (see \eqref{Meq:continuity}) it holds that 
            \begin{equation}\label{Meq:genasymptocatalyticcondition}
                \Phi_{\underline{\alpha},C}(P)\leq \Phi_{\underline{\alpha},C}(Q). 
            \end{equation}
			\item For every $\varepsilon>0$ there exist two tuples of probability vectors $(q_\varepsilon^{(1)},\ldots,q_\varepsilon^{(d)})$ and $(r_\varepsilon^{(1)},\ldots,r_\varepsilon^{(d)})$, satisfying $\bigcap_{k=1}^d{\rm supp}\,q_\varepsilon^{(k)}\neq\emptyset$ and $\bigcap_{k=1}^d{\rm supp}\,r_\varepsilon^{(k)}\neq\emptyset$, and a stochastic map $T_\varepsilon$ such that
			\begin{equation}
				\|q^{(k)}-q_\varepsilon^{(k)}\|_1\leq\varepsilon\quad\text{for }k\in[d], 
			\end{equation}
			and 
			\begin{equation}
				T_\varepsilon(r_\varepsilon^{(k)}\otimes p^{(k)})=r_\varepsilon^{(k)}\otimes q_\varepsilon^{(k)}\quad\text{for }k\in[d]. 
			\end{equation}
			Also, we may choose, for $n$ sufficiently large
			\begin{equation}
				r_\varepsilon^{(k)}=\frac{1}{n+1}\bigoplus_{\ell=0}^n\left(q_\varepsilon^{(k)}\right)^{\otimes\ell}\otimes\left(p^{(k)}\right)^{\otimes(n-\ell)}\quad\text{ for }k\in[d]. 
			\end{equation}
			\item For every $\varepsilon>0$ there exist a tuple of probability vectors $(q_\varepsilon^{(1)},\ldots,q_\varepsilon^{(d)})$, satisfying\\$\bigcap_{k=1}^d{\rm supp}\,q_\varepsilon^{(k)}\neq\emptyset$, such that
			\begin{equation}
				\|q^{(k)}-q_\varepsilon^{(k)}\|_1\leq\varepsilon\quad\text{for }k\in[d], 
			\end{equation}
			and for $n$ sufficiently large a stochastic map $T_{\varepsilon,n}$ such that 
			\begin{equation}
				T_{\varepsilon,n}(p^{(k)})^{\otimes n}=(q_\varepsilon^{(k)})^{\otimes n}\quad\text{for }k\in[d]. 
			\end{equation}
		\end{enumerate}

(i) $\Rightarrow$ (ii) and (iii): Fix any $k\in[d]$. Define $W:=(w,\ldots,w)$, where $w:=(1/n,\ldots,1/n)\in\mathbb{R}^n$, and 
		\begin{equation}
			Q_\varepsilon:=\left(1-\frac{\varepsilon}{2}\right)Q+\frac{\varepsilon}{2}W, 
		\end{equation}
		where $+$ means entry-wise addition of two matrices. Write $Q_\varepsilon=(q_\varepsilon^{(1)},\ldots,q_\varepsilon^{(d)})$. Let $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$ be continuous. Then 
		\begin{align}
			\Phi_{\underline{\alpha},C}&(Q_\varepsilon)=\Phi_{\underline{\alpha},C}\left(\left(1-\frac{\varepsilon}{2}\right)Q+\frac{\varepsilon}{2}W\right)\geq \Phi_{\underline{\alpha},C}\left(\left(1-\frac{\varepsilon}{2}\right)Q\boxplus\frac{\varepsilon}{2}W\right)\\
			&=\left(1-\frac{\varepsilon}{2}\right)\Phi_{\underline{\alpha},C}(Q)+\frac{\varepsilon}{2}\Phi_{\underline{\alpha},C}(W)=\Phi_{\underline{\alpha},C}(Q)+\frac{\varepsilon}{2}[1-\Phi_{\underline{\alpha},C}(Q)]\\
            &\geq \Phi_{\underline{\alpha},C}(Q)\geq \Phi_{\underline{\alpha},C}(P), 
		\end{align}
		where in the first inequality we used monotonicity, in the equality that follows we used additivity and the fact that $\Phi_{\underline{\alpha},C}(cA)=c\Phi_{\underline{\alpha},C}(A)$ for any $c>0$ and $A\in \mathcal{V}^d$, in the next equality we used that $\Phi_{\underline{\alpha},C}(W)=1$ since all the columns in $W$ are the same and sum to $1$, in the penultimate inequality we used that $\Phi_{\underline{\alpha},C}(Q)\leq1$, and in the final inequality we used the assumption in (i). If $\Phi_{\underline{\alpha},C}(Q)=1$, then the final inequality is strict since $\Phi_{\underline{\alpha},C}(P)<1$ by Lemma \ref{Mlem:poweruniversalconditions}. If $\Phi_{\underline{\alpha},C}(Q)<1$, then the penultimate inequality is strict. Thus, in both cases $\Phi_{\underline{\alpha},C}(P)<\Phi_{\underline{\alpha},C}(Q_\varepsilon)$.

		Let $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$ be discontinuous. Since $Q_\varepsilon$ has no $0$ entries, $\Phi_{\underline{\alpha},C}(Q_\varepsilon)=\Phi_{\underline{\alpha},D}(Q_\varepsilon)$, where $D\subseteq C$ consists of all $c\in C$ that satisfy $\alpha_c>0$. If $\Phi_{\underline{\alpha},D}$ is one of the degenerate homomorphisms (i.e. the $1$-norm of one of the columns), then 
        \begin{equation}
			\Phi_{\underline{\alpha},C}(P)<1=\Phi_{\underline{\alpha},D}(Q_\varepsilon)=\Phi_{\underline{\alpha},C}(Q_\varepsilon), 
		\end{equation}
        where the inequality follows from Lemma \ref{Mlem:poweruniversalconditions}. If $\Phi_{\underline{\alpha},D}$ is nondegenerate, then we find 
		\begin{equation}
			\Phi_{\underline{\alpha},C}(P)\leq \Phi_{\underline{\alpha},D}(P)<\Phi_{\underline{\alpha},D}(Q_\varepsilon)=\Phi_{\underline{\alpha},C}(Q_\varepsilon), 
		\end{equation}
		where the first inequality is due to the fact that $\Phi_{\underline{\alpha},C}$ sums over all or a subset of the rows that $\Phi_{\underline{\alpha},D}$ sums over, and the second inequality is due to the fact that $\Phi_{\underline{\alpha},D}$ is continuous and nondegenerate. 

		We conclude that $\Phi_{\underline{\alpha},C}(P)<\Phi_{\underline{\alpha},C}(Q_\varepsilon)$ for all $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$, hence Theorem \ref{Mthm:majorization} yields (ii) and (iii). Note that one easily sees that $\bigcap_{k=1}^d{\rm supp}\,q_\varepsilon^{(k)}\neq\emptyset$ and the fact that $\bigcap_{k=1}^d{\rm supp}\,r_\varepsilon^{(k)}\neq\emptyset$ in (ii) follows from the possible choice of the $r_\varepsilon^{(k)}$ in \eqref{Meq:rform}. 

		(ii) or (iii) $\Rightarrow$ (i): The fact that $\bigcap_{k=1}^d{\rm supp}\,q_\varepsilon^{(k)}\neq\emptyset$, respectively $\bigcap_{k=1}^d{\rm supp}\,r_\varepsilon^{(k)}\neq\emptyset$, implies that $(q_\varepsilon^{(1)},\ldots,q_\varepsilon^{(d)})\in S^d$, respectively $(r_\varepsilon^{(1)},\ldots,r_\varepsilon^{(d)})\in S^d$. Then, for any continuous $\Phi\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$ we find for any $\varepsilon>0$, using monotonicity and multiplicativity, that $\Phi(P)\leq \Phi(Q_\varepsilon)$, where $Q_\varepsilon:=(q_\varepsilon^{(1)},\ldots,q_\varepsilon^{(d)})$. For any $\varepsilon>0$, write $Q_\varepsilon=Q_\varepsilon^0\boxplus Q_\varepsilon^1$, where $Q_\varepsilon^0$ consists of the first $n_Q$ rows of $Q_\varepsilon$ and $n_Q$ is the number of rows in $Q$ (if $Q_\varepsilon$ has less than $n_Q$ rows, then we add rows of zeros to form $Q_\varepsilon^0$). Note that $\lim_{\varepsilon\rightarrow0}Q_\varepsilon^0=Q$ and the sum of every column in $Q_\varepsilon^1$ is at most $\varepsilon$. Then 
        \begin{equation}
            \Phi(Q_\varepsilon)+1=\Phi(Q_\varepsilon\boxplus(1\,\cdots\,1))=\Phi(Q_\varepsilon^0)+\underbrace{\Phi(Q_\varepsilon^1\boxplus(1\,\cdots\,1))}_{\leq1+\varepsilon}, 
        \end{equation}
        where in the inequality we used monotonicity and the fact that the rows of $Q_\varepsilon^1\boxplus(1\,\cdots\,1)$ sum to at most $1+\varepsilon$. Hence $\Phi(Q_\varepsilon)\leq\Phi(Q_\varepsilon^0)+\varepsilon$. This implies that $\Phi(P)\leq\Phi(Q_\varepsilon^0)+\varepsilon$. Taking the limit $\varepsilon\rightarrow0$ in this inequality, since $\Phi$ is a continuous function when restricted to matrices with a fixed number of rows, we deduce that $\Phi(P)\leq\Phi(Q)$, completing the proof.

\label{Mrmk:minimalrestrictions}
        As mentioned in the Introduction, we could drop the requirement \eqref{Meq:baselinecond}, namely that the intersection of the supports of the columns in a matrix is non-empty, and require instead that the pairwise intersection of supports is non-empty. This would yield a semiring with even less restrictions than the one studied in this section. However, in that case, the homomorphisms and derivations appearing in the conditions of the Vergleichsstellensatz (Theorem \ref{thm:Fritz2022}) will turn out to be only the bivariate ones, namely those associated with the R\'enyi divergences between each pair of columns of the matrix. To get an idea why this is so, consider the $d=3$ case. A matrix of the form 
        \begin{equation}
            P:=\left(\begin{array}{ccc}
            *&*&0\\
            *&0&*\\
            0&*&*
            \end{array}\right), 
        \end{equation}
        where the asterisks represent positive entries, has pairwise non-empty intersections of the supports, but does not have non-empty intersection over all the supports. Any homomorphism $\Phi_{\underline{\alpha},C}$ with a character $C$ containing more than two columns will evaluate to zero on the matrix above, since the set of rows $I(P,C)$ defined in \eqref{Meq:Iset} is empty. Hence $\Phi_{\underline{\alpha},C}$ has a non-trivial kernel, and such homomorphisms are excluded from the set of homomorphisms appearing in the conditions of Theorem \ref{thm:Fritz2022}. Therefore, the only non-degenerate monotone homomorphisms with trivial kernel associated with this semiring are $\Phi_{\underline{\alpha},\{k,k'\}}$ with $k,k'\in[d]$, $k\neq k'$, $\underline{\alpha}\in A_+$ having at most two non-zero components $\alpha_k,\alpha_{k'}\geq0$, and $\alpha_{l}=0$ for all $l\neq k,k'$. These homomorphisms correspond to the R\'enyi divergences between any pair of columns, with parameter $\alpha\in[0,1)$; see also Figure \ref{Mfig:emptytriangle} for a depiction.

        Additionally, the conditions for a matrix to be power universal are even stricter in this semiring than in $S^d$. Namely, a matrix having any common support among all columns is now no longer power universal, hence we can no longer use this semiring to find majorization conditions for such a matrix.

For a fixed matrix $P\in S^d$, define the evaluation function 
\begin{equation}
    f_P:\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})\rightarrow\mathbb{R} 
\end{equation}
by 
\begin{equation}
    f_P(\Phi_{\underline{\alpha},C}):=\Phi_{\underline{\alpha},C}(P), 
\end{equation}
for any $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$. For a fixed $C\subseteq[d]$ with $|C|\geq2$, one sees that $\alpha\mapsto\Phi_{\underline{\alpha},C}(P)$ is continuous on $A_C$, and therefore $f_P$ is continuous on $T_C$. Thus, by the properties of the discrete union topology, $f_P$ is continuous on $\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$. In other words, $f_P$ is in $C(\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op}),\mathbb{R})$, the algebra of all continuous real-valued functions on $\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$. 

Next, let $\mathcal{A}$ be the $\mathbb{R}$-algebra generated by multiplication of the functions $f_P$, $P\in S^d$, by real numbers, and finite repetitions of point-wise addition and multiplication. Then $\mathcal{A}$ is a subalgebra of $C(\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op}),\mathbb{R})$. Clearly, $f_{(1,\ldots,1)}(\Phi_{\underline{\alpha},C})=1$ for all $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$, hence $\mathcal{A}$ contains a non-zero constant function. One also sees that for any two distinct $\Phi_{\underline{\alpha},C},\Phi_{\underline{\alpha'},C'}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})$, there exists a $P\in S^d$ such that $f_P(\Phi_{\underline{\alpha},C})\neq f_P(\Phi_{\underline{\alpha'},C'})$, hence $\mathcal{A}$ separates points. Therefore, by the Stone-Weierstrass theorem, $\mathcal{A}$ is dense in $C(\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op}),\mathbb{R})$.

Since $O$ is open, it contains a $\Phi_{\underline{\alpha_0},C_0}\in O$ that is continuous, i.e. satisfying ${\rm supp}\,\underline{\alpha_0}=C_0$ (see \eqref{Meq:continuity}). Clearly, there exists a continuous function $f:\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})\rightarrow\mathbb{R}$ such that $f(\Phi_{\underline{\alpha},C})=1$ for all $\Phi_{\underline{\alpha},C}$ outside $O$, and $f(\Phi_{\underline{\alpha_0},C_0})=-1$. Since $\mathcal{A}$ is dense in $C(\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op}),\mathbb{R})$, $f$ can be approximated by functions in $\mathcal{A}$ with arbitrary precision, from which it follows that there exist $r_1,\ldots,r_t\in\mathbb{R}$ and $P_1,\ldots,P_t\in S^d$ such that 
\begin{equation}\label{Meq:SWapproximation}
    r_1\Phi_{\underline{\alpha},C}(P_1)+\ldots+r_t\Phi_{\underline{\alpha},C}(P_t)\left\{\begin{array}{ll}>0&\text{if }\ \Phi_{\underline{\alpha},C}\in \mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})\setminus O\\<0&\text{if }\ \Phi_{\underline{\alpha},C}=\Phi_{\underline{\alpha_0},C_0}\end{array}\right..
\end{equation}
Here we have used the multiplicativity of the homomorphisms, which implies that $\mathcal{A}$ is the span of the set of all $f_P$, $P\in S^d$, with real coefficients. 
Define the matrices 
\begin{equation}
    S:=\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i\,:\,r_i>0}r_iP_i,\quad R:=\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{i\,:\,r_i<0}-r_iP_i, 
\end{equation}
which are both contained in $S^d$. Then, by rearranging \eqref{Meq:SWapproximation}, if $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})\setminus O$, 
\begin{equation}\label{Meq:counterexample1}
    \Phi_{\underline{\alpha},C}(S)>\Phi_{\underline{\alpha},C}(R),  
\end{equation}
and 
\begin{equation}\label{Meq:counterexample2}
    \Phi_{\underline{\alpha_0},C_0}(S)<\Phi_{\underline{\alpha_0},C_0}(R). 
\end{equation}
Note that it follows in particular that both matrices $R,S$ are non-zero. 

We may add a diagonal component to $R,S$ via 
\begin{equation}
    \tilde R:=R\boxplus{\rm diag}\{a_1,\ldots,a_d\},\quad\tilde S:=S\boxplus{\rm diag}\{b_1,\ldots,b_d\}, 
\end{equation}
with $a_1,\ldots,a_d>0$ and $b_1,\ldots,b_d\geq0$, to ensure that each column in both $\tilde R$ and $\tilde S$ sums to the same value $t$. Define the normalized matrices $P:=\tilde R/t$ and $Q:=\tilde S/t$, in $S$. Since $a_1,\ldots,a_d>0$, $P$ satisfies condition (ii) of Proposition \ref{Mlem:poweruniversalconditions}, hence $P$ is power universal. For any character $C\subseteq[d]$ with $|C|\geq2$, we have 
\begin{equation}
    \Phi_{\underline{\alpha},C}(P)=t^{-1}\Phi_{\underline{\alpha},C}(\tilde R)=t^{-1}\Phi_{\underline{\alpha},C}(R), 
\end{equation}
and similarly for $Q$. Hence, 
\begin{equation}
    \Phi_{\underline{\alpha},C}(Q)>\Phi_{\underline{\alpha},C}(P) 
\end{equation}
for all $\Phi_{\underline{\alpha},C}\in\mathcal{H}^{\rm n.d.}(S^d,\mathbb{R}_+^{\rm op})\setminus O$ and the reverse inequality when $\Phi_{\underline{\alpha},C}=\Phi_{\underline{\alpha_0},C_0}$. The statement of the theorem now follows from the fact that (a) or (b) in Theorem \ref{Mthm:majorization} imply the non-strict version of \ref{Meq:majorizationconditions} for the case of exact majorization, and from the implications (ii) $\Rightarrow$ (i), and (iii) $\Rightarrow$ (i) in Theorem \ref{Mthm:genasymptocatalytic} for the case of asymptotic majorization.

Let $\beta>0$ and $c\in[d-1]$. Note that, denoting the rows of $P\in\mathcal{V}^d_{\rm d.c.}$ by $p_1,\ldots,p_n$, we have
\begin{equation}
\Phi^\mathbb{T}_{\beta,c}(P)=\sup_{1\leq j\leq n}\varphi^\mathbb{T}_{\beta,c}(p_j), 
\end{equation}
where $\varphi^\mathbb{T}_{\beta,c}(x_1,\ldots,x_d)=(x_c/x_d)^\beta$ for all $x_1,\ldots,x_{d-1}\geq0$ and $x_d>0$. The sublevel sets
\begin{equation}
\left\{(x_1,\ldots,x_d)\in\mathbb{R}_+^{d-1}\times\mathbb{R}_{>0}\,\middle|\,\left(\frac{x_c}{x_d}\right)^\beta\leq a\right\},\qquad a>0,
\end{equation}
are immediately seen to be convex, implying that $\varphi^\mathbb{T}_{c,\beta}$ is quasi-convex, i.e.,\ for all $x,y\in\mathbb{R}_+^{d-1}\times\mathbb{R}_{>0}$ and $t\in(0,1)$,
\begin{equation}
\varphi^\mathbb{T}_{c,\beta}\big(tx+(1-t)y\big)\leq\max\{\varphi^\mathbb{T}_{c,\beta}(x),\varphi^\mathbb{T}_{c,\beta}(y)\}.
\end{equation}

Let $P,Q\in\mathcal{V}^d_{\rm d.c.}$, $P$ with rows $p_1,\ldots,p_n$ and $Q$ with rows $q_1,\ldots,q_m$. Assume that $P\succeq Q$ and let $T=(T_{i,j})_{i,j}$ be a stochastic matrix such that $Q=TP$. We again denote $T_i=\sum_{j=1}^n T_{i,j}$ which we may assume to be positive WLOG. Noting that $\varphi^\mathbb{T}_{c,\beta}(cx)=\varphi^\mathbb{T}_{c,\beta}(x)$ for all $c>0$ and $x\in\mathbb{R}_+^{d-1}\times\mathbb{R}_{>0}$ and using the quasi-convexity of $\varphi^\mathbb{T}_{c,\beta}$, we now have
\begin{align}
\Phi^\mathbb{T}_{c,\beta}(Q)&=\max_{1\leq i\leq m}\varphi^\mathbb{T}_{c,\beta}(q_i)=\max_{1\leq i\leq m}\varphi^\mathbb{T}_{c,\beta}\left(\sum_{j=1}^n T_{i,j}p_j\right)\\
&=\max_{1\leq i\leq m}\varphi^\mathbb{T}_{c,\beta}\left(\sum_{j=1}^n\frac{T_{i,j}}{T_i}p_j\right)\leq\max_{1\leq i\leq m}\max_{1\leq j\leq n}\varphi^\mathbb{T}_{c,\beta}(p_j)\\
&=\max_{1\leq j\leq n}\varphi^\mathbb{T}_{c,\beta}(p_j)=\Phi^\mathbb{T}_{c,\beta}(P),
\end{align}
proving the claim.

Throughout this proof, we consider an arbitrary matrix $P=\big(p^{(1)},\ldots,p^{(d)}\big)\in\mathcal{V}^d_{\rm d.c.}$ with rows $p^{(k)}=\big(p^{(k)}_1,\ldots,p^{(k)}_n\big)$ for $k=1,\ldots,d$. We also denote the rows of $P$ by $p_1,\ldots,p_n$.

We first consider the case of a monotone homomorphism $\Phi:S^d_{\rm d.c.}\to\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op}\}$. As in the minimally restricted case $S^d$, also now $\Phi$ is associated with $\underline{\alpha}\in A_+\cup A_-\setminus\{e_1,\ldots,e_d\}$. Lemmas \ref{Mlem:1or2} and \ref{Mclm:nontrivialB} can be proven in exactly the same way (except now we only consider $B\subsetneq[d]$ such that $d\in B$) and we will use these results in the following. Hence, the notion of $\Phi$-nontrivial sets can again be defined and $\Phi$ also has a character $C\subseteq[d]$. Through the same proof as the one for Proposition \ref{Mpro:monhommin}, we know that
\begin{equation}
\Phi(P)=\sum_{i:\,C\subseteq{\rm supp}\,p_i}\prod_{k\in{\rm supp}\,p_i}\big(p_i^{(k)}\big)^{\alpha_k}
\end{equation}
and that ${\rm supp}\,\underline{\alpha}=\{k\,|\,\alpha_k\neq0\}\subseteq C$. As for the case $\mathbb{K}=\mathbb{R}_+^{\rm op}$, we already know that $\underline{\alpha}\in A_+$, so this case is dealt with and the set of nondegenerate monotone homomorphisms coincides with $\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{R}_+^{\rm op})$. Thus we may concentrate on the case $\mathbb{K}=\mathbb{R}_+$.

Assume that $\mathbb{K}=\mathbb{R}_+$. From the results of \cite{farooq2024}, we know that $\underline{\alpha}\in A_-$. Let us first concentrate on the subset of those $\underline{\alpha}=(\alpha_1,\ldots,\alpha_d)$ where $\alpha_1>1$ and $\alpha_2,\ldots,\alpha_d\leq 0$. We show that $\alpha_2=\cdots=\alpha_{d-1}=0$. Consider
\begin{equation}
P_t:=\left(\begin{array}{ccccc}
1/2&1-t&1/2&\cdots&1/2\\
1/2&t&1/2&\cdots&1/2
\end{array}\right),\qquad 0\leq t\leq\frac{1}{2}.
\end{equation}
Assume $\alpha_2\neq0$, hence $\alpha_2<0$. Then, by Lemma \ref{Mlem:1or2}(ii), $2\in C$. Whenever $0\leq s\leq t\leq 1/2$, we have $P_s\succeq P_t$. Thus, $\Phi(P_\varepsilon)\leq\Phi(P_0)$, i.e.,
\begin{equation}
\label{Meq:onlytwocolumns}
2^{-\alpha_1-\alpha_3-\cdots-\alpha_d}\left[(1-\varepsilon)^{\alpha_2}+\varepsilon^{\alpha_2}\right]\leq2^{-\alpha_1-\alpha_3-\cdots-\alpha_d}
\end{equation}
for all $\varepsilon\in(0,1/2]$. However, the left-hand side above diverges as $\varepsilon\to 0$, so $\alpha_2=0$. Similarly, $\alpha_3=\cdots=\alpha_{d-1}=0$. The same logic does not work for $\alpha_d$ because
\begin{equation}
\left(\begin{array}{cccc}
1/2&\cdots&1/2&1\\
1/2&\cdots&1/2&0
\end{array}\right)\notin\mathcal{V}^d_{\rm d.c.}, 
\end{equation}
hence we are not able to consider matrices similar to the $P_t$ for $0\leq t\leq1/2$ as above, but now with the last column equal to $(1-t,t)$. 

We know that $1,d\in C$ and we now show that there are no other columns in $C$. Assume that $C$ contains another column $k\in C\setminus\{1,d\}$. WLOG we assume that $k=2$. Then, \eqref{Meq:onlytwocolumns} holds with $\alpha_1+\alpha_d=1$ and $\alpha_3=\cdots=\alpha_{d-1}=0$, yielding $1\leq1/2$, a contradiction. Hence $C=\{1,d\}$. Therefore, in the part of $A_-$ where $\alpha_1>1$, the only non-degenerate homomorphisms $S^d_{\rm d.c.}\to\mathbb{R}_+$ are all $\Phi_{\alpha,1}$ for $\alpha_d>1$. In the same way, we can deal with the parts of $A_-$ where $\alpha_c>1$, $c=2,\ldots,d-1$ to show that the only homomorphisms are all $\Phi_{\alpha,c}$, for $\alpha_c>1$, $c=2,\ldots,d-1$. 

It remains to be shown what the homomorphisms are for the part of $A_-$ where $\alpha_d>1$. Assume that $\alpha_d\geq1$.             








Considering matrices
\begin{equation}
Q_t:=\left(\begin{array}{cccc}
1-t&1/2&\cdots&1/2\\
t&1/2&\cdots&1/2
\end{array}\right),\qquad 0\leq t\leq\frac{1}{2},
\end{equation}
we find that $Q_s\succeq Q_t$ for $0\leq s\leq t\leq 1/2$, so $\Phi(Q_\varepsilon)\leq\Phi(Q_0)$ for all $\varepsilon\in(0,1/2]$. However, for $\alpha_1<0$, this again leads to a contradiction, so $\alpha_1=0$. Similarly, $\alpha_2=\cdots=\alpha_{d-1}=0$. Thus, $\alpha_d=1$ since $\alpha_1+\cdots+\alpha_d=1$. However, this case falls under the set $\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{R}_+^{\rm op})$ which is already dealt with. Thus, the set of nondegenerate monotone homomorphisms $S^d_{\rm d.c.}\to\mathbb{R}_+$ is exactly $\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{R}_+)$.























































We now consider the case $\mathbb{K}=\mathbb{T}\mathbb{R}_+$. From the results of \cite{farooq2024}, we know that there is $\underline{\beta}=(\beta_1,\ldots,\beta_d)\in B_-$ such that, when the columns of $P$ have full support,
\begin{equation}
\Phi(P)=\max_{1\leq i\leq n}\prod_{k=1}^d \big(p^{(k)}_i\big)^{\beta_k}.
\end{equation}
Proceeding similarly as above for $\mathbb{K}=\mathbb{R}_+$ and considering the matrices $P_t$ and $Q_t$, one can again show that $\beta_d<0$ and that there is $c\in\{1,\ldots,d-1\}$ such that $\beta_c>0$ and $\beta_k=0$ for $k\in[d-1]\setminus\{c\}$. Thus, $\beta:=\beta_c=-\beta_d$.






Note that we may assume $P$ to have columns that sum up to $1$ because, in the general case, 
\begin{equation}
\Phi(P)=\Phi\left(\|p^{(1)}\|_1\,\cdots\,\|p^{(d)}\|_1\right)\Phi(P^\prime) 
\end{equation}
for a matrix $P'$ with columns that sum to $1$, and $\Phi\left(\|p^{(1)}\|_1\,\cdots\,\|p^{(d)}\|_1\right)$ is known since $\Phi$ is evaluated on a matrix with common support. Thus, we assume for now that $\|p^{(k)}\|=1$ for $k=1,\ldots,d$. By monotonity, this implies that $\Phi(P)\geq1$. 

        Let $p_1,\ldots,p_n\in\mathbb{R}_+^d$ denote the rows of $P$. Let $\delta>0$, which we will fix later. If a row $p_i$ contains a zero, but $(p_i)_k>0$, then we denote by $\widetilde{p_i}$ the row $p_i$ with every $0$ replaced by a $1$. If a row $p_i$ contains a zero, and $(p_i)_k=0$ is one of them, then we denote by $\widetilde{p_i}^\delta$ the row $p_i$ with $\delta$ on position $k$ and every other $0$ replaced by a $1$. Then, notice that 
		\begin{align}
			&P\boxplus\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{k\in{\rm supp}\,p_i\neq[d]}\widetilde{p_i}\boxplus\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{k\notin{\rm supp}\,p_i\neq[d]}\widetilde{p_i}^\delta&\label{Meq:PhiPdecomposedtropical1}\\
            &\qquad\qquad=\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{{\rm supp}\,p_i=[d]}p_i\boxplus\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{k\in{\rm supp}\,p_i\neq[d]}\left(\begin{array}{c}
				\widetilde{p_i}\\
				p_i
			\end{array}\right)\boxplus\DOTSB 
	\mathop{\vphantom{\sum}\mathpalette\bigop@{\boxplus}}\slimits@
_{k\notin{\rm supp}\,p_i\neq[d]}\left(\begin{array}{c}
				\widetilde{p_i}^\delta\\
				p_i
			\end{array}\right).&\label{Meq:PhiPdecomposedtropical2}
		\end{align}

Let us note that Lemma \ref{Mlem:1or2} still holds (with the obvious modification that $d\in B$), especially $\Phi[B]=1$ whenever $d\in B\subseteq[d]$. Using this, we have for the terms in the penultimate $\boxplus$-sum on the RHS of \eqref{Meq:PhiPdecomposedtropical1}, \eqref{Meq:PhiPdecomposedtropical2} (i.e.,\ when $i$ is such that $k\in{\rm supp}\,p_i$ or, simply, $i\in{\rm supp}\,p^{(k)}$ and ${\rm supp}\,p_i\neq [d]$)
\begin{align}
\Phi\big(\widetilde{p_i}\boxplus p_i\big)&=\Phi\left(\widetilde{p_i}\boxtimes\left(
\begin{array}{ccc}
1&\cdots&1\\
&{\rm supp}\,p_i&
\end{array}\right)\right)\\
&=\Phi(\widetilde{p_i})\Phi[{\rm supp}\,p_i]=\Phi(\widetilde{p_i})=\left(\frac{p^{(k)}_i}{p^{(d)}_i}\right)^\beta.
\end{align}
Similarly, for the terms in the final $\boxplus$-sum on the RHS of \eqref{Meq:PhiPdecomposedtropical1}, \eqref{Meq:PhiPdecomposedtropical2}, we have
\begin{equation}
\Phi(\widetilde{p_i}^\delta\boxplus p_i)=\left(\frac{\delta}{p^{(d)}_i}\right)^\beta.
\end{equation}
Then \eqref{Meq:PhiPdecomposedtropical1}, \eqref{Meq:PhiPdecomposedtropical2} implies 
		\begin{align}
			\label{Meq:Phitropicaldominatingcolumnalmost}
   \max&\left(\{\Phi(P)\}\cup\left\{\left(\frac{p^{(k)}_i}{p^{(d)}_i}\right)^\beta\,\middle|\,i:\ k\in{\rm supp}\,p_i\neq[d]\right\}\right.\\
   &\qquad\qquad\qquad\cup\left.\left\{\left(\frac{\delta}{p^{(d)}_i}\right)^\beta\,\middle|\,i:\ k\notin{\rm supp}\,p_i\neq[d]\right\}\right)\\
   &=\max\left(\left\{\left(\frac{p^{(k)}_i}{p^{(d)}_i}\right)^\beta\,\middle|\,i:\ k\in{\rm supp}\,p_i\right\}\right.\\
   &\qquad\qquad\qquad\qquad\cup\left.\left\{\left(\frac{\delta}{p^{(d)}_i}\right)^\beta\,\middle|\,i:\ k\notin{\rm supp}\,p_i\right\}\right).

		\end{align}
        By making $\delta$ suitably small, we can make sure that both maximizations above do not have an element of the form $\delta^\beta\big(p^{(d)}_i\big)^{-\beta}$, for some row $i$, as largest element. 

		For any $\varepsilon>0$, we have 
		\begin{equation}
			P\boxplus\left(\begin{array}{ccc}
				\varepsilon&\cdots&\varepsilon\\
				\vdots&\ddots&\vdots\\
				\varepsilon&\cdots&\varepsilon
			\end{array}\right)\succeq P+\left(\begin{array}{ccc}
				\varepsilon&\cdots&\varepsilon\\
				\vdots&\ddots&\vdots\\
				\varepsilon&\cdots&\varepsilon
			\end{array}\right), 
		\end{equation}
		where $+$ denotes the entry-wise addition of matrices. This implies 
		\begin{equation}
			\Phi(P)\geq\max_{i\in[n]}\left(\frac{p^{(k)}_i+\varepsilon}{p^{(d)}_i+\varepsilon}\right)^\beta, 
		\end{equation}
        where we used the assumption that $\Phi(P)\geq1$. By continuity of the functions $\varepsilon\mapsto\frac{p^{(k)}_i+\varepsilon}{p^{(d)}_i+\varepsilon}$, $i\in[n]$, there exists $\varepsilon_{\rm max}$ such that the above maximum is obtained at the same $i_0$ for all $\varepsilon\leq\varepsilon_{\rm max}$. Then, taking $\varepsilon\rightarrow0$ on both sides of the inequality above, we deduce 
		\begin{equation}
			\Phi(P)\geq\left(\frac{p^{(k)}_{i_0}}{p^{(d)}_{i_0}}\right)^\beta\quad\forall\,i\in[n]. 
		\end{equation}
		This together with \eqref{Meq:Phitropicaldominatingcolumnalmost} yields 
        \begin{equation}
            \Phi(P)=\max_{i\in[n]}\left(\frac{p^{(k)}_i}{p^{(d)}_i}\right)^\beta. 
        \end{equation}

		Finally, we consider the case $\mathbb{K}=\mathbb{T}\mathbb{R}_+^{\rm op}$. Exactly as in the proof of Proposition 13 in \cite{farooq2024} (see Equations (89), (90)), we can show that $\Phi(P)$ only depends on the supports of the columns of $P$. More precisely, if $P,Q\in S_{\rm d.c.}^d$ satisfy ${\rm supp}\,p^{(k)}={\rm supp}\,q^{(k)}$ for all $k\in[d]$, then $\Phi(P)=\Phi(Q)$. It then follows that for any $Q\in S_{\rm d.c.}^d$, we have $\Phi(Q)\leq\Phi(\|q^{(1)}\|_1\,\cdots\,\|q^{(d)}\|_1)=\Phi(1\,\cdots\,1)=1$, since $Q\succeq(\|q^{(1)}\|_1\,\cdots\,\|q^{(d)}\|_1)$ and the latter one-row matrix has the same support structure as $(1\,\cdots\,1)$. $P$ has at least one row not containing any $0$. Assume WLOG it is the first row. Then $P$ majorizes and is majorized by 
		\begin{equation}
			\left(\begin{array}{ccc}
				p_1^{(1)}/2&\cdots&p_1^{(d)}/2\\
				p_1^{(1)}/2&\cdots&p_1^{(d)}/2\\
				p_2^{(1)}&\cdots&p_2^{(d)}\\
				\vdots&\vdots&\vdots\\
				p_n^{(1)}&\cdots&p_n^{(d)}
			\end{array}\right), 
		\end{equation}
		hence 
        \begin{equation}
            \Phi(P)=\max\left(\underbrace{\Phi\left(p_1^{(1)}/2\;\cdots\;p_1^{(d)}/2\right)}_{=1},\underbrace{\Phi\left(\begin{array}{ccc}
				p_1^{(1)}/2&\cdots&p_1^{(d)}/2\\
				p_2^{(1)}&\cdots&p_2^{(d)}\\
				\vdots&\vdots&\vdots\\
				p_n^{(1)}&\cdots&p_n^{(d)}
			\end{array}\right)}_{\leq1}\right)=1. 
        \end{equation}
        Therefore, there are no non-degenerate monotone homomorphisms for $\mathbb{K}=\mathbb{T}\mathbb{R}_+^{\rm op}$.

Let $\Delta:S_{\rm d.c.}^d\to\mathbb{\mathbb{R}}$ be a monotone $\Phi^{(k)}$-derivation for some $k\in[d]$. For any $x\in\mathbb{R}_+^d$ with $d\in{\rm supp}\,x$ we find using the above note and the Leibniz rule for $\Delta$,
\begin{align}
\Delta\big(\tilde{x}^T\boxplus x^T\big)&=\Delta\left(\tilde{x}^T\boxtimes\left(\begin{array}{ccc}
1&\cdots&1\\
&{\rm supp}\,x&
\end{array}\right)\right)\\
&=\Delta(\tilde{x}^T)\Phi^{(k)}[{\rm supp}\,x]+\Phi^{(k)}(\tilde{x}^T)\underbrace{\Delta[{\rm supp}\,x]}_{=0}\\
&=\left\{\begin{array}{ll}
2\Delta(\tilde{x}^T)&{\rm if}\ k\in{\rm supp}\,x\\
\Delta(\tilde{x}^T)&{\rm otherwise}
\end{array}\right.. 
\end{align}
Through a similar calculation as in \eqref{Meq:Phihajotus1}, \eqref{Meq:Phihajotus2} and \eqref{Meq:Phihajotus3}, we now find that
\begin{equation}
\Delta(P)=\sum_{i\in{\rm supp}\,p^{(k)}}\Delta(\widetilde{p_i}) 
\end{equation}
for any $P=(p^{(1)},\ldots,p^{(d)})\in S_{\rm d.c.}^d$ with rows $p_i$. Again, $\widetilde{p_i}$ is the row $p_i$ where the vanishing entries are replaced with 1. It follows that $\Delta(P)$ can be seen as $\Delta$ evaluated on a matrix with non-vanishing entries, more specifically the matrix resulting from taking only the rows in $P$ corresponding to ${\rm supp}\,p^{(k)}$ and replacing all vanishing entries with $1$. Hence, we can use the results in the proof of Proposition 14 in \cite{farooq2024} for the equal-support case. Combining Equations (111) and (117) in \cite{farooq2024}, we find 
\begin{equation}
\Delta(P)=\sum_{\ell\neq k}\gamma_\ell\sum_{i\in{\rm supp}\,p^{(k)}}p_i^{(k)}\log\left(\frac{p_i^{(k)}}{\widetilde{p_i^{(\ell)}}}\right) 
\end{equation}
for some constants $\gamma_\ell\geq0$, $\ell\in[d]\setminus\{k\}$. 

        Next, we show that $\gamma_\ell=0$ if $\ell\neq d$. Let $\ell\in[d-1]\setminus\{k\}$. Consider the following matrices in $S_{\rm d.c.}^d$ 
        \begin{align}
            P:=\left(\begin{array}{ccccccc}
                3/4&\cdots&3/4&1&3/4&\cdots&3/4\\
                1/4&\cdots&1/4&0&1/4&\cdots&1/4
            \end{array}\right),\\
            Q:=\left(\begin{array}{ccccccc}
                7/8&\cdots&7/8&1&7/8&\cdots&7/8\\
                1/8&\cdots&1/8&0&1/8&\cdots&1/8
            \end{array}\right),
        \end{align}
        where the column containing a $0$ is the $\ell$-th column. Notice that $P\succeq Q$. A simple calculation shows that 
        \begin{equation}
            \Delta(P)=\gamma_\ell\left(\frac{3}{4}\log\frac{3}{4}+\frac{1}{4}\log\frac{1}{4}\right)\leq\gamma_\ell\left(\frac{7}{8}\log\frac{7}{8}+\frac{1}{8}\log\frac{1}{8}\right)=\Delta(Q), 
        \end{equation}
        with strict inequality if $\gamma_\ell>0$. This would imply that $\Delta$ is not monotone. Hence, we find that $\gamma_\ell=0$ for all $\ell\in[d-1]\setminus\{k\}$. Therefore, if $k\neq d$, 
        \begin{equation}
            \Delta(P)=\gamma_d\sum_{i\in{\rm supp}\,p^{(k)}}p_i^{(k)}\log\left(\frac{p_i^{(k)}}{\widetilde{p_i^{(d)}}}\right)=\gamma_d D_1\left(p^{(k)}\|p^{(d)}\right), 
        \end{equation}
        where we used that ${\rm supp}\,p^{(k)}\subseteq {\rm supp}\,p^{(d)}$ to identify the sum as the Kullback--Leibler divergence $D_1$. Note that the monotonicity of $\Delta$ follows from the data-processing inequality satisfied by $D_1$. For the case $k=d$, we have $\gamma_\ell=0$ for all $\ell\neq d$, hence $\Delta(P)=0$ for every $P\in S_{\rm d.c.}^d$.

\label{Mpro:poweruniversaldcgeneral}
    Let $U=(u^{(1)},\ldots,u^{(d)})\in S_{\rm d.c.}^d$ with all $u^{(k)}$ for $k\in[d]$, probability distributions. Then the following are equivalent: 
    \begin{enumerate}[(i)]
        \item $U$ is power universal. 
        \item It holds that ${\rm supp}\,u^{(k)}\subsetneq{\rm supp}\,u^{(d)}$ for all $k\in[d-1]$, and ${\rm supp}\,u^{(k)}\nsubseteq{\rm supp}\,u^{(k^\prime)}$ for all $k,k^\prime\in[d-1]$, $k\neq k^\prime$. 
        \item Any nondegenerate homomorphism
        \begin{equation}
            \Phi\in\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{R}_+)\cup\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{R}_+^{\rm op})\cup\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{T}\mathbb{R}_+)
        \end{equation}
        satisfies $\Phi(U)\neq1$. 
    \end{enumerate}

(iii) $\Rightarrow$ (ii): Note that for a monotone homomorphism $\Phi:S^d_{\rm d.c.}\to\mathbb{\mathbb{R}^{\rm op}}$, $\Phi(U)\neq1$ implies $\Phi(U)<1$. Since $\Phi_{e_d,\{k,d\}}(U)<1$ for $k\in[d-1]$, there is a row with a vanishing entry at $k$ and a positive value at $d$. Similarly, since $\Phi_{e_k,\{k,k^\prime,d\}}(U)<1$ for $k,k^\prime\in[d-1]$, $k\neq k^\prime$, there is a row with a vanishing entry at $k^\prime$ and a positive value at $k$. Hence, the conditions in (ii) are satisfied.  

    (ii) $\Rightarrow$ (i): From (ii), it follows that for each $k=2,\ldots,d-1$, $U$ has a row with positive entries at positions $1$ and $d$, and $0$ at position $k$. Then $U^{\boxtimes (d-2)}$ will contain the $\boxtimes$-product of these $d-2$ rows, which is a row with positive entries at positions $1$ and $d$, and $0$ everywhere else. Similarly, for the other columns $k^\prime=2,\ldots,d-1$, $U^{\boxtimes (d-2)}$ will contain a row with positive entries at positions $k^\prime$ and $d$ and $0$ everywhere else. Note that $U^{\boxtimes (d-1)}=U^{\boxtimes (d-2)}\boxtimes U$ will also contain rows of these specific types. From (ii) it also follows that for each $k=1,\ldots,d-1$, $U$ contains a row with a positive entry at position $d$ and $0$ at position $k$. Then $U^{\boxtimes (d-1)}$ will contain the $\boxtimes$-product of these $d-1$ rows, which is a row with a positive entry at position $d$ and $0$ everywhere else. One sees that it is possible to sum the rows in $U^{\boxtimes (d-1)}$ in such a way that 
    \begin{equation}
        \label{Meq:almostidentity}
        U^{\boxtimes (d-1)}\succeq\left(\begin{array}{cccc}
            a_1&\cdots&a_{d-1}&b_0\\
            1-a_1&\cdots&0&b_1\\
            0&\ddots&\vdots&\vdots\\
            0&\cdots&1-a_{d-1}&b_{d-1}\\
            0&\cdots&0&1-b			
        \end{array}\right):=\tilde{U}, 
    \end{equation}
    where $b:=\sum_{i=0}^{d-1}b_i$, and $a_k,b_i,b\in(0,1)$ for $k=1,\ldots,d-1$ and $i=0,\ldots,d-1$.                                                     










    Define the stochastic map (matrix) $T$ mapping probability vectors on $\{0,1,\ldots,d\}^2$ into probability vectors on $\{0,1.\ldots,d\}$ through
    \begin{equation}
    (Tp)_m=p_{m,m}+\sum_{j=0}^{m-1}\big(p_{j,m}+p_{m,j}\big),\qquad m=0,\ldots,d,
    \end{equation}
    for all $p=(p_{j,k})_{i,j=0}^d$ where empty sums $\sum_{j=0}^{-1}(\cdots)$ vanish. Also define matrices $U_\ell$ through $U_1=\tilde{U}$ and $U_{\ell+1}=T(\tilde{U}\boxtimes U_\ell)$ for all $\ell=1,2,\ldots$. One easily sees that $\tilde{U}^{\boxtimes\ell}\succeq U_\ell$ and a straightforward calculation combined with an induction argument shows that, for all $\ell\in\mathbb{N}$, there are $b^{(\ell)}_i$, $i=0,\ldots,d-1$ such that $b^{(\ell)}_0+\cdots+b^{(\ell)}_{d-1}=b^\ell$ and
    \begin{equation}\label{Meq:majorizedbyU}
        U_\ell= \left(\begin{array}{cccc}
            a_1^\ell&\cdots&a_{d-1}^\ell&b_0^{(\ell)}\\
            1-a_1^\ell&\cdots&0&b_1^{(\ell)}\\
            0&\ddots&\vdots&\vdots\\
            0&\cdots&1-a_{d-1}^\ell&b_{d-1}^{(\ell)}\\
            0&\cdots&0&1-b^\ell		
        \end{array}\right).
    \end{equation}

    Hence, by choosing $\ell$ sufficiently large, we can make $a_k^\ell$ for $k=1,\ldots,d-1$ and $b_i^{(\ell)}$ for $i=0,\ldots, d-1$ arbitrarily small. 

Let $P=\big(p^{(1)},\ldots,p^{(d)}\big)\in \mathcal{V}_{\rm d.c.}^d$ with columns of unit $1$-norm, where $p^{(k)}=\big(p^{(k)}_1,\ldots,p^{(k)}_n\big)$. We may assume WLOG that $p^{(k)}_1>0$ for $k=1,\ldots,d$. Let us write $p_1:=\min_{1\leq k\leq d-1}p^{(k)}_1>0$, $t^{(0)}:=(1,0,\ldots,0)$ (with $n$ entries), and 
\begin{equation}
t^{(k)}_v:=\frac{1}{1-v}\big(p^{(k)}-vt^{(0)}\big)
\end{equation}
for $v\in(0,p_1)$ and $k=1,\ldots,d-1$. For any $v=(v_1,\ldots,v_{d-1})\in(0,p_1)^{d-1}$ and $w=(w_0,\ldots,w_{d-1})\in\mathbb{R}_{>0}^d$ such that $w_0+\cdots+w_{d-1}<1$, let us also define
\begin{equation}
t^{(d)}_{v,w}:=\frac{1}{1-w_0-\cdots-w_{d-1}}\big(p^{(d)}-w_0 t^{(0)}-w_1 t^{(1)}_{v_1}-\cdots-w_{d-1}t^{(d-1)}_{v_{d-1}}\big).
\end{equation}
A sufficient condition for $t^{(d)}_{v,w}$ to be a probability vector is
\begin{align}
p^{(d)}_1-w_0-\sum_{k=1}^{d-1}w_k\frac{p^{(k)}_1}{1-p_1}&\geq0,\\
p^{(d)}_i-\sum_{k=1}^{d-1}w_k\frac{p^{(k)}_i}{1-p_1}&\geq0,\qquad i=2,\ldots,n,
\end{align}
independent of $v_1,\ldots,v_{d-1}$. Thus, there is $w=(w_0,\ldots,w_{d-1})\in\mathbb{R}_{>0}^{d}$ such that $t^{(d)}_{v,w'}$ is a probability vector for all $v\in(0,p_1)^{d-1}$ and $w'\in\mathbb{R}_{>0}^d$ whose entries are upper-bounded by those of $w$. Suppose then that $\ell\in\mathbb{N}$ is large enough so that $a_k^\ell<p_1$ for $k=1,\ldots,d-1$ and $b^\ell<w_i$ (so that $b^{(\ell)}_i\leq b^\ell<w_i$) for $i=0,\ldots,d-1$ where $a_k$, $b_i$, and $b^{(\ell)}_i$ are as in \eqref{Meq:almostidentity} and \eqref{Meq:majorizedbyU}. Setting $v:=\big(a_1^\ell,\ldots,a_{d-1}^\ell\big)$ and $w':=\big(b_0^{(\ell)},\ldots,b_{d-1}^{(\ell)}\big)$ and $t^{(k)}:=t^{(k)}_{v}$ for $k=1,\ldots,d-1$ and $t^{(d)}:=t^{(d)}_{v,w'}$, we may set up the stochastic matrix $T=\big(t^{(0)},\ldots,t^{(d)}\big)$. It follows that we may write $TU_\ell=P$, i.e.,\ $U^{\boxtimes\ell(d-1)}\succeq\tilde{U}^{\boxtimes\ell}\succeq U_\ell\succeq P$.

We now have shown that, for all $P\in\mathcal{V}^d_{\rm d.c.}$ with columns of unit $1$-norm, there is $\ell\in\mathbb{N}$ such that $U^{\boxtimes\ell}\succeq P$. Let us assume next that $P,Q\in\mathcal{V}_{\rm d.c.}^d$ are such that $P\succeq Q$. WLOG we may assume that the columns of $P$ and $Q$ have unit 1-norm. Thus, there is $\ell\in\mathbb{N}$ such that
\begin{equation}
Q\boxtimes U^{\boxtimes\ell}\succeq(1\,\cdots\,1)\boxtimes U^{\boxtimes\ell}=U^{\boxtimes\ell}\succeq P,
\end{equation}
showing that $U$ is a power universal.

(i) $\Rightarrow$ (iii): Let $P\in\mathcal{V}^d_{\rm d.c.}$ be such that all the columns of $P$ have unit 1-norm and $\Phi(P)\neq 1$ for all the nondegenerate monotone homomorphisms of $S^d_{\rm d.c.}$ into $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$. We may choose, e.g.,
\begin{equation}
P=\left(\begin{array}{cccc}
1/2&\cdots&1/2&1/d\\
1/2&\cdots&0&1/d\\
\vdots&\ddots&\vdots&\vdots\\
0&\cdots&1/2&1/d
\end{array}\right), 
\end{equation}
for which $\Phi(P)>1$ when $\Phi\in\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{R}_+)\cup\mathcal{H}^{\rm d.c.}(S^d_{\rm d.c.},\mathbb{T}\mathbb{R}_+)$ and $\Phi(P)<1$ otherwise. According to (i), there is $\ell\in\mathbb{N}$ such that $U^{\boxtimes\ell}\succeq P$, so that $\Phi(U)^\ell\geq\Phi(P)>1$ for $\Phi\in\mathcal{H}^{\rm n.d.}(S^d_{\rm d.c.},\mathbb{R}_+)\cup\mathcal{H}^{\rm d.c.}(S^d_{\rm d.c.},\mathbb{T}\mathbb{R}_+)$ and $\Phi(U)^\ell\leq\Phi(P)<1$ otherwise. All in all, $\Phi(U)\neq1$ for all the monotone homomorphisms.

Note that, according to item (ii) of Proposition \ref{Mpro:poweruniversaldcgeneral} and item (iii) of Proposition \ref{Mlem:poweruniversalconditions}, $U=\big(u^{(1)},\ldots,u^{(d)}\big)$ is a power universal of $S^d_{\rm d.c.}$ if and only if $\big(u^{(1)},\ldots,u^{(d-1)}\big)$ is a power universal of $S^{d-1}$ (n.b.,\ {\it not} of $S^{d-1}_{\rm d.c.}$) and ${\rm supp}\,u^{(k)}\subsetneq{\rm supp}\,u^{(d)}$ for $k=1,\ldots,d-1$. 

For $d=2$, $U=\big(u^{(1)},u^{(2)}\big)$ is a power universal of $S^d_{\rm d.c.}$ if and only if ${\rm supp}\,u^{(1)}\subsetneq{\rm supp}\,u^{(2)}$. For $d=3$, the general form of a power universal, up to the $\approx$-equivalence, is
\begin{equation}
U=\left(\begin{array}{ccc}
*&*&*\\
*&0&*\\
0&*&*
\end{array}\right), 
\end{equation}
where the asterisks represent positive entries (or vectors with positive entries).

\label{Mthm:majorizationdominatingcolumn}
		Let $P=(p^{(1)},\ldots,p^{(d)})$, $Q=(q^{(1)},\ldots,q^{(d)})$ be tuples of probability vectors such that $\bigcap_{k=1}^d{\rm supp}\,p^{(k)}\neq\emptyset$ and ${\rm supp}\,p^{(k)}\subseteq{\rm supp}\,p^{(d)}$ for $k\in[d-1]$, and similarly for $Q$. If the inequalities in \eqref{Meq:majorizationconditionsdominatingcolumn1}, \eqref{Meq:majorizationconditionsdominatingcolumn2}, \eqref{Meq:majorizationconditionsdominatingcolumn3} and \eqref{Meq:majorizationconditionsdominatingcolumn4} hold, then we have the following: 
		\begin{enumerate}[(a)]
			\item There exist a stochastic map $T$ and a tuple of probability vectors $(r^{(1)},\ldots,r^{(d)})$, satisfying $\bigcap_{k=1}^d{\rm supp}\,r^{(k)}\neq\emptyset$ and ${\rm supp}\,r^{(k)}\subseteq{\rm supp}\,r^{(d)}$ for $k\in[d-1]$, such that
			\begin{equation}
				T(r^{(k)}\otimes p^{(k)})=r^{(k)}\otimes q^{(k)}\quad\text{for }k\in[d], 
			\end{equation}
			and we may choose, for $n$ sufficiently large, 
			\begin{equation}
				r^{(k)}=\frac{1}{n+1}\bigoplus_{\ell=0}^n\left(q^{(k)}\right)^{\otimes \ell}\otimes\left(p^{(k)}\right)^{\otimes(n-\ell)}\quad\text{ for }k\in[d]. 
			\end{equation}
			\item For $n$ sufficiently large there exists a stochastic map $T_n$ such that 
			\begin{equation}
				T_n(p^{(k)})^{\otimes n}=(q^{(k)})^{\otimes n}\quad\text{for }k\in[d]. 
			\end{equation}
		\end{enumerate}
		Conversely, if either one of these holds, then the inequalities \eqref{Meq:majorizationconditionsdominatingcolumn1}, \eqref{Meq:majorizationconditionsdominatingcolumn2}, \eqref{Meq:majorizationconditionsdominatingcolumn3} and \eqref{Meq:majorizationconditionsdominatingcolumn4} hold non-strictly.

\label{Mcor:dichotomyexact}
Let $\big(p^{(1)},p^{(2)}\big)$ and $\big(q^{(1)},q^{(2)}\big)$ be dichotomies. If
\begin{equation}\label{Meq:RenyiOrdered}
D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)>D_\alpha\big(q^{(1)}\big\|q^{(2)}\big),\qquad\forall\alpha\in[0,\infty],
\end{equation}
then we have the following:
\begin{itemize}
\item[(a)] There is a stochastic matrix $T$ and a dichotomy $\big(r^{(1)},r^{(2)}\big)$ such that
\begin{equation}
T\big(r^{(k)}\otimes p^{(k)}\big)=r^{(k)}\otimes q^{(k)},\qquad k=1,2.
\end{equation}
There is $n\in\mathbb{N}$ such that we may choose
\begin{equation}\label{Meq:BinomialCatalyst}
r^{(k)}=\frac{1}{n+1}\bigoplus_{\ell=0}^n \big(q^{(k)}\big)^{\otimes\ell}\otimes\big(p^{(k)}\big)^{\otimes(n-\ell)},\quad k=1,2.
\end{equation}
\item[(b)] For any $n\in\mathbb{N}$ sufficiently large, there is a stochastic matrix $T_n$ such that
\begin{equation}
T_n\big(p^{(k)}\big)^{\otimes n}=\big(q^{(k)}\big)^{\otimes n},\qquad k=1,2.
\end{equation}
\end{itemize}
Conversely, if item (a) or (b) above holds, then \eqref{Meq:RenyiOrdered} holds with non-strict inequalities.

\label{Mthm:asymptocatalytic}

Consider dichotomies $\big(p^{(1)},p^{(2)}\big)$ and $\big(q^{(1)},q^{(2)}\big)$                                            
and assume ${\rm supp}\,p^{(1)}\subsetneq{\rm supp}\,p^{(2)}$. The following conditions are equivalent:
\begin{itemize}
\item[(i)] For all $\alpha\in(0,\infty]$,
\begin{equation}\label{Meq:0alphainfty}
D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)\geq D_\alpha\big(q^{(1)}\big\|q^{(2)}\big).
\end{equation}
\item[(ii)] For all $\varepsilon>0$, there is a stochastic matrix $T_\varepsilon$ and dichotomies $\big(q_\varepsilon^{(1)},q_\varepsilon^{(2)}\big)$ and $\big(r_\varepsilon^{(1)},r_\varepsilon^{(2)}\big)$ such that
\begin{equation}
\big\|q^{(k)}-q^{(k)}_\varepsilon\big\|_1\leq\varepsilon,\qquad k=1,2,
\end{equation}
and
\begin{equation}
T_\varepsilon\big(r_\varepsilon^{(k)}\otimes p^{(k)}\big)=r_\varepsilon^{(k)}\otimes q_\varepsilon^{(k)},\qquad k=1,2.
\end{equation}
Again, we may choose $r_\varepsilon^{(k)}$ as in \eqref{Meq:BinomialCatalyst} (with $q_\varepsilon^{(k)}$ substituted for $q^{(k)}$) for sufficiently large $n\in\mathbb{N}$.
\item[(iii)] For all $\varepsilon>0$, there is a dichotomy $\big(q_\varepsilon^{(1)},q_\varepsilon^{(2)}\big)$                                       
such that
\begin{equation}
\big\|q^{(k)}-q_\varepsilon^{(k)}\big\|_1\leq\varepsilon,\qquad k=1,2,
\end{equation}
and for $n\in\mathbb{N}$ sufficiently large there is a stochastic matrix $T_{\varepsilon,n}$ such that
\begin{equation}
T_{\varepsilon,n}\big(p^{(k)}\big)^{\otimes n}=\big(q_\varepsilon^{(k)}\big)^{\otimes n},\qquad k=1,2.
\end{equation}
\end{itemize}
In statements (ii) and (iii) above, we may assume that $q_\varepsilon^{(2)}=q^{(2)}$ for all $\varepsilon>0$.

Let us assume condition (i). Let us choose $w\in\mathcal{P}_n$ which dominates $q^{(2)}$ (and, hence, automatically $q^{(1)}$). Naturally, we may choose $w=q^{(2)}$; this choice yields the final claim of the statement of the theorem, as one clearly subsequently sees. Let us denote, for brevity, $\big(p^{(1)},p^{(2)}\big)=:P$, $\big(q^{(1)},q^{(2)}\big)=:Q$, and $W:=(w,w)$ and define, for all $\varepsilon\in(0,2]$,
\begin{equation}
q^{(k)}_\varepsilon:=\left(1-\frac{\varepsilon}{2}\right)q^{(k)}+\frac{\varepsilon}{2}w,\qquad k=1,2,
\end{equation}
and
\begin{equation}
Q_\varepsilon:=\big(q^{(1)}_\varepsilon,q^{(2)}_\varepsilon\big)=\left(1-\frac{\varepsilon}{2}\right)Q+\frac{\varepsilon}{2}W.
\end{equation}
Clearly, $Q_\varepsilon$ is a dichotomy with mutually supporting columns for all $\varepsilon\in(0,2]$. Moreover, $\big\|q^{(k)}-q^{(k)}_\varepsilon\big\|_1\leq\varepsilon$, as one easily verifies. We may show that $D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)>D_\alpha\big(q^{(1)}_\varepsilon\big\|q^{(2)}_\varepsilon\big)$ for all $\alpha\in[0,1)$ in the same way as in the proof of Theorem \ref{Mthm:genasymptocatalytic}.

Using the joint convexity of the Kullback--Leibler divergence, we have, for all $\varepsilon\in(0,2]$,
\begin{align}
D_1\big(q^{(1)}_\varepsilon\big\|q^{(2)}_\varepsilon\big)&\leq \left(1-\frac{\varepsilon}{2}\right)D_1\big(q^{(1)}\big\|q^{(2)}\big)+\frac{\varepsilon}{2}\underbrace{D_1(w\|w)}_{=0}\\
&\leq D_1\big(q^{(1)}\big\|q^{(2)}\big)\leq D_1\big(p^{(1)}\big\|p^{(2)}\big).
\end{align}
If $D_1\big(q^{(1)}\big\|q^{(2)}\big)=0$, then $D_1\big(q^{(1)}\big\|q^{(2)}\big)=0<D_1\big(p^{(1)}\big\|p^{(2)}\big)$ since $p^{(1)}\neq p^{(2)}$. If, on the other hand, $D_1\big(q^{(1)}\big\|q^{(2)}\big)>0$, then the penultimate inequality in the above calculation is strict. Thus, we have
\begin{equation}
D_1\big(q^{(1)}_\varepsilon\big\|q^{(2)}_\varepsilon\big)<D_1\big(p^{(1)}\big\|p^{(2)}\big),\qquad\forall\varepsilon\in(0,2].
\end{equation}

Let now $\alpha\in(1,\infty)$ and denote $\Phi_\alpha:=\Phi_{(\alpha,1-\alpha),\{1,2\}}$. Similarly as in the proof of Theorem \ref{Mthm:genasymptocatalytic}, we may evaluate, for all $\varepsilon\in(0,2]$,
\begin{align}
D_\alpha\big(q^{(1)}_\varepsilon\big\|q^{(2)}_\varepsilon\big)&\leq\frac{1}{\alpha-1}\log{\bigg(\Phi_\alpha(Q)-\frac{\varepsilon}{2}\underbrace{\big(\Phi_\alpha(Q)-1\big)}_{\geq0}\bigg)}\\
&\leq\frac{1}{\alpha-1}\log{\Phi_\alpha(Q)}=D_\alpha\big(q^{(1)}\big\|q^{(2)}\big)\leq D_\alpha\big(p^{(1)}\big\|p^{(2)}\big).
\end{align}
If $\Phi_\alpha(Q)=1$, then $\Phi_\alpha(Q)=1<\Phi_\alpha(P)$ and the final inequality above is strict. If $\Phi_\alpha(Q)>1$, then the penultimate inequality above is strict. Thus,
\begin{equation}
D_\alpha\big(q^{(1)}_\varepsilon\big\|q^{(2)}_\varepsilon\big)<D_\alpha\big(p^{(1)}\big\|p^{(2)}\big),\qquad\forall\varepsilon\in(0,2].
\end{equation}

Let us then look at the tropical homomorphism $\Phi^\mathbb{T}_1$. Using monotonicity, we have, for all $\varepsilon\in(0,2]$,
\begin{align}
\Phi^\mathbb{T}_1(Q_\varepsilon)&=\Phi^\mathbb{T}_1\left(\left(1-\frac{\varepsilon}{2}\right)Q+\frac{\varepsilon}{2}W\right)\leq\Phi^\mathbb{T}_1\left(\left(1-\frac{\varepsilon}{2}\right)Q\boxplus\frac{\varepsilon}{2}W\right)\\
&=\max\big\{\Phi^\mathbb{T}_1(Q),1\big\}=\Phi^\mathbb{T}_1(Q)\leq\Phi^\mathbb{T}_1(P).
\end{align}
Especially, $\Phi^\mathbb{T}_1(Q_\varepsilon)\leq\Phi^\mathbb{T}_1(Q)$, i.e.,
\begin{equation}
\max_{1\leq i\leq n}\frac{\left(1-\frac{\varepsilon}{2}\right)q^{(1)}_i+\frac{\varepsilon}{2}w_i}{\left(1-\frac{\varepsilon}{2}\right)q^{(2)}_i+\frac{\varepsilon}{2}w_i}\leq\max_{1\leq i\leq n}\frac{q^{(1)}_i}{q^{(2)}_i}
\end{equation}
for all $\varepsilon\in(0,2]$. When $0<\varepsilon\leq\varepsilon'\leq 2$, then $Q_\varepsilon\succeq Q_{\varepsilon'}$, implying that the LHS above is non-increasing in $\varepsilon$ and coincides with the RHS when $\varepsilon\to0$. Thus, if we have equality with some $\varepsilon_0\in(0,2]$, then we have equality for all $\varepsilon\in[0,\varepsilon_0]$. Let us assume this. Since the LHS is a pointwise maximum of a finite set of real-analytic functions, the maximum is reached with the same index $i$ for all $\varepsilon\in[0,\varepsilon_0]$. The real-analyticity of the LHS now implies that the LHS is constant for all $\varepsilon\in[0,2]$, i.e.,\ $\Phi^\mathbb{T}_1(Q)=1=\Phi^\mathbb{T}_1(W)$. Thus, if $\Phi^\mathbb{T}_1(Q_\varepsilon)=\Phi^\mathbb{T}_1(Q)$ for some $\varepsilon\in(0,2]$, this is the case for all $\varepsilon\in[0,2]$ and $\Phi^\mathbb{T}_1(Q)=1<\Phi^\mathbb{T}_1(P)$. On the other hand, if $\Phi^\mathbb{T}_1(Q)>1$ then $\Phi^\mathbb{T}(Q_\varepsilon)<\Phi^\mathbb{T}(Q)$, so that $\Phi^\mathbb{T}_1(Q_\varepsilon)<\Phi^\mathbb{T}_1(Q)\leq\Phi^\mathbb{T}_1(P)$. All in all,
\begin{equation}
D_\infty\big(q^{(1)}_\varepsilon\big\|q^{(2)}_\varepsilon\big)<D_\infty\big(p^{(1)}\big\|p^{(2)}\big),\qquad\forall\varepsilon\in(0,2].
\end{equation}
Thus, the conditions of Corollary \ref{Mcor:dichotomyexact} are satisfied for $Q_\varepsilon$ and $P$, and conditions (ii) and (iii) of the claim follow.

Let us then assume that (ii) or (iii) holds. The proof that $D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)\geq D_\alpha\big(q^{(1)}\big\|q^{(2)}\big)$ for $\alpha\in(0,1)$ follows from the same argument as in the end of the proof of Theorem \ref{Mthm:genasymptocatalytic}. To show the inequality for $\alpha\in(1,\infty)$, we use almost the same argument: consider any $D_\alpha$ with $\alpha\in(1,\infty)$, which corresponds to the monotone homomorphism $\Phi_{\alpha,1}$. Then we use similar notation and reasoning as in the proof of Theorem \ref{Mthm:genasymptocatalytic}, except that $\Phi=\Phi_{\alpha,1}$ and the direction of the inequalities is reversed, and we note that 
\begin{equation}
    \Phi_{\alpha,1}(Q_\varepsilon^1\boxplus(1\,\cdots\,1))\geq(1+\varepsilon)^{1-\alpha}, 
\end{equation}
where we used monotonicity of $\Phi_{\alpha,1}$ and that the sum of each column in $Q_\varepsilon^1\boxplus(1\,\cdots\,1)$ is between $1$ and $1+\varepsilon$. Finally, the inequalities $D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)\geq D_\alpha\big(q^{(1)}\big\|q^{(2)}\big)$ for $\alpha\in\{1,\infty\}$ follow from the same inequalities for $\alpha\in(0,1)\cup(1,\infty)$ and the continuity of $D_\alpha$ in $\alpha$.

\label{Mcor:asymptocatalytic}
Denote by $\mathcal{P}_n$ the set of probability vectors with $n$ components and consider probability vectors $p^{(2)},q^{(2)}\in\mathcal{P}_n$ of full support and some additional $p^{(1)},q^{(1)}\in\mathcal{P}_n$. Also assume that $p^{(1)}\neq p^{(2)}$. The following conditions are equivalent:
\begin{itemize}
\item[(i)] For all $\alpha\geq 1/2$,
\begin{equation}\label{Meq:jointcond}
D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)\geq D_\alpha\big(q^{(1)}\big\|q^{(2)}\big),\qquad D_\alpha\big(p^{(2)}\big\|p^{(1)}\big)\geq D_\alpha\big(q^{(2)}\big\|q^{(1)}\big).
\end{equation}
\item[(ii)] For all $\varepsilon>0$, there is a stochastic matrix $T_\varepsilon$ and dichotomies $\big(q_\varepsilon^{(1)},q_\varepsilon^{(2)}\big)$ and $\big(r_\varepsilon^{(1)},r_\varepsilon^{(2)}\big)$ such that
\begin{equation}
\big\|q^{(k)}-q^{(k)}_\varepsilon\big\|_1\leq\varepsilon,\qquad k=1,2,
\end{equation}
and
\begin{equation}
T_\varepsilon\big(r_\varepsilon^{(k)}\otimes p^{(k)}\big)=r_\varepsilon^{(k)}\otimes q_\varepsilon^{(k)},\qquad k=1,2.
\end{equation}
Again, we may choose $r_\varepsilon^{(k)}$ as in \eqref{Meq:BinomialCatalyst} (with $q_\varepsilon^{(k)}$ substituted for $q^{(k)}$) for sufficiently large $n\in\mathbb{N}$.
\item[(iii)] For all $\varepsilon>0$, there is a dichotomy $\big(q_\varepsilon^{(1)},q_\varepsilon^{(2)}\big)$ with probability vectors in $\mathcal{P}_n$
such that
\begin{equation}
\big\|q^{(k)}-q_\varepsilon^{(k)}\big\|_1\leq\varepsilon,\qquad k=1,2,
\end{equation}
and for $n\in\mathbb{N}$ sufficiently large there is a stochastic matrix $T_{\varepsilon,n}$ such that
\begin{equation}
T_{\varepsilon,n}\big(p^{(k)}\big)^{\otimes n}=\big(q_\varepsilon^{(k)}\big)^{\otimes n},\qquad k=1,2.
\end{equation}
\end{itemize}
In statements (ii) and (iii), we may assume that $q_\varepsilon^{(2)}=q^{(2)}$ for all $\varepsilon>0$.

Let us first assume that ${\rm supp}\,p^{(1)}={\rm supp}\,p^{(2)}=\{1,\ldots,n\}$ and ${\rm supp}\,q^{(1)}={\rm supp}\,q^{(2)}=\{1,\ldots,n\}$. In this case, the desired result is given by Theorem 22 in \cite{farooq2024}. Strictly speaking, only the equivalence of statements (i) and (ii) is shown there, but adding (iii) can be done in the same way that we have already employed earlier.

Let us now assume that ${\rm supp}\,p^{(1)}\subsetneq{\rm supp}\,p^{(2)}$ or ${\rm supp}\,q^{(1)}\subsetneq{\rm supp}\,q^{(2)}$. Let us first show that the latter case is out of the question if the first one does not hold. So, assume that ${\rm supp}\,p^{(1)}={\rm supp}\,p^{(2)}$ while ${\rm supp}\,q^{(1)}\subsetneq{\rm supp}\,q{(2)}$. If we assume (i), we obtain from the second set of inequalities that
\begin{equation}
1=\sum_{i\in{\rm supp}\,p^{(1)}}p^{(2)}_i\leq\sum_{i\in{\rm supp}\,q^{(1)}}q^{(2)}_i<1
\end{equation}
as $\alpha\to 1$, a contradiction. Thus, we only have to consider the case where ${\rm supp}\,p^{(1)}\subsetneq{\rm supp}\,p^{(2)}$. In this case, the second set of the inequalities in \eqref{Meq:jointcond} are irrelevant when $\alpha\geq1$. Indeed, $D_\alpha\big(p^{(2)}\big\|p^{(1)}\big)=\infty$ when $\alpha\geq1$. Thus we may ignore this set of inequalities. For $0<\alpha\leq1/2$, we have $D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)=\frac{1-\alpha}{\alpha}D_{1-\alpha}\big(p^{(2)}\big\|p^{(1)}\big)$. This means that, if (i) holds, then $D_\alpha\big(p^{(1)}\big\|p^{(2)}\big)\geq D_\alpha\big(q^{(1)}\big\|q^{(2)}\big)$ for all $\alpha>0$. Naturally this also holds for $\alpha=0$ as a pointwise limit of the above. Finally, condition (i) is equivalent with \eqref{Meq:0alphainfty}, and we are in the situation of Theorem \ref{Mthm:asymptocatalytic} providing the proof for the remainder of the claim.

\label{Mcor:thermal}
Suppose that the eigen-energies $E_i>0$ for all $i$, and $\rho$ and $\sigma$ diagonalize in the energy eigenbasis. Then $\rho$ asymptotically catalytically thermally majorizes $\sigma$ if and only if
\begin{equation}
F^\pm_{\alpha,\beta}(\rho)\geq F^\pm_{\alpha,\beta}(\sigma),\qquad\forall\alpha\geq\frac{1}{2}.
\end{equation}

\label{con:puconditiongeneral}
Let $\Xi$ be a collection of support conditions and $U\in S^d_\Xi$ with normalized columns. Then $U$ is power universal in $S^d_\Xi$ if and only if it satisfies the following for every pair of columns $k,k'\in[d]$, $k\neq k'$, according to the condition $\Xi(k,k')$: 

\vspace{1mm}
\begin{center}
    \begin{tabular}{|c|c|}
        \hline
        Condition $\Xi(k,k')$&Condition on $U\in S_\Xi^d$\\
        \hline
        \textup{$\textrm{`}\!\!\subseteq\!\!\text{'}$}&${\rm supp}\,u^{(k)}\subsetneq{\rm supp}\,u^{(k^\prime)}$\\
        \textup{$\textrm{`}\!\!\supseteq\!\!\text{'}$}&${\rm supp}\,u^{(k)}\supsetneq{\rm supp}\,u^{(k^\prime)}$\\
        \textup{$\textrm{`}\!\!=\!\!\text{'}$}&${\rm supp}\,u^{(k)}={\rm supp}\,u^{(k^\prime)}$ and $u^{(k)}\neq u^{(k^\prime)}$\\
        \textup{$\textrm{`}\!\!\times\!\!\text{'}$}&${\rm supp}\,u^{(k)}\nsubseteq{\rm supp}\,u^{(k^\prime)}$ and ${\rm supp}\,u^{(k^\prime)}\nsubseteq{\rm supp}\,u^{(k)}$\\
        \hline
    \end{tabular}
\end{center}

\label{thm:approximateLS}
    Let $(\rho,\sigma)$, $(\rho',\sigma')$ be two pairs of states in $\mathcal{F}$, where $\rho$, $\sigma$ are non-parallel (i.e. satisfy \eqref{eq:pu1}) and $\rho'$, $\sigma'$ do not commute. Consider the following statements: 
    \begin{enumerate}[(i)]
        \item $D_{\alpha,z}(\rho\|\sigma)\geq D_{\alpha,z}(\rho'\|\sigma')$ when $\alpha\in(0,1)$ and $z>\max\{\alpha,1-\alpha\}$. 
        \item For each $\varepsilon>0$, there exist a state $\rho'_\varepsilon$ such that $F(\rho'_\varepsilon,\rho')\geq1-\varepsilon$, and a quantum channel $\mathcal{C}_{\varepsilon,n}$ for $n\geq n_\varepsilon$ large enough such that $\mathcal{C}_{\varepsilon,n}(\rho^{\otimes n})=(\rho'_\varepsilon)^{\otimes n}$ and $\mathcal{C}_{\varepsilon,n}(\sigma^{\otimes n})=(\sigma')^{\otimes n}$. 
        \item For each $\varepsilon>0$, there exist a state $\rho'_\varepsilon$ such that $F(\rho'_\varepsilon,\rho')\geq1-\varepsilon$, a quantum channel $\mathcal{C}_\varepsilon$, and a catalyzer pair $(\tau_\varepsilon$, $\omega_\varepsilon)\in\mathcal{F}$ such that 
        \begin{equation}
            \mathcal{C}_\varepsilon(\rho\otimes\tau_\varepsilon)=\rho'_\varepsilon\otimes\tau_\varepsilon\quad\text{and}\quad \mathcal{C}_\varepsilon(\sigma\otimes\omega_\varepsilon)=\sigma'\otimes\omega_\varepsilon. 
        \end{equation}
        Statements (i) and (iii) are equivalent. If $(\rho,\sigma)$ furthermore satisfies \eqref{eq:pu2}, then (i), (ii) and (iii) are equivalent. 
    \end{enumerate}

\label{thm:minimal}
     Let $O$ be a non-empty open subset of $R$. There exist pairs $(\rho,\sigma)$, $(\rho',\sigma')$ in $\mathcal{F}$, where $\rho$, $\sigma$ are non-parallel and satisfy \eqref{eq:pu2}, and $\rho'$, $\sigma'$ do not commute, such that 
     \begin{equation}\label{eq:smallercondition}
         D_{\alpha,z}(\rho\|\sigma)\geq D_{\alpha,z}(\rho'\|\sigma')\ \text{when}\ (\alpha,z)\in R\setminus O, 
     \end{equation}
     but both (ii) and (iii) of Theorem \ref{thm:approximateLS} do not hold.

\label{thm:rates}
    For pairs $(\rho,\sigma)$ and $(\rho',\sigma')$ of states in $\mathcal{F}$, where $\rho$, $\sigma$ are non-parallel and satisfy \eqref{eq:pu2}, the optimal conversion rate from $(\rho, \sigma)$ to $(\rho', \sigma')$ is                                                      
    \begin{align}
    &r\big((\rho,\sigma)\to(\rho',\sigma')\big)=\inf\left\{\,\frac{D_{\alpha,z}(\rho\|\sigma)}{D_{\alpha,z}(\rho'\|\sigma')}\,\middle|\,\begin{array}{l}\alpha\in(0,1),\\z>\max\{\alpha,1-\alpha\}\end{array}\,\right\}&\label{eq:rate1}\\
    &\quad=\min\left\{\,\frac{\hat{D}_{\alpha,z}(\rho\|\sigma)}{\hat{D}_{\alpha,z}(\rho'\|\sigma')}\,\middle|\,\begin{array}{l}\alpha\in[0,1],\\z\geq\max\{\alpha,1-\alpha\}\end{array}\,\right\}\cup\left\{\frac{\hat{D}^\mathbb{T}(\rho\|\sigma)}{\hat{D}^\mathbb{T}(\rho'\|\sigma')}\right\}.&\label{eq:rate2} 
    \end{align}

\label{propo:Uhlmann}
    Let $\ket{\alpha_1},\ket{\beta_1}\in\mathcal{H}_1$ and $\ket{\alpha_2},\ket{\beta_2}\in\mathcal{H}_2$ be normalized vectors in some Hilbert spaces $\mathcal{H}_1,\mathcal{H}_2$. Then 
    \begin{equation}
        (\,\ketbra{\alpha_1}{\alpha_1},\ketbra{\beta_1}{\beta_1}\,)\succeq(\,\ketbra{\alpha_2}{\alpha_2},\ketbra{\beta_2}{\beta_2}\,)\quad\Longleftrightarrow\quad|\braket{\alpha_1}{\beta_1}|\leq|\braket{\alpha_2}{\beta_2}|. 
    \end{equation}

Let us first consider a simpler case where we show that a pair $(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})$ of pure states such that $0<|\braket{\alpha}{\beta}|<1$ is a power universal of $S_{\rm e.o.}$. To this end, let us fix $(A',B')\in S_{\rm e.o.}$ such that $\mathrm{Tr}[A']=1=\mathrm{Tr}[B']$, where
\begin{equation}\label{eq:a'b'}
    A'=\bigoplus_{i=1}^{n'}p'_i\ketbra{\alpha'_i}{\alpha'_i},\quad B'=\bigoplus_{i=1}^{n'}q'_i\ketbra{\beta'_i}{\beta'_i}.
\end{equation}
Since we are within $S_{\rm e.o.}$, we may assume that $p'_i,q'_i>0$ for all $i=1,\ldots,n'$. We next show that 
\begin{equation}
    (\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})^{\boxtimes m}\succeq (A',B')
\end{equation}    
for $m\in\mathbb{N}$ sufficiently large.                                                                                                                                                                                                                                                                                                                                                                                                          








Let us denote $F:=|\braket{\alpha}{\beta}|^2$. Let $m_0\in\mathbb{N}$ be such that $F^m p'_i<q'_i$ for all $m\geq m_0$ and $i=1,\ldots,n'$. Let $\ket{\alpha_m^\perp}$ be a unit vector in the 2-dimensional Hilbert space $\mathcal{M}_m$ spanned by $\ket{\alpha}^{\otimes m}$ and $\ket{\beta}^{\otimes m}$ which is perpendicular to $\ket{\alpha}^{\otimes m}$ for all $m\in\mathbb{N}$. It follows that we may define, for all $m\geq m_0$, the positive-operator-valued measure $E^m=(E^m_i)_{i=1}^{n'}$ on $\mathcal{M}_m$ through
\begin{equation}
E^m_i=p'_i\ketbra{\alpha}{\alpha}^{\otimes m}+\frac{q'_i-F^mp'_i}{1-F^m}\ketbra{\alpha_m^\perp}{\alpha_m^\perp}.
\end{equation}
In what follows, we write, e.g.,\ $|\alpha^{\otimes m}\rangle:=|\alpha\rangle^{\otimes m}$. Through a straightforward calculation, we find that
\begin{equation}
\left\langle\alpha^{\otimes m}\middle|E^m_i\middle|\alpha^{\otimes m}\right\rangle=p'_i,\qquad \left\langle\beta^{\otimes m}\middle|E^m_i\middle|\beta^{\otimes m}\right\rangle=q'_i.
\end{equation}
Let us define the unit vectors $\big|\tilde{\beta}_i^m\big\rangle=(q'_i)^{-1/2}(E^m_i)^{1/2}\ket{\beta}^{\otimes m}$. It is easily seen that
\begin{equation}
\big\langle\alpha^{\otimes m}\big|\tilde{\beta}_i^m\big\rangle
=\sqrt{p'_i/q'_i}\braket{\alpha}{\beta}^m\to 0
\end{equation}
as $m\to\infty$. Since $|\braket{\alpha'_i}{\beta'_i}|>0$ for $i=1,\ldots,n'$, there is $m_1\in\mathbb{N}$, $m_1\geq m_0$, such that, for any $m\geq m_1$ and $i=1,\ldots,n'$, $|\big\langle\alpha^{\otimes m}\big|\tilde{\beta}_i^m\big\rangle|\leq|\braket{\alpha'_i}{\beta'_i}|$. Then, according to Proposition \ref{propo:Uhlmann}, for any $m\geq m_1$ and $i=1,\ldots,n'$, there is a channel $\mathcal{C}^m_i$ such that $\mathcal{C}^m_i(\ketbra{\alpha}{\alpha}^{\otimes m})=\ketbra{\alpha'_i}{\alpha'_i}$ and $\mathcal{C}^m_i\big(\big|\tilde{\beta}_i^m\big\rangle\big\langle\tilde{\beta}_i^m\big|\big)=\ketbra{\beta'_i}{\beta'_i}$. Thus, when $m\geq m_1$, we may define the channel $\mathcal{C}_m$ through
\begin{equation}
\mathcal{C}_m(\tau)=\bigoplus_{i=1}^{n'}\mathcal{C}_i^m\big((E^m_i)^{1/2}\tau(E_i^m)^{1/2}\big),
\end{equation}
and it is seen through a simple calculation that
\begin{align}
\mathcal{C}_m(\ketbra{\alpha}{\alpha}^{\otimes m})&=\bigoplus_{i=1}^{n'}p'_i\ketbra{\alpha'_i}{\alpha'_i}=A',\\
\mathcal{C}_m(\ketbra{\beta}{\beta}^{\otimes m})&=\bigoplus_{i=1}^{n'}q'_i\ketbra{\beta'_i}{\beta'_i}=B'.
\end{align}

Let us next assume that the state pair $(A,B)$ is as in \eqref{eq:Vpair2} with $0<|\braket{\alpha_i}{\beta_i}|<1$ for $i=1,\ldots,n$. We are free to assume that $|\braket{\alpha_1}{\beta_1}|^2$ is the greatest of the fidelities $|\braket{\alpha_i}{\beta_i}|^2$. According to Proposition \ref{propo:Uhlmann}, we have channels $\mathcal{D}_i$ such that $\mathcal{D}_i(\ketbra{\alpha_i}{\alpha_i})=\ketbra{\alpha_1}{\alpha_1}$ and $\mathcal{D}_i(\ketbra{\beta_i}{\beta_i})=\ketbra{\beta_1}{\beta_1}$ for $i=1,\ldots,n$; for $i=1$ we may naturally choose the identity map $\mathcal{D}_1={\rm id}$. Let $P_i$ be the projection of the Hilbert space onto the $i$'th component in \eqref{eq:Vpair2} and define the channel $\mathcal{D}$ by $\mathcal{D}(\tau)=\sum_{i=1}^n\mathcal{D}_i(P_i\tau P_i)$. It follows that $\mathcal{D}(A)=\ketbra{\alpha_1}{\alpha_1}$ and $\mathcal{D}(B)=\ketbra{\beta_1}{\beta_1}$, so that $(A,B)$ majorizes $(\ketbra{\alpha_1}{\alpha_1},\ketbra{\beta_1}{\beta_1})$. Since, by assumption, $0<|\braket{\alpha_1}{\beta_1}|<1$, we know from what we have shown thus far that $(\ketbra{\alpha_1}{\alpha_1},\ketbra{\beta_1}{\beta_1})^{\boxtimes m}\succeq (A',B')$ for any normalized element $(A',B')\in S_{\rm e.o.}$ for sufficiently large $m\in\mathbb{N}$. 









Thus, also for any normalized $(A',B')\in S_{\rm e.o.}$,
\begin{equation}\label{eq:apu2}
(A,B)^{\boxtimes m}\succeq(\ketbra{\alpha_1}{\alpha_1},\ketbra{\beta_1}{\beta_1})^{\boxtimes m}\succeq (A',B')
\end{equation}
for $m\in\mathbb{N}$ large enough. 

We are finally able to show that the above $(A,B)$ is a power universal. For this, consider pairs $(A_1,B_1),(A_2,B_2)\in S_{\rm e.o.}$ such that $(A_1,B_1)\preceq(A_2,B_2)$. This clearly means especially that $\mathrm{Tr}[A_1]=\mathrm{Tr}[A_2]$ and $\mathrm{Tr}[B_1]=\mathrm{Tr}[B_2]$. Define $A':=\mathrm{Tr}[A_2]^{-1}A_2$ and $B':=\mathrm{Tr}[B_2]^{-1}B_2$. Since we have already proven that, for $m\in\mathbb{N}$ large enough, we have \eqref{eq:apu2}, we now have
\begin{align}
(A_1,B_1)\boxtimes(A,B)^{\boxtimes m}&=(A_1\otimes A^{\otimes m},B_1\otimes B^{\otimes m})\\
&\succeq\big(\mathrm{Tr}[A_1]A^{\otimes m},\mathrm{Tr}[B_1]B^{\otimes m}\big)\\
&=\big(\mathrm{Tr}[A_2]A^{\otimes m},\mathrm{Tr}[B_2]B^{\otimes m}\big)\\
&\succeq\big(\mathrm{Tr}[A_2]A',\mathrm{Tr}[B_2]B'\big)=(A_2,B_2)
\end{align}
for $m\in\mathbb{N}$ large enough. This shows that $(A,B)$ is a power universal.

Let $(A,B)$ be a pair as stated in the claim. By using the equivalence relation defined on $S_{\rm m.r.}$, we may assume that there are $\ell$ with $1\leq\ell<n$, unit vectors $\ket{\alpha_i}$ and $\ket{\beta_i}$ such that $0<|\braket{\alpha_i}{\beta_i}|<1$, $i=1,\ldots,\ell$, positive probabilities $p_1,\ldots,p_\ell$ and $q_1,\ldots,q_\ell$ with $P:=p_1+\cdots+p_\ell<1$ and $Q:=q_1+\cdots+q_\ell<1$, and non-zero vectors $p,q\in\mathbb{R}_+^{n-\ell}$, $p=(p_{\ell+1},\ldots,p_{n})$, $q=(q_{\ell+1},\ldots,q_n)$, with $\|p\|_1+P=1=\|q\|_1+Q$ such that
\begin{align}
A&=\left(\bigoplus_{i=1}^\ell p_i\ketbra{\alpha_i}{\alpha_i}\right)\oplus p,\\
B&=\left(\bigoplus_{i=1}^\ell q_i\ketbra{\beta_i}{\beta_i}\right)\oplus q,
\end{align}
and additionally 
\begin{equation}
{\rm supp}\,p\cap{\rm supp}\,q=\emptyset,
\end{equation}
i.e.,\ $p$ and $q$ are disjoint.

It follows that, for each $m\in\mathbb{N}$,                                                                                            
\begin{align}
A^{\otimes m}&=\left(\bigoplus_{i_1,\ldots,i_m=1}^\ell p_{i_1}\cdots p_{i_m}\ketbra{\alpha_{i_1}}{\alpha_{i_1}}\otimes\cdots\otimes\ketbra{\alpha_{i_m}}{\alpha_{i_m}}\right)\oplus A^{(m)},\\
B^{\otimes m}&=\left(\bigoplus_{i_1,\ldots,i_m=1}^\ell q_{i_1}\cdots q_{i_m}\ketbra{\beta_{i_1}}{\beta_{i_1}}\otimes\cdots\otimes\ketbra{\beta_{i_m}}{\beta_{i_m}}\right)\oplus B^{(m)}
\end{align}
for some operators $A^{(m)}$ and $B^{(m)}$ where $A^{(m)}$ is a tensor product of $p$ (seen as a diagonal operator) with some other operator and $B^{(m)}$ is a tensor product of $q$ with some other operator. Since $p$ and $q$ have disjoint supports, $A^{(m)}$ and $B^{(m)}$ commute, so we may identify them with some sequences $p^{(m)}$ and $q^{(m)}$ (classical blocks) of non-negative numbers with disjoint supports. We may assume that the block $i=1$ has the highest fidelity among $|\braket{\alpha_i}{\beta_i}|^2$ for $i=1,\ldots,\ell$.
Then, by Proposition \ref{propo:Uhlmann}, there are channels $\mathcal{C}_{i_1,\ldots,i_m}$ such that
\begin{align}
\mathcal{C}_{i_1,\ldots,i_m}\big(\ketbra{\alpha_{i_1}}{\alpha_{i_1}}\otimes\cdots\otimes\ketbra{\alpha_{i_m}}{\alpha_{i_m}}\big)&=\ketbra{\alpha_1}{\alpha_1}^{\otimes m},\\
\mathcal{C}_{i_1,\ldots,i_m}\big(\ketbra{\beta_{i_1}}{\beta_{i_1}}\otimes\cdots\otimes\ketbra{\beta_{i_m}}{\beta_{i_m}}\big)&=\ketbra{\beta_1}{\beta_1}^{\otimes m}.
\end{align}
Let $P_{i_1,\ldots,i_m}$ be the projections onto the $\ell^m$ first blocks and $Q_j$, $j=\ell^m+1,\ldots,n^m$ be the projections onto the last (classical) blocks. Let us also denote by $\big({\rm supp}\,p^{(m)}\big)^c$ the complement of the support of $p^{(m)}$ among the $n^m-\ell^m$ final classical blocks. Naturally, this complement contains the support of $q^{(m)}$. Let us set up the quantum channel $\mathcal{C}_m$
\begin{align}
\mathcal{C}_m(R)=&\sum_{i_1,\ldots,i_m=1}^\ell \mathcal{C}_{i_1,\ldots,i_m}(P_{i_1,\ldots,i_m}RP_{i_1,\ldots,i_m})\\
&\oplus\,\left(\sum_{j\in{\rm supp}\,p^{(m)}}\mathrm{Tr}[Q_jRQ_j]\right)\,\oplus\,\left(\sum_{k\in\big({\rm supp}\,p^{(m)}\big)^c}\mathrm{Tr}[Q_k RQ_k]\right).
\end{align}
We now have                                                                                                                                                                                                                                                                                   
\begin{align}
\mathcal{C}_m(A^{\otimes m})&=P^m\ketbra{\alpha_1}{\alpha_1}^{\otimes m}\oplus(1-P^m)\oplus 0=:A_m,\\
\mathcal{C}_m(B^{\otimes m})&=Q^m\ketbra{\beta_1}{\beta_1}^{\otimes m}\oplus 0\oplus(1-Q^m)=:B_m,
\end{align}
so that $(A,B)^{\boxtimes m}\succeq (A_m,B_m)$.

Let $(A',B')$ be a pair of operators within $S_{\rm m.r.}$ which we intend to majorize with a high enough power of the input $(A,B)$. Let us assume that this pair has the form of \eqref{eq:a'b'}, except that now not all $p'_i$ and $q'_i$ need to be non-zero. However, there needs to be a block $i_0$ such that $p'_{i_0},q'_{i_0}>0$ and $\braket{\alpha'_{i_0}}{\beta'_{i_0}}\neq0$. By reordering, we may assume that $i_0=1$. Let us now upper bound this target pair $(A',B')$. We may write $A'=A_1\oplus A_2$ and $B'=B_1\oplus B_2$ where $(A_1,B_1)\in S_{\rm e.o.}$ and $A_2$ and $B_2$ have blocks that are completely disjoint. Let $s:=\mathrm{Tr}[A_1]$ and $t:=\mathrm{Tr}[B_1]$. We now claim that $(\tilde{A},\tilde{B})\succeq (A',B')$ where
\begin{align}
\tilde{A}&=s\ketbra{\alpha}{\alpha}\oplus(1-s)\oplus 0,\\
\tilde{B}&=t\ketbra{\beta}{\beta}\oplus 0\oplus(1-t)
\end{align}
where $\ket{\alpha}$ and $\ket{\beta}$ are some non-orthogonal unit vectors. Indeed, from the proof Proposition \ref{prop:puS}, we know that (when $|\braket{\alpha}{\beta}|$ is sufficiently small) \sloppy{${(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})\succeq (\mathrm{Tr}[A_1]^{-1}A_1,\mathrm{Tr}[B_1]^{-1}B_1)}$}, and from the remaining orthogonal part \sloppy{${((1-s)\oplus0,0\oplus(1-t))}$} of $(\tilde{A},\tilde{B})$ we can easily find a channel that creates $(A_2,B_2)$. We next show that there is $m\in\mathbb{N}$ such that $(A,B)^{\boxtimes m}\succeq (A',B')$ by showing the intermediary $(A_m,B_m)\succeq(\tilde{A},\tilde{B})$ for sufficiently large $m\in\mathbb{N}$.

Let us denote the 2-dimensional space spanned by $\ket{\alpha_1}^{\otimes m}$ and $\ket{\beta_1}^{\otimes m}$ by $\mathcal{M}_m$ and the projection of $\mathcal{M}_m\oplus\mathbb{C}\oplus\mathbb{C}$ onto $\mathcal{M}_m$ by $R_m$. The projection orthogonal to this we denote by $R_m^\perp$. Using again Proposition \ref{propo:Uhlmann}, we find that, for $m\in\mathbb{N}$ large enough, there is a channel $\mathcal{D}_m$ such that $\mathcal{D}_m(\ketbra{\alpha_1}{\alpha_1}^{\otimes m})=\ketbra{\alpha}{\alpha}$ and $\mathcal{D}_m(\ketbra{\beta_1}{\beta_1}^{\otimes m})=\ketbra{\beta}{\beta}$. Let us assume that $m\in\mathbb{N}$ is sufficiently large so that $P^m<s$ and $Q^m<t$.                                                                            
We may now define a channel $\mathcal{E}_m$ on the last two blocks of $(A_m,B_m)$ (which together can be regarded as a pair of qubits) such that
\begin{align}
\mathcal{E}_m(1\oplus 0)&=\frac{s-P^m}{1-P^m}\ketbra{\alpha}{\alpha}\oplus\frac{1-s}{1-P^m}\oplus0,\\
\mathcal{E}_m(0\oplus 1)&=\frac{t-Q^m}{1-Q^m}\ketbra{\beta}{\beta}\oplus0\oplus\frac{1-t}{1-Q^m}.
\end{align}
Define the channel $\mathcal{C}_m$ through
\begin{equation}
\mathcal{C}_m(\tau)=\mathcal{D}_m(R_m\tau R_m)+\mathcal{E}_m(R_m^\perp\tau R_m^\perp).
\end{equation}
It now follows from a straightforward calculation that $\mathcal{C}_m(A_m)=\tilde{A}$ and $\mathcal{C}_m(B_m)=\tilde{B}$. Thus, we may deduce that $(A,B)^{\boxtimes m}\succeq(A',B')$ for $m\in\mathbb{N}$ large enough. The fact that $(A,B)$ is a power universal now follows through the same simple logic as in the end of the proof of Proposition \ref{prop:puS}.

\label{prop:z}
    Let $\Phi:S_{*}\rightarrow\mathbb{K}$ be a monotone homomorphism, where $S_{*}\in\{S_{\rm m.r.},S_{\rm e.o.}\}$ and $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$. There exists $z\in\mathbb{R}$ such that 
    \begin{equation}
        \Phi(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})=|\braket{\alpha}{\beta}|^{2z}
    \end{equation}
    for all normalized $\ket{\alpha},\ket{\beta}\in\mathcal{H}$ such that $\braket{\alpha}{\beta}\neq0$, and $\mathcal{H}$ is a Hilbert space.

Fix orthonormal vectors $\ket{0}$ and $\ket{1}$ that span the subspace $\mathcal{M}$ where $\ket{\alpha}$ and $\ket{\beta}$ reside. For any normalized $|\alpha^\perp\rangle\in\mathcal{M}$ perpendicular to $\ket{\alpha}$ we have 
    \begin{equation}
        |\braket{\alpha}{\beta}|^2+|\langle\alpha^\perp|\beta\rangle|^2=1. 
    \end{equation}
    Hence 
    \begin{equation}
        |\braket{\alpha}{\beta}|=\cos\theta,\quad|\langle\alpha^\perp|\beta\rangle|=\sin\theta,
    \end{equation}
    for some $\theta\in[0,\pi/2]$. By multiplying with an appropriate phase, we may choose $|\alpha^\perp\rangle$ such that 
    \begin{equation}
        \braket{\alpha}{\beta}\langle\beta|\alpha^\perp\rangle=\cos\theta\sin\theta. 
    \end{equation}
    Via the unitary operation defined by $\ket{\alpha}\mapsto\ket{0},|\alpha^\perp\rangle\mapsto\ket{1}$, the pair $(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})$ is equivalent (according to the equivalence relation $\approx$ defined in Section \ref{sec:definingthesemirings}) to the pair 
    \begin{equation}\label{eq:pairstandardform}
        (\ketbra{0}{0},\cos^2\theta\ketbra{0}{0}+\cos\theta\sin\theta\ketbra{0}{1}+\cos\theta\sin\theta\ketbra{1}{0}+\sin^2\theta\ketbra{1}{1}). 
    \end{equation}
    From this, we see that $\Phi(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})$ only depends on the fidelity $\cos^2\theta=|\braket{\alpha}{\beta}|^2$. Therefore, we can define $\varphi:(0,1]\rightarrow\mathbb{R}$, 
    \begin{equation}
        \varphi(x):=\Phi(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta}), 
    \end{equation}
    where $\ket{\alpha},\ket{\beta}$ are any normalized vectors such that $|\braket{\alpha}{\beta}|^2=x$. Note that 
    \begin{align}
        &(\ketbra{\alpha_1}{\alpha_1},\ketbra{\beta_1}{\beta_1})\boxtimes(\ketbra{\alpha_2}{\alpha_2},\ketbra{\beta_2}{\beta_2})\\            &\quad\quad=((\ket{\alpha_1}\otimes\ket{\alpha_2})(\bra{\alpha_1}\otimes\bra{\alpha_2}),(\ket{\beta_1}\otimes\ket{\beta_2})(\bra{\beta_1}\otimes\bra{\beta_2})) 
    \end{align}
    and 
    \begin{equation}
        |(\bra{\alpha_1}\otimes\bra{\alpha_2})(\ket{\beta_1}\otimes\ket{\beta_2})|^2=|\braket{\alpha_1}{\beta_1}|^2|\braket{\alpha_2}{\beta_2}|^2. 
    \end{equation}
    Thus, by multiplicativity of $\Phi$, the function $\varphi$ is multiplicative as well, i.e. 
    \begin{equation}
        \varphi(xy)=\varphi(x)\varphi(y)\text{ for all }x,y\in(0,1]. 
    \end{equation}    

    Using Proposition \ref{propo:Uhlmann}, for any $\ket{\alpha},\ket{\beta}$ such that 
    \begin{equation}
        |\braket{\alpha}{\beta}|^2\geq\frac{1}{2}=|\braket{0}{\psi(\pi/4)}|^2, 
    \end{equation}
    where $|\psi(\pi/4)\rangle$ is defined as in \eqref{eq:anglevectors}, we have 
    \begin{equation}
        (1,1)\preceq(\ketbra{\alpha}{\alpha},\ketbra{\beta}{\beta})\preceq(\ketbra{0}{0},\ketbra{\psi(\pi/4)}{\psi(\pi/4)}). 
    \end{equation}
    Hence for all $x\in[1/2,1]$, we have $\varphi(x)\leq1$ if $\mathbb{K}=\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+^{\rm op}$, and $\varphi(x)\leq\varphi(1/2)$ if $\mathbb{K}=\mathbb{R}_+,\mathbb{T}\mathbb{R}_+$. Therefore, $\varphi$ is bounded from above on a set of positive measure, which establishes that $\varphi$ is a regular solution of the multiplicative version of Cauchy's Functional Equation \cite[Chapter 3, Proposition 6]{Aczel1989}: there exists $z\in\mathbb{R}$ such that $\varphi(x)=x^z$ or $\varphi$ vanishes everywhere. The latter case is impossible since $\varphi(1)=\Phi(1,1)=1$ by the properties of a homomorphism.

\label{rmk:classical}
Let us summarize some results that were established in Chapter \ref{cha:matrix} on the possible monotone homomorphisms and derivations on commuting pairs $(A,B)$ in $S_{\rm m.r.}$, i.e.,\ a pair $(A,B)$ such as in \eqref{eq:Vpair2} where the component spaces $\mathcal{H}_i\simeq\mathbb{C}$. We will use these results extensively in the analysis of our current semiring $S_{\rm m.r.}$. 

The commuting pairs in $S_{\rm m.r.}$ correspond precisely to the elements in the semiring denoted in Chapter \ref{cha:matrix}, Section \ref{Msec:findings} as $S^2$, the minimal restrictions matrix majorization semiring of length $2$. Hence any non-degenerate monotone homomorphism or monotone derivation on $S_{\rm m.r.}$, when restricted to these commuting pairs, must correspond to a (possibly degenerate) monotone homomorphism or monotone derivation on $S^2$. 

We now list these homomorphisms and derivations. Let $\Phi:S_{\rm m.r.}\rightarrow\mathbb{K}$, $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$, be a monotone homomorphism. When $\mathbb{K}=\mathbb{R}_+^{\rm op}$, $\Phi$ restricted to a commuting pair $(A,B)$ takes the form 
\begin{equation}\label{eq:Phitemperate}
\Phi(A,B)=\sum_{i=1}^n p_i^\alpha q_i^{1-\alpha}
\end{equation}
for some $\alpha\in(0,1)$, or 
\begin{equation}\label{eq:Phicharacter}
\Phi(A,B)=\sum_{i:p_i>0} q_i,\quad\text{or}\quad\Phi(A,B)=\sum_{i:q_i>0} p_i, 
\end{equation}
or $\Phi$ restricts to one of the two degenerate homomorphisms $\Phi(A,B)=\mathrm{Tr}[A]$ or $\mathrm{Tr}[B]$.\footnote{Note that the two cases in \eqref{eq:Phicharacter} correspond to the character $C=\{1,2\}$, i.e. only those $i$ for which $p_i>0$ and $q_i>0$ are summed over.} When $\mathbb{K}=\mathbb{R}_+$, $\Phi$ always restricts to one of these latter two degenerate cases. When $\mathbb{K}=\mathbb{T}\mathbb{R}_+$ or $\mathbb{T}\mathbb{R}_+^{\rm op}$, the only form $\Phi$ can take on a commuting pair is the highly degenerate $\Phi(A,B)=1$ when $(A,B)\neq 0$ and $\Phi(0,0)=0$. (However, it will turn out that the new parameter $z$ in Proposition \ref{prop:z} makes the extension of this homomorphism to $S_{\rm m.r.}$ \emph{non}-degenerate in the case $\mathbb{K}=\mathbb{T}\mathbb{R}_+^{\rm op}$.) Finally, the derivations corresponding to the two degenerate cases $\Phi(A,B)=\mathrm{Tr}[A]$ or $\mathrm{Tr}[B]$, up to interchangeability (see footnote \ref{ftn:interchangeability} on page \pageref{ftn:interchangeability}), must vanish on commuting pairs.

\label{prop:monhom}
The non-degenerate monotone homomorphisms $\Phi:S_{\rm m.r.}\to\mathbb{K}$, where $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$, with trivial kernel are exactly the following: 
\begin{itemize}
\item $\mathbb{K}=\mathbb{R}_+^{\rm op}$: $\Phi$ is of the form 
\begin{equation}\label{eq:temperate}
    \Phi_{\alpha,z}(A,B):=\sum_{i=1}^n(p_i)^\alpha(q_i)^{1-\alpha}|\braket{\alpha_i}{\beta_i}|^{2z}, 
\end{equation}    
for any $\alpha\in[0,1]$ and $z\geq\max\{\alpha,1-\alpha\}$. 
\item $\mathbb{K}=\mathbb{T}\mathbb{R}_+^{\rm op}$: $\Phi$ is of the form 
\begin{equation}\label{eq:tropicalz}
    \Phi_z^\mathbb{T}(A,B):=\max_{i=1,\ldots,n}|\braket{\alpha_i}{\beta_i}|^{2z}, 
\end{equation}    
for any $z>0$. 
\item $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{T}\mathbb{R}_+\}$: There are no non-degenerate monotone homomorphisms with trivial kernel. 
\end{itemize}
Moreover, there are no non-zero monotone derivations.

Note that when $\alpha=0$ or $1$, it may occur that the expression \eqref{eq:temperate} contains a factor $0^0$ when $p_i=0$ or $q_i=0$ for some $i$. However, since in this case also the corresponding $\ket{\alpha_i}$ or $\ket{\beta_i}$ equals the zero vector, there is no ambiguity: the entire expression $(p_i)^\alpha(q_i)^{1-\alpha}|\braket{\alpha_i}{\beta_i}|^{2z}$ should be considered to be equal to $0$. 

    One checks that for pairs $(A,B)\in S_{\rm m.r.}$, we have 
    \begin{equation}
        \Phi_{\alpha,z}(A,B)=\mathrm{Tr}\left[\left(B^{\frac{1-\alpha}{2z}}A^{\frac{\alpha}{z}}B^{\frac{1-\alpha}{2z}}\right)^z\right], 
    \end{equation}
    where the right-hand side is the expression appearing inside the logarithm in the definition of the $\alpha$-$z$ relative entropy in \eqref{eq:alphazdivergence}. 

    For two pairs $(A,B),(A',B')\in S_{\rm m.r.}$, note that $\Phi_z^\mathbb{T}(A,B)>\Phi_z^\mathbb{T}(A',B')$ for all $z>0$ if and only if this inequality holds for one such $z$. Since the conditions for majorization given by Theorem \ref{thm:Fritz2022} are stated in terms of such inequalities, it is sufficient for our purposes to consider only $\Phi_z^\mathbb{T}$ for the choice $z=1$. Hence, we define 
    \begin{equation}\label{eq:tropical}
        \Phi^\mathbb{T}(A,B):=\Phi_1^\mathbb{T}(A,B)=\max_{i=1,\ldots,n}|\braket{\alpha_i}{\beta_i}|^{2}=\|({\rm supp}\,A)({\rm supp}\,B)\|_\infty^2. 
    \end{equation}
    Here, the right-hand side gives an alternative expression for the homomorphism, where $\|\cdot\|_\infty$ is the operator norm and, e.g.,\ ${\rm supp}\,A$ is the support projection of the positive semidefinite $A$.

Before proceeding to the characterization of all relevant monotone homomorphisms and derivations, we will first show how to interpret the decompositions \eqref{eq:decompositiontemperate} and \eqref{eq:decompositiontropical} when there are $i$ such that $\ket{\alpha_i},\ket{\beta_i}$ are orthogonal or exactly one of them is the zero-vector. 

Fix a monotone homomorphism $\Phi:S_{\rm m.r.}\rightarrow\mathbb{K}$, where $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\allowbreak\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$, and let $(A,B)\in S_{\rm m.r.}$. Note that we may assume that there exists a representation as in \eqref{eq:Vpair2} such that there is no $j$ for which $\braket{\alpha_j}{\beta_j}=0$ and $\ket{\alpha_j},\ket{\beta_j}\neq0$. Indeed, if there is such $j$, then the pair $(p_j\ketbra{\alpha_j}{\alpha_j},q_j\ketbra{\beta_j}{\beta_j})$ can be replaced by $(p_j\oplus0,0\oplus q_j)$ under the equivalence relation $\approx$. 

Due to \eqref{eq:cscondition}, there exists $k\in[n]$ such that $|\braket{\alpha_k}{\beta_k}|\neq0$. Assume there is a $j_1$ such that $\ket{\alpha_{j_1}}\neq0$ and $\ket{\beta_{j_1}}=0$, or a $j_2$ such that $\ket{\alpha_{j_2}}=0$ and $\ket{\beta_{j_2}}\neq0$. In the following, we will show that $\Phi(A,B)$ may be expressed as \eqref{eq:decompositiontemperate} or \eqref{eq:decompositiontropical}, where we set 
\begin{equation}\label{eq:define0trA}
    \Phi(p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},0)=p_{j_1}\Phi(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k})\text{ and }\Phi(0,q_{j_2}\ketbra{\beta_{j_2}}{\beta_{j_2}})=0
\end{equation}
if $\mathbb{K}=\mathbb{R}_+$ or $\mathbb{R}_+^{\rm op}$ and $\Phi$ restricts to $\mathrm{Tr}[A']$ on commuting pairs $(A',B')$, 
\begin{equation}\label{eq:define0trB}
    \Phi(p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},0)=0\text{ and }\Phi(0,q_{j_2}\ketbra{\beta_{j_2}}{\beta_{j_2}})=q_{j_2}\Phi(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k})
\end{equation}
if $\mathbb{K}=\mathbb{R}_+$ or $\mathbb{R}_+^{\rm op}$ and $\Phi$ restricts to $\mathrm{Tr}[B']$ on commuting pairs $(A',B')$, and 
\begin{equation}\label{eq:define0otherwise}
    \Phi(p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},0)=0\text{ and }\Phi(0,q_{j_2}\ketbra{\beta_{j_2}}{\beta_{j_2}})=0
\end{equation}
otherwise. Note that, although \eqref{eq:define0trA}, \eqref{eq:define0trB} seem to depend on the choice of $k$ due to the appearance of the term $\Phi(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k})$, we will show later that $z=0$ when $\Phi$ restricts to $\mathrm{Tr}[A']$ or $\mathrm{Tr}[B']$ on commuting pairs $(A',B')$, hence $\Phi(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k})=1$, independent of $k$. 

Assume there is a $j_1$ such that $\ket{\alpha_{j_1}}\neq0$ and $\ket{\beta_{j_1}}=0$; the analysis of the case of $j_2$ such that $\ket{\alpha_{j_2}}=0$ and $\ket{\beta_{j_2}}\neq0$ is analogous. Denote by $\substack{\succeq\\\preceq}$ majorization in both directions. There exist a quantum channel that splits block $k$, and another channel that merges two blocks, which implies 
\begin{align}
    \big(p_k\ketbra{\alpha_k}{\alpha_k},q_k\ketbra{\beta_k}{\beta_k}\big)\substack{\succeq\\\preceq}&\big(p_k/2\ketbra{\alpha_k}{\alpha_k},q_k/2\ketbra{\beta_k}{\beta_k}\big)\\
    &\boxplus\big(p_k/2\ketbra{\alpha_k}{\alpha_k},q_k/2\ketbra{\beta_k}{\beta_k}\big). 
\end{align}
Denote by $(\tilde A,\tilde B)\in S_{\rm m.r.}$ the pair $(A,B)$ with blocks $j_1$ and $k$ removed. Using the majorization relation above, we have 
\begin{align}
    \big(A,B\big)\substack{\succeq\\\preceq}&\big(p_k/2\ketbra{\alpha_k}{\alpha_k}\oplus \tilde A,q_k/2\ketbra{\beta_k}{\beta_k}\oplus\tilde B\big)\label{eq:split1}\\
    &\boxplus\big(p_k/2\ketbra{\alpha_k}{\alpha_k}\oplus p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},q_k/2\ketbra{\beta_k}{\beta_k}\oplus0\big).\label{eq:split2}
\end{align}
Since $\ket{\beta_{j_1}}=0$, we may assume that $\ket{\alpha_{j_1}}=\ket{\alpha_k}$ under the equivalence relation $\approx$. Then, notice that 
\begin{align}
    &\big(p_k/2\ketbra{\alpha_k}{\alpha_k}\oplus p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},q_k/2\ketbra{\beta_k}{\beta_k}\oplus0\big)\label{eq:specialblock1}\\
    &\quad\quad=\big(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}\big)\boxtimes\big(p_k/2\oplus p_{j_1},q_k/2\oplus0\big).\label{eq:specialblock2}
\end{align}

Now assume $\mathbb{K}=\mathbb{R}_+$ or $\mathbb{R}_+^{\rm op}$. Assume further that the restriction of $\Phi$ on commuting pairs $(A',B')$ does not equal $\mathrm{Tr}[A']$. Considering the remaining possible restrictions (see Remark \ref{rmk:classical}), it follows from \eqref{eq:specialblock1}, \eqref{eq:specialblock2} that 
\begin{align}
    &\Phi\big(p_k/2\ketbra{\alpha_k}{\alpha_k}\oplus p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},q_k/2\ketbra{\beta_k}{\beta_k}\oplus0\big)\\
    &\quad\quad=\Phi\big(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}\big)\Phi\big(p_k/2\oplus p_{j_1},q_k/2\oplus0\big)\\
    &\quad\quad=\Phi\big(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}\big)\Phi\big(p_k/2,q_k/2\big)\\
    &\quad\quad=\Phi\big(p_k/2\ketbra{\alpha_k}{\alpha_k},q_k/2\ketbra{\beta_k}{\beta_k}\big). 
\end{align}
Using this equality and \eqref{eq:split1}, \eqref{eq:split2}, via splitting and merging of blocks, we find 
\begin{align}
    \Phi(A,B)&=\Phi\big(p_k/2\ketbra{\alpha_k}{\alpha_k}\oplus\tilde A,q_k/2\ketbra{\beta_k}{\beta_k}\oplus\tilde B\big)\\
    &\quad+\Phi\big(p_k/2\ketbra{\alpha_k}{\alpha_k},q_k/2\ketbra{\beta_k}{\beta_k}\big)\\        
    &=\Phi\big(p_k\ketbra{\alpha_k}{\alpha_k}\oplus\tilde A,q_k\ketbra{\beta_k}{\beta_k}\oplus\tilde B\big).
\end{align}
Note that $(p_k\ketbra{\alpha_k}{\alpha_k}\oplus\tilde A,q_k\ketbra{\beta_k}{\beta_k}\oplus\tilde B)$ equals $(A,B)$ with the pair $(p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},0)$ removed. Hence, we may set $\Phi(p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},0)=0$. Assume now that $\Phi$ restricts to $\mathrm{Tr}[A']$ on commuting pairs $(A',B')$. Then it follows from \eqref{eq:specialblock1}, \eqref{eq:specialblock2} that 
\begin{align}
    &\Phi\big(p_k/2\ketbra{\alpha_k}{\alpha_k}\oplus p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},q_k/2\ketbra{\beta_k}{\beta_k}\oplus0\big)\\
    &\quad\quad=\Phi\big(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}\big)(p_k/2+p_{j_1})\\
    &\quad\quad=\Phi\big(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}\big)(\Phi\big(p_k/2,q_k/2\big)+p_{j_1})\\        &\quad\quad=\Phi\big(p_k/2\ketbra{\alpha_k}{\alpha_k},q_k/2\ketbra{\beta_k}{\beta_k}\big)+p_{j_1}\Phi\big(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}\big). 
\end{align}
Now it follows from \eqref{eq:split1}, \eqref{eq:split2} that 
\begin{equation}
    \Phi(A,B)=\Phi\big(p_k\ketbra{\alpha_k}{\alpha_k}\oplus\tilde A,q_k\ketbra{\beta_k}{\beta_k}\oplus\tilde B\big)+p_{j_1}\Phi(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}), 
\end{equation}
allowing us to set $\Phi(p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},0)=p_{j_1}\Phi(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k})$. Analogously one can show that, when there is $j_2$ such that $\ket{\alpha_{j_2}}=0$ and $\ket{\beta_{j_2}}\neq0$, and $\Phi$ does not restrict to $\mathrm{Tr}[B']$ on commuting pairs $(A',B')$, we may set $\Phi(0,q_{j_2}\ketbra{\beta_{j_2}}{\beta_{j_2}})=0$, and otherwise $\Phi(0,q_{j_2}\ketbra{\beta_{j_2}}{\beta_{j_2}})=q_{j_2}\Phi(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k})$. We conclude that \eqref{eq:decompositiontemperate} with the conventions \eqref{eq:define0trA}, \eqref{eq:define0trB}, \eqref{eq:define0otherwise} are correct for $\mathbb{K}=\mathbb{R}_+,\mathbb{R}_+^{\rm op}$. 

Next, assume $\mathbb{K}=\mathbb{T}\mathbb{R}_+$ or $\mathbb{T}\mathbb{R}_+^{\rm op}$. Recall that $\Phi$ must restrict to $\Phi(A,B)=1$ for commuting pairs $(A,B)\neq 0$ and $\Phi(0,0)=0$. Assume there is a $j_1$ such that $\ket{\alpha_{j_1}}\neq0$ and $\ket{\beta_{j_1}}=0$. Using \eqref{eq:specialblock1}, \eqref{eq:specialblock2}, we now have 
\begin{equation}
    \Phi\big(p_k/2\ketbra{\alpha_k}{\alpha_k}\oplus p_{j_1}\ketbra{\alpha_{j_1}}{\alpha_{j_1}},q_k/2\ketbra{\beta_k}{\beta_k}\oplus0\big)=\Phi\big(\ketbra{\alpha_k}{\alpha_k},\ketbra{\beta_k}{\beta_k}\big). 
\end{equation}    
Then, using similar arguments as above using \eqref{eq:split1}, \eqref{eq:split2}, and remembering that addition in $\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}$ is defined by taking the maximum of two numbers, we may conclude that 
\begin{equation}
    \Phi(A,B)=\Phi\big(p_k\ketbra{\alpha_k}{\alpha_k}\oplus\tilde A,q_k\ketbra{\beta_k}{\beta_k}\oplus\tilde B\big). 
\end{equation}
The case of $j_2$ such that $\ket{\alpha_{j_2}}=0$ and $\ket{\beta_{j_2}}\neq0$ can be handled analogously. We conclude that \eqref{eq:decompositiontropical} with the convention \eqref{eq:define0otherwise} is correct for $\mathbb{K}=\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}$. 

In the next part of the proof, we will first exclude certain ranges that the $\alpha$ and $z$ parameters may be in by providing counterexamples to the monotonicity property of homomorphisms. Similarly, we will use monotonicity to show that there are no non-zero monotone derivations. Finally, we prove that the homomorphisms that remain are in fact monotone. 

Fix a monotone homomorphism $\Phi:S_{\rm m.r.}\rightarrow\mathbb{K}$, where $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\allowbreak\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$. From the results in Propositions \ref{propo:Uhlmann} and \ref{prop:z} on majorization of pairs of pure states, and using the monotonicity of $\Phi$, it follows that the parameter $z$ must be non-positive when ${\mathbb{K}}=\mathbb{R}_+,\mathbb{T}\mathbb{R}_+$ and non-negative when ${\mathbb{K}}=\mathbb{R}_+^{\rm op},\mathbb{T}\mathbb{R}_+^{\rm op}$. 

Let us assume $\mathbb{K}=\mathbb{R}_+^{\rm op}$ first. In the following, we will consider case-by-case the different ways that $\Phi$ restricts to commuting pairs. 

The quantum channel arising from measuring a qubit in a fixed basis $\ket{0},\ket{1}$ yields the following majorization relation: 
\begin{equation}
\label{eq:alphazrelationship1}
    \left(\,\ketbra{\psi(\pi/4)}{\psi(\pi/4)},\ketbra{0}{0}\,\right)\succeq(1/2,1)\boxplus(1/2,0), 
\end{equation}
where $|\psi(\theta)\rangle$ is defined as in \eqref{eq:anglevectors}. Consider the case that $\Phi$ is of the form \eqref{eq:Phitemperate} with $\alpha\in(0,1)$ when restricted to commuting pairs. Evaluating $\Phi$ on both sides of the inequality \eqref{eq:alphazrelationship1}, it follows by monotonicity that 
\begin{equation}
\label{eq:alphazrelationship2}
    \frac{1}{2^z}\leq\frac{1}{2^\alpha}. 
\end{equation}
By switching around the states in the two pairs in \eqref{eq:alphazrelationship1}, we have similarly
\begin{equation}
\label{eq:alphazrelationship3}
    \frac{1}{2^z}\leq\frac{1}{2^{1-\alpha}}. 
\end{equation}    
Hence \sloppy{${z\geq\max\{\alpha,1-\alpha\}}$}. It follows by the decomposition \eqref{eq:decompositiontemperate} with the convention \eqref{eq:define0otherwise} that $\Phi$ must be as in \eqref{eq:temperate} with $\sloppy{\alpha\in(0,1)}$ and ${z\geq\max\{\alpha,1-\alpha\}}$. 

Next, consider the case that $\Phi$ is one of \eqref{eq:Phicharacter} when restricted to a commuting pair. When it restricts to the second form in \eqref{eq:Phicharacter}, monotonicity and \eqref{eq:alphazrelationship1} imply that 
\begin{equation}
    \frac{1}{2^z}\leq\frac{1}{2}. 
\end{equation}
Hence, $z\geq1$. Similarly, when $\Phi$ restricts to the first form in \eqref{eq:Phicharacter}, by switching around the states in the two pairs in \eqref{eq:alphazrelationship1}, we find $z\geq1$. It follows for these latter two cases that $\Phi$ is equal to \eqref{eq:temperate} with $\alpha=0$ or $1$, and $z\geq1=\max\{\alpha,1-\alpha\}$. 

A measure-and-prepare channel establishes the following majorization relation: 
\begin{align}\label{eq:preparation}
&(1/2,1/2)\boxplus(1/2,0)\boxplus(0,1/2)\\
&\qquad\qquad\succeq(1/2,1/2)\boxplus(1/2\ketbra{0}{0},1/2\ketbra{\psi(\pi/4)}{\psi(\pi/4)}). 
\end{align}
Consider the remaining case that $\Phi$ is equal to $\mathrm{Tr}[A]$ or $\mathrm{Tr}[B]$ on commuting pairs. By monotonicity, it follows from \eqref{eq:preparation} that 
\begin{equation}\label{eq:preparationinequality}
    1\leq\frac{1}{2}+\frac{1}{2}\frac{1}{2^z}.
\end{equation} 
Since $z\geq0$, this implies that $z=0$. Hence, using the convention \eqref{eq:define0trA} or \eqref{eq:define0trB}, $\Phi$ is one of the degenerate homomorphisms $\Phi(A,B)=\mathrm{Tr}[A]$ or $\mathrm{Tr}[B]$ for all $(A,B)\in S_{\rm m.r.}$. 

Assume now that ${\mathbb{K}}=\mathbb{R}_+$. Then $\Phi$ equals $\mathrm{Tr}[A]$ or $\mathrm{Tr}[B]$ on commuting pairs. Monotonicity and \eqref{eq:preparation} now yield \eqref{eq:preparationinequality} with the inequality reversed. Since $z\leq0$, it follows that $z=0$. Again, $\Phi$ is one of the degenerate cases $\Phi(A,B)=\mathrm{Tr}[A]$ or $\mathrm{Tr}[B]$ for all $(A,B)\in S_{\rm m.r.}$. 

Next, assume ${\mathbb{K}}=\mathbb{T}\mathbb{R}_+^{\rm op}$. Then $\Phi$ is the highly degenerate $\Phi(A,B)=1$ when $(A,B)\neq 0$ and $\Phi(0,0)=0$ on commuting pairs. Also, $z\geq0$. Using the decomposition \eqref{eq:decompositiontropical} with the convention \eqref{eq:define0otherwise}, we see that when $z=0$ we get the degenerate homomorphism that is equal to $1$ for all non-zero elements in $S_{\rm m.r.}$. When $z>0$, we find that $\Phi$ must be as in \eqref{eq:tropicalz}. 

Finally, assume ${\mathbb{K}}=\mathbb{T}\mathbb{R}_+$. Then $\Phi$ is again the highly degenerate $\Phi(A,B)=1$ when $(A,B)\neq 0$ and $\Phi(0,0)=0$ on commuting pairs. The majorization relation \eqref{eq:preparation} implies that 
\begin{equation}
\label{eq:zrelationship2}
    1\geq\max\left\{1,\frac{1}{2^z}\right\}, 
\end{equation}    
Since $z\leq0$, this implies $z=0$. Hence, using the decomposition \eqref{eq:decompositiontropical} with the convention \eqref{eq:define0otherwise}, we get the degenerate homomorphism that is equal to $1$ for all non-zero elements in $S_{\rm m.r.}$. 

We now turn to studying the monotone derivations on $S_{\rm m.r.}$ at the two degenerate homomorphisms $\Phi(A,B)=\mathrm{Tr}[A]$ or $\mathrm{Tr}[B]$ for all $(A,B)\in S_{\rm m.r.}$. Let $\Delta:S_{\rm m.r.}\rightarrow\mathbb{R}$ be a monotone derivation at $\Phi(A,B)=\mathrm{Tr}[A]$, \sloppy{${(A,B)\in S_{\rm m.r.}}$}. Observe that for any $(A,B)\in S_{\rm m.r.}$, 
\begin{equation}
    (\mathrm{Tr}[A],\mathrm{Tr}[B])\boxplus(1,1)\preceq(A,B)\boxplus(1,1)\preceq(1,1)\boxplus(\mathrm{Tr}[A],0)\boxplus(0,\mathrm{Tr}[B]), 
\end{equation}
where the second majorization is achieved by using a measure-and-prepare channel. By interchangeability, we may assume that $\Delta$ vanishes on commuting pairs. Since the outer left and outer right sides of the above inequalities are commuting pairs, monotonicity and additivity of $\Delta$ yields 
\begin{equation}
    0=\Delta((A,B)\boxplus(1,1))=\Delta(A,B)+\underbrace{\Delta(1,1)}_{=0}. 
\end{equation}
Hence, $\Delta$ vanishes everywhere on $S_{\rm m.r.}$. The same conclusion holds for any derivation at the other degenerate monotone homomorphism $\Phi(A,B)=\mathrm{Tr}[B]$, $(A,B)\in S_{\rm m.r.}$. 

Finally, we show that the maps in \eqref{eq:temperate} and \eqref{eq:tropicalz} are in fact monotone homomorphisms with trivial kernel. Additivity and multiplicativity are immediate from the decompositions \eqref{eq:decompositiontemperate}, \eqref{eq:decompositiontropical} together with the multiplicativity of the factors appearing in the decompositions. Also, they all have a trivial kernel, since for every non-zero $(A,B)\in S_{\rm m.r.}$ there is at least one $k$ such that $\braket{\alpha_k}{\beta_k}\neq0$. The fact that they are all monotone can be seen as follows. The homomorphisms $\Phi_{\alpha,z}$, $\Phi^\mathbb{T}$ give rise to the relative entropies $\hat{D}_{\alpha,z}$, $\hat{D}^\mathbb{T}$ defined in \eqref{eq:alphazexplicit}, \eqref{eq:DT}. Since DPI is known to be satisfied for the $\alpha$-$z$ relative entropies when $\alpha\in(0,1)$ and $z\geq\max\{\alpha,1-\alpha\}$ \cite{Zhang2020} (and hence also for our version with a different prefactor), the pointwise limits 
\begin{equation}
    \hat D^\mathbb{T}=\lim_{z\rightarrow\infty}\hat{D}_{\alpha,z}\ \text{(independent of}\ \alpha\text{)}, 
\end{equation}
and, for $z\geq1$, 
\begin{equation}
    \hat D_{0,z}=\lim_{\alpha\rightarrow0}\hat{D}_{\alpha,z},\quad\hat D_{1,z}=\lim_{\alpha\rightarrow1}\hat{D}_{\alpha,z} 
\end{equation}    
also satisfy DPI. Since these relative entropies satisfy DPI and the prefactors in front of $\log$ are negative, the homomorphisms that they are associated with (namely $\Phi_{\alpha,z}$ for $\alpha\in[0,1]$, $z\geq\max\{\alpha,1-\alpha\}$, and $\Phi^\mathbb{T}$) are monotone according to the opposite ordering of $\mathbb{R}_+^{\rm op}$, $\mathbb{T}\mathbb{R}_+^{\rm op}$. Since 
\begin{equation}
    \Phi_z^\mathbb{T}(A,B)=\left(\Phi^\mathbb{T}(A,B)\right)^z
\end{equation}
for all $(A,B)\in S_{\rm m.r.}$ and $z>0$, we find that $\Phi_z^\mathbb{T}$ for any $z>0$ is also monotone.

\label{rmk:Seo}
For the semiring $S_{\rm e.o.}$ we do not have a complete picture: we know that all monotone homomorphisms in Proposition \ref{prop:monhom} associated with $S_{\rm m.r.}$ are also associated with $S_{\rm e.o.}$, but there might be more. Namely, it is still an open question whether the homomorphisms for $\mathbb{K}=\mathbb{R}_+$ or $\mathbb{R}_+^{\rm op}$ that have the same form as \eqref{eq:temperate}, but with parameters $\alpha=0$, $z<1$, or $\alpha=1$, $z<1$, are monotone or not. The same question of monotonicity can also be asked for the homomorphisms for $\mathbb{K}=\mathbb{T}\mathbb{R}_+$ that are similar to \eqref{eq:tropicalz}, but with $z<0$. Additionally, there might exist monotone derivations that do not vanish everywhere. In the following, we will show that we can rule out the existence of any $\Phi$ other than the aforementioned additional ones or the ones associated with $S_{\rm m.r.}$, using techniques similar to the proof of Proposition \ref{prop:monhom}. We suspect that these additional homomorphisms are in fact not monotone either, since they correspond to parameters $\alpha,z$ for which the $\alpha$-$z$ relative entropy is known not to satisfy DPI for general pairs of quantum states (with some conditions on the support). However, in principle, DPI might be satisfied when restricting to the specific pairs of states we consider in this work. 

Fix a monotone homomorphism $\Phi:S_{\rm e.o.}\rightarrow\mathbb{K}$, where $\mathbb{K}\in\{\mathbb{R}_+,\mathbb{R}_+^{\rm op},\allowbreak\mathbb{T}\mathbb{R}_+,\mathbb{T}\mathbb{R}_+^{\rm op}\}$. First, let us summarize results from \cite{farooq2024} on the monotone homomorphisms and derivations associated to the \emph{matrix majorization semiring of length} $2$, which consists precisely of all commuting pairs in $S_{\rm e.o.}$. When $\mathbb{K}=\mathbb{R}_+^{\rm op}$, $\Phi$ restricts to \eqref{eq:Phitemperate} for some $\alpha\in[0,1]$, on commuting pairs. When $\mathbb{K}=\mathbb{R}_+$, $\Phi$ restricts to \eqref{eq:Phitemperate} for some $\alpha\in(-\infty,0]\cup[1,\infty)$. Note that for $\mathbb{K}=\mathbb{R}_+^{\rm op}$ or $\mathbb{R}_+$ the cases $\alpha=0$, respectively $\alpha=1$, correspond to the degenerate homomorphisms $\mathrm{Tr}[B]$, respectively $\mathrm{Tr}[A]$, for a commuting pair $(A,B)$. When $\mathbb{K}=\mathbb{T}\mathbb{R}_+$, $\Phi$ on commuting pairs restricts to 
\begin{equation}\label{eq:Phitropicalcommuting}
\Phi(A,B)=\max_{1\leq i\leq n}\left(\frac{p_i}{q_i}\right)^\beta, 
\end{equation}
for some $\beta\in\mathbb{R}$. For $\beta=0$, this corresponds to the highly degenerate $\Phi(A,B)=1$ for $(A,B)\neq 0$ a commuting pair and $\Phi(0,0)=0$. When $\mathbb{K}=\mathbb{T}\mathbb{R}_+^{\rm op}$, $\Phi$ always restricts to this highly degenerate case on commuting pairs. The two degenerate homomorphisms $\mathrm{Tr}[A],\mathrm{Tr}[B]$ for commuting pairs $(A,B)$ both have non-zero monotone derivations associated with them (similar in form to the Kullback--Leibler divergence), but we will not use these here. 

Note that the pair on the right-hand side in \eqref{eq:alphazrelationship1} is not inside $S_{\rm e.o.}$. However, for the case $\mathbb{K}=\mathbb{R}_+^{\rm op}$ and $\alpha\in(0,1)$, we can still deduce that $\Phi$ is of the form \eqref{eq:temperate} with $z\geq\max\{\alpha,1-\alpha\}$. To see this, consider again measuring a qubit in a fixed basis $\ket{0},\ket{1}$: 
\begin{equation}
\label{eq:alphazrelationship1eo}
    \left(\,\ketbra{\psi(\pi/4)}{\psi(\pi/4)},\ketbra{\psi(\theta)}{\psi(\theta)}\,\right)\succeq(1/2,\cos^2\theta)\boxplus(1/2,\sin^2\theta), 
\end{equation}
where $\theta\in(0,\pi/2)$, which ensures that the pair on the right-hand side above is in $S_{\rm e.o.}$. Assume $\mathbb{K}=\mathbb{R}_+^{\rm op}$ and $\alpha\in(0,1)$. Using monotonicity of $\Phi$, \eqref{eq:alphazrelationship1eo} yields 
\begin{equation}
\label{eq:alphazrelationship2eo}
    \left(\cos(\theta-\pi/4)\right)^{2z}\leq\frac{1}{2^\alpha}\left((\cos\theta)^{2-2\alpha}+(\sin\theta)^{2-2\alpha}\right) 
\end{equation}
for all $\theta\in(0,\pi/2)$, and by switching around the states in the pairs in \eqref{eq:alphazrelationship1eo}, we have similarly 
\begin{equation}
\label{eq:alphazrelationship3eo}
    \left(\cos(\theta-\pi/4)\right)^{2z}\leq\frac{1}{2^{1-\alpha}}\left((\cos\theta)^{2\alpha}+(\sin\theta)^{2\alpha}\right). 
\end{equation}
Taking the limit $\theta\rightarrow\pi/2$ in the above two inequalities allows us to conclude that $\sloppy{z\geq\max\{\alpha,1-\alpha\}}$ for $\alpha\in(0,1)$. Note that for $\alpha=0$ or $1$, we are not able to use this method to conclude that $z\geq1=\max\{\alpha,1-\alpha\}$. 

Next, assume $\mathbb{K}=\mathbb{R}_+$ and $\alpha\in(-\infty,0)\cup(1,\infty)$. Note that \eqref{eq:alphazrelationship2eo} and \eqref{eq:alphazrelationship3eo} hold with the inequality reversed. Assume $\alpha>1$. When taking the limit $\theta\rightarrow\pi/2$, the left-hand side of \eqref{eq:alphazrelationship2eo} converges to $\frac{1}{2^z}$, but the right-hand side diverges to positive infinity, leading to a contradiction. When $\alpha<0$, a similar argument using \eqref{eq:alphazrelationship3eo} leads to a contradiction. This rules out the existence of any monotone homomorphism on $S_{\rm e.o.}$ associated with $\alpha$ outside $[0,1]$. 

Now, we assume $\mathbb{K}=\mathbb{T}\mathbb{R}_+$ and $\Phi$ is of the form \eqref{eq:Phitropicalcommuting} for some $\beta\neq0$ when restricted to commuting pairs. Now \eqref{eq:alphazrelationship1eo} implies 
\begin{equation}
\label{eq:TR+}
    \left(\cos(\theta-\pi/4)\right)^{2z}\geq\frac{1}{2^\beta}\max\left\{(\cos\theta)^{-2\beta},(\sin\theta)^{-2\beta}\right\} 
\end{equation}
for all $\theta\in(0,\pi/2)$. Assume $\beta>0$. Then for $\theta$ restricted to the smaller interval $[\pi/4,\pi/2)$, 
\begin{equation}
    \left(\cos(\theta-\pi/4)\right)^{2z}\geq\frac{1}{2^\beta}(\cos\theta)^{-2\beta}. 
\end{equation}
When taking the limit $\theta\rightarrow\pi/2$, the left-hand side converges to $\frac{1}{2^z}$, but the right-hand side diverges to positive infinity, leading to a contradiction. When $\beta<0$, an analogous argument where we switch around the states in the pairs in \eqref{eq:alphazrelationship1eo} leads to a contradiction. Note that we cannot rule out the case $\beta=0$ using this method. Hence there might exist monotone homomorphisms that are similar to \eqref{eq:tropicalz}, but with $z<0$. 

Finally, assume $\mathbb{K}=\mathbb{T}\mathbb{R}_+^{\rm op}$. Analogously as in the case of the semiring $S_{\rm m.r.}$, we can conclude that any non-degenerate $\Phi$ must be of the form \eqref{eq:tropicalz} for some $z>0$.

Proposition \ref{prop:puS} tells us that any $(A,B)\in S_{\rm e.o.}$, where $A,B$ have trace $1$ and satisfy $|\braket{\alpha_i}{\beta_i}|<1$ for all $i=1,\ldots,n$, is power universal. We can now show that these are in fact all possible power universals in $S_{\rm e.o.}$, using the tropical monotone homomorphism $\Phi^\mathbb{T}$ defined in \eqref{eq:tropical}. 

    To see this, let $(A,B)\in S_{\rm e.o.}$ be power universal. Then there exists $m\in\mathbb{N}$ such that $(A,B)^{\boxtimes m}\succeq(\ketbra{0}{0},\ketbra{\psi(\pi/4)}{\psi(\pi/4)})$. Hence, 
    \begin{equation}
        \left(\Phi^\mathbb{T}(A,B)\right)^m\leq\Phi^\mathbb{T}(\ketbra{0}{0},\ketbra{\psi(\pi/4)}{\psi(\pi/4)})=1/2<1. 
    \end{equation}
    Therefore, $\Phi^\mathbb{T}(A,B)<1$, from which it follows that $|\braket{\alpha_i}{\beta_i}|<1$ for all $i=1,\ldots,n$.

First, note that satisfying the inequalities in part (i) of the theorem is equivalent to $\hat D_{\alpha,z}(\rho\|\sigma)\geq \hat D_{\alpha,z}(\rho'\|\sigma')$ for all $\alpha\in[0,1]$, $z\geq\max\{\alpha,1-\alpha\}$, and additionally $\hat D^\mathbb{T}(\rho\|\sigma)\geq \hat D^\mathbb{T}(\rho'\|\sigma')$. 

    Also, by Proposition \ref{prop:pumr}, $(\rho,\sigma)$ is power universal if it satisfies \eqref{eq:pu1} and \eqref{eq:pu2}. Note that Theorem \ref{thm:Fritz2022} only requires $(\rho,\sigma)$ to be power universal in the large-sample setting. This is why we require \eqref{eq:pu2} to hold for equivalence of all conditions (i), (ii), (iii). We require property \eqref{eq:pu1} to hold both in the large-sample and catalytic setting since our construction in this proof relies on it. However, since we will invoke Theorem \ref{thm:LS}, $(\rho,\sigma)$ has to satisfy \eqref{eq:pu1} anyway if condition \eqref{eq:LScondition2} is to be met, as explained in Section \ref{sec:exactproof}. 

    (i) $\Rightarrow$ (ii) and (iii): We write
    \begin{equation}
    \rho'=\bigoplus_{i=1}^{n'}p'_i\ketbra{\alpha'_i}{\alpha'_i},\quad\sigma'=\bigoplus_{i=1}^{n'}q'_i\ketbra{\beta'_i}{\beta'_i}, 
    \end{equation}
    with all $\ket{\alpha'_i},\ket{\beta'_i}$ normalized or equal to $0$. Let $J\subseteq[n']$ be the subset of all $i$ where $0<|\braket{\alpha'_i}{\beta'_i}|<1$, which is non-empty since $\rho'$, $\sigma'$ do not commute. One shows analogously as in the discussion above \eqref{eq:pairstandardform} that each pair $(\ketbra{\alpha'_i}{\alpha'_i},\ketbra{\beta'_i}{\beta'_i})$, $i\in J$, is equivalent (according to the equivalence relation $\approx$ defined in Section \ref{sec:definingthesemirings}) to the pair 
    \begin{align}
        \big(\cos^2\theta_i&\ketbra{e_{i,1}}{e_{i,1}}+\cos\theta_i\sin\theta_i\ketbra{e_{i,1}}{e_{i,2}}\\
        &+\cos\theta_i\sin\theta_i\ketbra{e_{i,2}}{e_{i,1}}+\sin^2\theta_i\ketbra{e_{i,2}}{e_{i,2}},\ketbra{e_{i,1}}{e_{i,1}}\big), 
    \end{align}
    for some angle $\theta_i\in(0,\pi/2)$, and $\ket{e_{i,1}},\ket{e_{i,2}}$ an orthonormal basis of a $2$-dimensional Hilbert space. Choose $\eta\in(0,\pi/2)$ such that $\eta<\theta_i$ for all $i\in J$ and $\cos\eta\geq\sqrt{1-\varepsilon}$. For each $i\in J$, we define 
    \begin{equation}
        \ket{\alpha'_{\varepsilon,i}}:=\cos(\theta_i-\eta)\ket{e_{i,1}}+\sin(\theta_i-\eta)\ket{e_{i,2}}, 
    \end{equation}
    and for each $i\in[n']\setminus J$, we define $\ket{\alpha'_{\varepsilon,i}}:=\ket{\alpha'_i}$. Consider 
    \begin{equation}
        \rho'_\varepsilon:=\bigoplus_{i=1}^{n'}p'_i\ketbra{\alpha'_{\varepsilon,i}}{\alpha'_{\varepsilon,i}}. 
    \end{equation}
    One computes that $|\braket{\alpha'_{\varepsilon,i}}{\alpha'_i}|=\cos(\eta)\geq\sqrt{1-\varepsilon}$ for all $i\in J$, hence the fidelity between $\rho'_\varepsilon$ and $\rho'$ satisfies 
    \begin{equation}
        F(\rho'_\varepsilon,\rho')=\left(\sum_{i=1}^{n'} p'_i|\braket{\alpha'_{\varepsilon,i}}{\alpha'_i}|\right)^2\geq1-\varepsilon. 
    \end{equation}

    Also, for all $i\in J$ 
    \begin{equation}
        |\braket{\alpha'_i}{\beta'_i}|=\cos(\theta_i)<\cos(\theta_i-\eta)=|\braket{\alpha'_{\varepsilon,i}}{\beta'_i}|, 
    \end{equation}
    hence for all $\alpha\in[0,1]$, $z\geq\max\{\alpha,1-\alpha\}$ 
    \begin{equation}
        \hat D_{\alpha,z}(\rho\|\sigma)\geq \hat D_{\alpha,z}(\rho'\|\sigma')>\hat D_{\alpha,z}(\rho'_\varepsilon\|\sigma'). 
    \end{equation}

    Assume $\hat D^\mathbb{T}(\rho'\|\sigma')>0$, i.e. $\max_{i=1,\ldots,n'}|\braket{\alpha'_i}{\beta'_i}|^{2}<1$. Then this maximum is obtained by some subspace in $J$, from which it follows that $\max_{i=1,\ldots,n'}|\braket{\alpha'_i}{\beta'_i}|^{2}<\max_{i=1,\ldots,n'}|\braket{\alpha'_{\varepsilon,i}}{\beta'_i}|^{2}$, whence $\hat D^\mathbb{T}(\rho\|\sigma)\geq \hat D^\mathbb{T}(\rho'\|\sigma')>\hat D^\mathbb{T}(\rho'_\varepsilon\|\sigma')$. In case $\hat D^\mathbb{T}(\rho'\|\sigma')=0$, it follows immediately that $\hat D^\mathbb{T}(\rho\|\sigma)>\hat D^\mathbb{T}(\rho'_\varepsilon\|\sigma')$, since $\hat D^\mathbb{T}(\rho\|\sigma)>0$ by \eqref{eq:pu1}. 

    The pairs $(\rho,\sigma)$ and $(\rho'_\varepsilon,\sigma')$ thus satisfy the strict inequalities \eqref{eq:LScondition1} and \eqref{eq:LScondition2} of Theorem \ref{thm:LS}, hence (ii) and (iii) follow. 

    (ii) or (iii) $\Rightarrow$ (i): Using the tensor additivity and the DPI property of the $D_{\alpha,z}$, large-sample majorization as in (ii) implies that for all $\varepsilon>0$ and all $\alpha\in(0,1)$, $z>\max\{\alpha,1-\alpha\}$ 
    \begin{equation}\label{eq:approximateinequality}
        D_{\alpha,z}(\rho\|\sigma)\geq D_{\alpha,z}(\rho'_\varepsilon\|\sigma') 
    \end{equation}
    for a state $\rho'_\varepsilon$ satisfying $F(\rho'_\varepsilon,\rho')\geq1-\varepsilon$. Similarly, the same is implied by catalytic majorization as in (iii). 

    We may assume that $\rho'_\varepsilon$ resides in a Hilbert space $\mathcal{H}'_\varepsilon$ possibly larger than $\mathcal{H}'$ where $\rho'$ and $\sigma'$ operate. Let $P_\varepsilon$ be the projection of $\mathcal{H}'_\varepsilon$ onto $\mathcal{H}'$ and $P_\varepsilon^\perp$ be the projection onto the orthogonal complement of $\mathcal{H}'$ within $\mathcal{H}'_\varepsilon$. Set up the channel $\mathcal{D}_\varepsilon$, $\mathcal{D}_\varepsilon(\tau)=P_\varepsilon\tau P_\varepsilon+P_\varepsilon^\perp\tau P_\varepsilon^\perp$. Denoting $P_\varepsilon\rho'_\varepsilon P_\varepsilon=:{\rho'_\varepsilon}^0$ and $P_\varepsilon^\perp\rho'_\varepsilon P_\varepsilon^\perp=:{\rho'_\varepsilon}^1$, we have $\mathcal{D}_\varepsilon(\rho'_\varepsilon)={\rho'_\varepsilon}^0\oplus{\rho'_\varepsilon}^1$ and $\mathcal{D}_\varepsilon(\sigma')=\sigma'$ when we view $\sigma'$ as a state on $\mathcal{H}'_\varepsilon$.

    Note that $\lim_{\varepsilon\rightarrow0}({\rho'_\varepsilon}^0,\sigma')=(\rho',\sigma')$. 

    Next, for $\alpha\in(0,1)$ and $z>\max\{\alpha,1-\alpha\}$, consider the expression 
    \begin{equation}
        \Psi_{\alpha,z}(\tau,\omega):=\mathrm{Tr}\left[\left(\omega^\frac{1-\alpha}{2z}\tau^\frac{\alpha}{z}\omega^\frac{1-\alpha}{2z}\right)^z\right] 
    \end{equation}
    inside the $\log$ of $D_{\alpha,z}$ as in \eqref{eq:alphazdivergence}. One checks that this is additive under $\oplus$, i.e. $\Psi_{\alpha,z}(\rho_1\oplus\rho_2,\sigma_1\oplus\sigma_2)=\Psi_{\alpha,z}(\rho_1,\sigma_1)+\Psi_{\alpha,z}(\rho_2,\sigma_2)$, and is non-decreasing when applying a quantum channel by the DPI of $D_{\alpha,z}$. Then, these properties and \eqref{eq:approximateinequality} imply 
    \begin{equation}
        \Psi_{\alpha,z}(\rho,\sigma)\leq\Psi_{\alpha,z}(\rho'_\varepsilon,\sigma')\leq\Psi_{\alpha,z}({\rho'_\varepsilon}^0,\sigma')+\underbrace{\Psi_{\alpha,z}({\rho'_\varepsilon}^1,0)}_{=0}. 
    \end{equation}
    Since the $\Psi_{\alpha,z}$ are continuous on pairs of fixed dimension, and $\lim_{\varepsilon\rightarrow0}({\rho'_\varepsilon}^0,\sigma')=(\rho',\sigma')$, we conclude that the inequalities in part (i) hold.

Consider the set $\bar R$, containing the parameter range $R$, defined by 
    \begin{equation}\label{eq:Rbar}
        \bar R:=\big\{\,(\alpha,z)\,|\,\alpha\in[0,1],\ z\geq\max\{\alpha,1-\alpha\}\,\big\}\cup\big\{\,(\alpha,\infty)\,|\,\alpha\in[0,1]\,\big\}, 
    \end{equation}
    and define the injective map $\varphi:\bar R\rightarrow\mathbb{R}^2$ by 
    \begin{equation}
        \varphi(\alpha,z)=\left\{\begin{array}{ll}\big(\alpha,\frac{z}{z+1}\big)&\text{if }z\neq\infty\\
        (\alpha,1)&\text{if }z=\infty\end{array}\right..
    \end{equation}
    We define a topology on $\bar R$ by requiring that $U$ is open in $\bar R$ if and only if $U=\varphi^{-1}(V)$ for some open $V$ in $\mathbb{R}^2$ with the Euclidean topology. The subspace topology that $R$ inherits from $\bar R$ coincides with the Euclidean topology. One checks that the image $\varphi(\bar R)$ is a compact subset of $\mathbb{R}^2$, hence $\bar R$ is compact and Hausdorff. 

    For any $(A,B)\in S_{\rm m.r.}$, the evaluation function $f_{(A,B)}:\bar R\rightarrow\mathbb{R}$ is defined for $(\alpha,z)\in\bar R$ when $z\neq\infty$ by 
    \begin{equation}
        f_{(A,B)}(\alpha,z):=\Phi_{\alpha,z}(A,B)=\sum_{i=1}^n(p_i)^\alpha(q_i)^{1-\alpha}|\braket{\alpha_i}{\beta_i}|^{2z}
    \end{equation}
    and when $z=\infty$ by 
    \begin{equation}
        f_{(A,B)}(\alpha,\infty):=\lim_{z\rightarrow\infty}\Phi_{\alpha,z}(A,B)=\sum_{i\in[n]\,:\,|\braket{\alpha_i}{\beta_i}|=1}(p_i)^\alpha(q_i)^{1-\alpha}, 
    \end{equation} 
    where we used that all $|\braket{\alpha_i}{\beta_i}|\leq1$ to compute the limit. Observe that $f_{(A,B)}\circ\varphi^{-1}:\varphi(\bar R)\rightarrow\mathbb{R}$ is continuous since it is a composition of continuous functions on $\varphi(\bar R)\setminus([0,1]\times\{1\})$, and equals the limiting value on $[0,1]\times\{1\}$. Hence, $f_{(A,B)}$ is continuous. 

    Next, let $\mathcal{A}$ be the $\mathbb{R}$-algebra generated by multiplication of the functions $f_{(A,B)}$, $\sloppy{(A,B)\in S_{\rm m.r.}}$, by real numbers, and finite repetitions of point-wise addition and multiplication. Then $\mathcal{A}$ is a subalgebra of $C(\bar R,\mathbb{R})$, the set of all continuous real-valued functions on $\bar R$. 

    Observe that $f_{(1,1)}(\alpha,z)=1$ for all $(\alpha,z)\in\bar R$, hence $\mathcal{A}$ contains a non-zero constant function. Clearly, for every two distinct $(\alpha,z),(\alpha',z')\in\bar R$ there exists a pair $\sloppy{(A,B)\in S_{\rm m.r.}}$ such that $f_{(A,B)}(\alpha,z)\neq f_{(A,B)}(\alpha',z')$, hence $\mathcal{A}$ separates points. Therefore, by the Stone-Weierstrass theorem, $\mathcal{A}$ is dense in $C(\bar R,\mathbb{R})$. 

    The non-empty open subset $O$ in the statement of the theorem contains an open ball, and without loss of generality we assume $O$ to be equal to an open ball. Clearly, there exists a continuous function $f:\bar R\rightarrow\mathbb{R}$ such that $f(\alpha,z)=1$ for all $(\alpha,z)$ outside $O$, and $f(\alpha_0,z_0)=-1$ for some $(\alpha_0,z_0)$ in $O$. Since $\mathcal{A}$ is dense in $C(\bar R,\mathbb{R})$, $f$ can be approximated by functions in $\mathcal{A}$ with arbitrary precision, from which it follows that there exist $r_1,\ldots,r_t\in\mathbb{R}$ and $(A_1,B_1),\ldots,(A_t,B_t)\in S_{\rm m.r.}$ such that 
    \begin{equation}\label{eq:SWapproximation}
        r_1\Phi_{\alpha,z}(A_1,B_1)+\ldots+r_t\Phi_{\alpha,z}(A_t,B_t)\left\{\begin{array}{ll}>0&\text{if }\ (\alpha,z)\in R\setminus O\\<0&\text{if }\ (\alpha,z)=(\alpha_0,z_0)\end{array}\right..
    \end{equation}
    Here we have used the multiplicativity of the homomorphisms, which implies that $\mathcal{A}$ is the span of the set of all $f_{(A,B)}$, $(A,B)\in S_{\rm m.r.}$, with real coefficients. 
    Define the pairs 
    \begin{align}
        &(A',B'):=\left(\bigoplus_{i\,:\,r_i>0}r_iA_i,\bigoplus_{i\,:\,r_i>0}r_iB_i\right),\\
        &(A,B):=\left(\bigoplus_{i\,:\,r_i<0}-r_iA_i,\bigoplus_{i\,:\,r_i<0}-r_iB_i\right). 
    \end{align}
    Then, by rearranging \eqref{eq:SWapproximation}, if $(\alpha,z)\in R\setminus O$, 
    \begin{equation}\label{eq:counterexample1}
        \Phi_{\alpha,z}(A',B')>\Phi_{\alpha,z}(A,B),  
    \end{equation}
    and 
    \begin{equation}\label{eq:counterexample2}
        \Phi_{\alpha_0,z_0}(A',B')<\Phi_{\alpha_0,z_0}(A,B). 
    \end{equation}
    Note that it follows in particular that both pairs $(A,B),(A',B')$ are non-zero. 

    If $(A,B)$ is not non-parallel, i.e. there are $i$ such that $|\braket{\alpha_i}{\beta_i}|=1$, then for such $i$ we may rotate $\ket{\alpha_i},\ket{\beta_i}$ to ensure that $|\braket{\alpha_i}{\beta_i}|<1$. By doing so, $\Phi_{\alpha,z}(A,B)$ may decrease, hence \eqref{eq:counterexample1} remains true. By ensuring that the rotations are sufficiently small, \eqref{eq:counterexample2} also remains true. We conclude that we may assume that $(A,B)$ is non-parallel. 

    If $(A',B')$ is a commuting pair, i.e. $|\braket{\alpha_i}{\beta_i}|=1$ for all $i$, then $\Phi_{\alpha_0,z}(A',B')$ does not depend on $z$. However, $\Phi_{\alpha_0,z}(A,B)$ is strictly decreasing in $z$. We may assume that $O$ is a sufficiently small open ball such that there exists $z_1\in\mathbb{R}$ with $(\alpha_0,z_1)\in R\setminus O$ and $z_1<z_0$. There also exists $z_2\in\mathbb{R}$ with $(\alpha_0,z_2)\in R\setminus O$ and $z_0<z_2$. Then \eqref{eq:counterexample1} implies that both $\Phi_{\alpha_0,z_1}(A,B)$ and $\Phi_{\alpha_0,z_2}(A,B)$ are strictly less than the constant $\Phi_{\alpha_0,z_0}(A',B')$. Since $\Phi_{\alpha_0,z_0}(A,B)>\Phi_{\alpha_0,z_0}(A',B')$, this contradicts the fact that $\Phi_{\alpha_0,z}(A,B)$ is strictly decreasing in $z$. In conclusion, $(A',B')$ is not a commuting pair. 

    We add an orthogonal component to both pairs as follows: 
    \begin{align}
        &(\tilde{A},\tilde{B}):=(A,B)\boxplus(a\ketbra{0}{0},b\ketbra{1}{1}),\\
        &(\tilde{A'},\tilde{B'}):=(A',B')\boxplus(a'\ketbra{0}{0},b'\ketbra{1}{1}), 
    \end{align}
    with $a,b>0$, $a',b'\geq0$ chosen such that 
    \begin{equation}
        T:=\mathrm{Tr}{\tilde{A}}=\mathrm{Tr}{\tilde{B}}=\mathrm{Tr}{\tilde{A'}}=\mathrm{Tr}{\tilde{B'}}. 
    \end{equation}
    The pairs $(\rho,\sigma):=(\tilde{A},\tilde{B})/T$ and $(\rho',\sigma'):=(\tilde{A'},\tilde{B'})/T$ are in $\mathcal{F}$, and the former is non-parallel and the latter is not commutative. Since $a,b>0$, $(\rho,\sigma)$ additionally satisfies \eqref{eq:pu2}. Note that 
    \begin{align}
        &\Phi_{\alpha,z}(\rho,\sigma)=T^{-1}\Phi_{\alpha,z}(\tilde{A},\tilde{B})=T^{-1}\Phi_{\alpha,z}(A,B),\\
        &\Phi_{\alpha,z}(\rho',\sigma')=T^{-1}\Phi_{\alpha,z}(\tilde{A'},\tilde{B'})=T^{-1}\Phi_{\alpha,z}(A',B')
    \end{align}    
    for all $(\alpha,z)\in R$. Hence, it follows from \eqref{eq:counterexample1}, \eqref{eq:counterexample2} that 
    \begin{equation}\label{eq:contradiction}
        \Phi_{\alpha,z}(\rho',\sigma')>\Phi_{\alpha,z}(\rho,\sigma) 
    \end{equation}
    for all $(\alpha,z)\in R\setminus O$ and the reverse inequality for $(\alpha,z)=(\alpha_0,z_0)$.

    Now, \eqref{eq:contradiction} for all $(\alpha,z)\in R\setminus O$ implies the conditions \eqref{eq:smallercondition}. However, (ii) and (iii) in Theorem \ref{thm:approximateLS} are both false: if either were true, then they would imply (i), which contradicts the fact that \eqref{eq:contradiction} with the reverse inequality is true for $(\alpha,z)=(\alpha_0,z_0)$.
